def visible_revision_case_specs() -> tuple[tuple[str, str, str, tuple[str, ...]], ...]:
    cases: list[tuple[str, str, str, tuple[str, ...]]] = []
    for code in VISIBLE_REVISION_CODES:
        lowered = code.lower()
        if code == "SCB_DIGEST_MISMATCH":
            cases.extend(
                (
                    (
                        "receipt_scb_digest_mismatch",
                        code,
                        "commit.codec.scb",
                        ("TransactionCodecError",),
                    ),
                    (
                        "object_scb_digest_mismatch",
                        code,
                        "commit.store",
                        ("StoreError",),
                    ),
                    (
                        "state_root_scb_digest_mismatch",
                        code,
                        "commit.codec.state_root.scb",
                        ("TransactionCodecError",),
                    ),
                    (
                        "policy_root_scb_digest_mismatch",
                        code,
                        "commit.codec.policy_root.scb",
                        ("TransactionCodecError",),
                    ),
                )
            )
        elif code == "SCHEMA_EPOCH_MISMATCH":
            cases.extend(
                (
                    (
                        "state_schema_epoch_mismatch",
                        code,
                        "commit.codec.state_root.schema",
                        ("TransactionCodecError",),
                    ),
                    (
                        "policy_schema_epoch_mismatch",
                        code,
                        "commit.codec.policy_root.schema",
                        ("TransactionCodecError",),
                    ),
                )
            )
        elif code == "TXN_OBJECT_INVENTORY_MISMATCH":
            cases.extend(
                (
                    (
                        "receipt_txn_object_inventory_mismatch",
                        code,
                        "commit.codec.transaction",
                        ("TransactionCodecError",),
                    ),
                    (
                        "repository_txn_object_inventory_mismatch",
                        code,
                        "commit.transaction",
                        (),
                    ),
                )
            )
        elif code == "TXN_IO":
            cases.append(("host_txn_io", code, "commit.io", ("io::Error(Other)",)))
        elif code == "TXN_RESOURCE_LIMIT":
            cases.append(
                (
                    "codec_txn_resource_limit",
                    code,
                    "commit.codec.transaction",
                    ("TransactionCodecError",),
                )
            )
        elif code == "SCB_LABEL_NOT_NFC":
            continue
        elif code in {
            "SCB_CONTRACT_UNKNOWN",
            "SCB_EPOCH_MISMATCH",
            "SCB_FIELD_ORDER",
            "SCB_MAP_ORDER",
            "SCB_MAP_DUPLICATE",
        }:
            cases.append(
                (
                    f"state_root_{lowered}",
                    code,
                    "commit.codec.state_root.scb",
                    ("TransactionCodecError",),
                )
            )
        elif code in {
            "SCB_BOOL_INVALID",
            "SCB_UTF8_INVALID",
            "SCB_FLOAT_NON_CANONICAL",
        }:
            cases.append(
                (
                    f"candidate_{lowered}",
                    code,
                    "commit.codec.candidate",
                    ("TransactionCodecError",),
                )
            )
        elif code.startswith("SCB_"):
            cases.append(
                (
                    f"receipt_{lowered}",
                    code,
                    "commit.codec.scb",
                    ("TransactionCodecError",),
                )
            )
        elif code.startswith("STORE_"):
            if code == "STORE_IO":
                chain = ("StoreError", "io::Error(Other)")
            elif code == "STORE_OBJECT_NOT_FOUND":
                chain = ("StoreError", "io::Error(NotFound)")
            else:
                chain = ("StoreError",)
            cases.append((f"object_{lowered}", code, "commit.store", chain))
        elif code.startswith("MUTATION_CANDIDATE_"):
            expected_code = (
                "SCB_UNION_INVALID"
                if code
                in {
                    "MUTATION_CANDIDATE_DESCRIPTOR_UNKNOWN",
                    "MUTATION_CANDIDATE_PAYLOAD_KIND",
                }
                else code
            )
            cases.append(
                (
                    f"candidate_{lowered}",
                    expected_code,
                    "commit.codec.candidate",
                    ("TransactionCodecError",),
                )
            )
        elif code.startswith("CANDIDATE_RESULT_"):
            cases.append(
                (
                    f"candidate_result_{lowered}",
                    code,
                    "commit.codec.candidate_result",
                    ("TransactionCodecError",),
                )
            )
        elif code.startswith("STATE_ROOT_"):
            cases.append(
                (
                    f"state_{lowered}",
                    code,
                    "commit.codec.state_root.semantic",
                    ("TransactionCodecError",),
                )
            )
        elif code.startswith("POLICY_ROOT_"):
            cases.append(
                (
                    f"policy_{lowered}",
                    code,
                    "commit.codec.policy_root.semantic",
                    ("TransactionCodecError",),
                )
            )
        elif code == "RECOVERY_RECEIPT_INCOMPLETE":
            cases.append(
                (
                    "repository_recovery_receipt_incomplete",
                    code,
                    "commit.transaction",
                    (),
                )
            )
        else:
            cases.append(
                (
                    f"receipt_{lowered}",
                    code,
                    "commit.codec.transaction",
                    ("TransactionCodecError",),
                )
            )
    return tuple(cases)


