def grouped_cor06_cases() -> dict[
    str, tuple[tuple[str, str, str, tuple[str, ...]], ...]
]:
    groups: dict[str, list[tuple[str, str, str, tuple[str, ...]]]] = {
        "head_checksum": [
            (
                "head_shape_before_receipt_missing",
                "REF_HEAD_CORRUPT",
                "commit.transaction",
                (),
            ),
            (
                "head_checksum_before_receipt_corrupt",
                "REF_HEAD_CORRUPT",
                "commit.transaction",
                (),
            ),
        ],
        "receipt_missing": [],
        "receipt_digest": [],
        "root": [],
        "policy": [],
        "object_missing": [],
        "object_digest": [],
        "manifest_length": [],
    }
    for case in VISIBLE_REVISION_CASES:
        name, code, variant, _source_chain = case
        if name == "repository_recovery_receipt_incomplete":
            group = "receipt_missing"
        elif ".state_root." in variant:
            group = "root"
        elif ".policy_root." in variant:
            group = "policy"
        elif code == "STORE_OBJECT_NOT_FOUND":
            group = "object_missing"
        elif variant == "commit.store":
            group = "object_digest"
        elif name == "repository_txn_object_inventory_mismatch":
            group = "manifest_length"
        else:
            group = "receipt_digest"
        groups[group].append(case)
    return {group: tuple(cases) for group, cases in groups.items()}


