def grouped_error_case_record(
    cases: dict[
        str,
        dict[str, tuple[tuple[str, str, str, tuple[str, ...]], ...]],
    ] = GROUPED_ERROR_CASES,
) -> tuple[tuple[str, str, str, str, str, tuple[str, ...]], ...]:
    return tuple(
        (row_id, group_id, leaf_id, code, variant, source_chain)
        for row_id, groups in cases.items()
        for group_id, leaves in groups.items()
        for leaf_id, code, variant, source_chain in leaves
    )


def grouped_error_cases_sha256(
    cases: dict[
        str,
        dict[str, tuple[tuple[str, str, str, tuple[str, ...]], ...]],
    ] = GROUPED_ERROR_CASES,
) -> str:
    payload = json.dumps(
        grouped_error_case_record(cases),
        ensure_ascii=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


class CorruptionFixtureSpec(NamedTuple):
    owner_source: str
    fixture_family: str
    recovery_operation: str
    expected_code: str
    expected_variant: str
    expected_source_chain: tuple[str, ...]
    target_role: str
    artifact_role: str
    identity_recipe: str
    path_recipe: str
    corrupter_class: str
    probe_class: str
