def corruption_fixture_specs() -> dict[tuple[str, str, str], CorruptionFixtureSpec]:
    visible_by_name = {case[0]: case for case in VISIBLE_REVISION_CASES}
    specs: dict[tuple[str, str, str], CorruptionFixtureSpec] = {}
    for row_id, groups in GROUPED_ERROR_CASES.items():
        for group_id, leaves in groups.items():
            for leaf_id, code, variant, source_chain in leaves:
                key = (row_id, group_id, leaf_id)
                if row_id == "COR-06" and group_id == "head_checksum":
                    specs[key] = CorruptionFixtureSpec(
                        owner_source="crates/sley-txn/src/repository.rs",
                        fixture_family="accepted_head_pointer",
                        recovery_operation="transaction_recovery",
                        expected_code=code,
                        expected_variant=variant,
                        expected_source_chain=source_chain,
                        target_role="ACCEPTED_POINTER",
                        artifact_role="accepted_pointer",
                        identity_recipe="transaction_repository_owner_root",
                        path_recipe="accepted_pointer_path",
                        corrupter_class=HEAD_POINTER_FIXTURE_RECIPES[leaf_id],
                        probe_class="decode_accepted_pointer_error",
                        selector=leaf_id,
                        required_facts=HEAD_POINTER_REQUIRED_FACTS,
                    )
                    continue
                visible_name: str | None = None
                role: str | None = None
                if row_id == "COR-06" and leaf_id in visible_by_name:
                    visible_name = leaf_id
                    role = "ACCEPTED_REVISION"
                elif row_id == "COR-07" and group_id == "target_transaction":
                    candidate = leaf_id.removeprefix("target_")
                    if candidate in visible_by_name:
                        visible_name = candidate
                        role = "BRANCH_HEAD_REVISION"
                elif row_id == "COR-07" and group_id == "origin_ancestry_binding":
                    candidate = leaf_id.removeprefix("origin_")
                    if candidate in visible_by_name:
                        visible_name = candidate
                        role = "BRANCH_ORIGIN_REVISION"
                if visible_name is not None and role is not None:
                    specs[key] = visible_revision_fixture_spec(
                        row_id,
                        code,
                        variant,
                        source_chain,
                        role,
                        visible_by_name[visible_name],
                    )
                    continue
                try:
                    recipe = REF_OWNER_FIXTURE_RECIPES[leaf_id]
                except KeyError:
                    fail(f"grouped corruption fixture recipe is absent: {key!r}")
                specs[key] = CorruptionFixtureSpec(
                    owner_source="crates/sley-repo/src/refs.rs",
                    fixture_family="ref_owner",
                    recovery_operation="ref_recovery",
                    expected_code=code,
                    expected_variant=variant,
                    expected_source_chain=source_chain,
                    target_role=recipe[0],
                    artifact_role=recipe[1],
                    identity_recipe=recipe[2],
                    path_recipe=recipe[3],
                    corrupter_class=recipe[4],
                    probe_class=recipe[5],
                    selector=leaf_id,
                    required_facts=REF_OWNER_REQUIRED_FACTS_BY_LEAF[leaf_id],
                )
    return specs


CORRUPTION_FIXTURE_SPECS = corruption_fixture_specs()


def corruption_fixture_spec_record(
    specs: dict[tuple[str, str, str], CorruptionFixtureSpec] = (
        CORRUPTION_FIXTURE_SPECS
    ),
) -> tuple[tuple[object, ...], ...]:
    return tuple(
        (
            *key,
            spec.owner_source,
            spec.fixture_family,
            spec.recovery_operation,
            spec.expected_code,
            spec.expected_variant,
            spec.expected_source_chain,
            spec.target_role,
            spec.artifact_role,
            spec.identity_recipe,
            spec.path_recipe,
            spec.corrupter_class,
            spec.probe_class,
            spec.selector,
            spec.required_facts,
            spec.distinct_from_roles,
        )
        for key, spec in specs.items()
    )


def corruption_fixture_specs_sha256(
    specs: dict[tuple[str, str, str], CorruptionFixtureSpec] = (
        CORRUPTION_FIXTURE_SPECS
    ),
) -> str:
    payload = json.dumps(
        corruption_fixture_spec_record(specs),
        ensure_ascii=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


