def fault_overlay(
    role: str,
    identity_recipe: str,
    path_recipe: str,
    corrupter_class: str,
    probe_class: str,
    *required_facts: str,
) -> FaultOverlay:
    return FaultOverlay(
        role,
        identity_recipe,
        path_recipe,
        corrupter_class,
        probe_class,
        required_facts,
    )


def code_error_authority(
    code: str,
    variant: str,
    source_chain: tuple[str, ...] = (),
) -> ErrorAuthority:
    return ErrorAuthority("code", code, variant, source_chain)


def enum_error_authority(
    variant: str,
    fields: tuple[tuple[str, int], ...] = (),
) -> ErrorAuthority:
    return ErrorAuthority("enum_fields", None, variant, (), fields)


