def require_dependency_direction() -> None:
    root_manifest = tomllib.loads((ROOT / "Cargo.toml").read_text(encoding="utf-8"))
    workspace = root_manifest.get("workspace", {})
    workspace_dependencies = (
        workspace.get("dependencies", {}) if isinstance(workspace, dict) else {}
    )
    if not isinstance(workspace_dependencies, dict):
        fail("root workspace dependencies are not a TOML table")

    def packages(crate: str) -> set[str]:
        path = ROOT / f"crates/{crate}/Cargo.toml"
        manifest = tomllib.loads(path.read_text(encoding="utf-8"))
        found: set[str] = set()

        def add_table(table: object) -> None:
            if not isinstance(table, dict):
                return
            for alias, declaration in table.items():
                package = alias
                if isinstance(declaration, dict):
                    if declaration.get("workspace") is True:
                        inherited = workspace_dependencies.get(alias)
                        if isinstance(inherited, dict):
                            package = inherited.get("package", alias)
                        else:
                            package = alias
                    else:
                        package = declaration.get("package", alias)
                if isinstance(package, str):
                    found.add(package)

        for key in ("dependencies", "dev-dependencies", "build-dependencies"):
            add_table(manifest.get(key))
        targets = manifest.get("target", {})
        if isinstance(targets, dict):
            for target in targets.values():
                if isinstance(target, dict):
                    for key in (
                        "dependencies",
                        "dev-dependencies",
                        "build-dependencies",
                    ):
                        add_table(target.get(key))
        return found

    store_dependencies = packages("sley-store")
    txn_dependencies = packages("sley-txn")
    repo_dependencies = packages("sley-repo")
    if "sley-txn" not in repo_dependencies or "sley-store" not in txn_dependencies:
        fail("required sley-repo -> sley-txn -> sley-store edges differ")
    if "sley-repo" in txn_dependencies or "sley-repo" in store_dependencies:
        fail("a resolved reverse dependency on sley-repo is present")
    if "sley-txn" in store_dependencies:
        fail("sley-store unexpectedly depends on sley-txn")


def s20_530_test_feature_tables_problem(
    txn_manifest: object,
    repo_manifest: object,
) -> str | None:
    if not isinstance(txn_manifest, dict) or not isinstance(repo_manifest, dict):
        return "test-hook manifest authority is not two TOML objects"
    if txn_manifest.get("features") != {"s20-530-test-hooks": []}:
        return "sley-txn test-hook feature table differs"
    dependencies = repo_manifest.get("dependencies")
    development = repo_manifest.get("dev-dependencies")
    if not isinstance(dependencies, dict) or not isinstance(development, dict):
        return "sley-repo dependency tables differ"
    if dependencies.get("sley-txn") != {"path": "../sley-txn"}:
        return "normal sley-repo to sley-txn dependency gained feature authority"
    if development.get("sley-txn") != {
        "path": "../sley-txn",
        "features": ["s20-530-test-hooks"],
    }:
        return "sley-repo dev dependency lacks the exact test-hook feature"
    return None


def s20_530_test_feature_manifest_problem() -> str | None:
    txn_path = ROOT / "crates/sley-txn/Cargo.toml"
    repo_path = ROOT / "crates/sley-repo/Cargo.toml"
    try:
        txn_manifest = tomllib.loads(txn_path.read_text(encoding="utf-8"))
        repo_manifest = tomllib.loads(repo_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, tomllib.TOMLDecodeError) as error:
        return f"cannot parse S20-530 test-hook manifests: {error}"
    if problem := s20_530_test_feature_tables_problem(txn_manifest, repo_manifest):
        return problem
    allowed = {txn_path, repo_path}
    for path in sorted(ROOT.glob("crates/*/Cargo.toml")):
        if path in allowed:
            continue
        try:
            payload = path.read_text(encoding="utf-8", errors="strict")
        except (OSError, UnicodeDecodeError) as error:
            return f"cannot read manifest {path.relative_to(ROOT)}: {error}"
        if "s20-530-test-hooks" in payload:
            return f"test-hook feature is enabled by {path.relative_to(ROOT)}"
    try:
        root_payload = (ROOT / "Cargo.toml").read_text(
            encoding="utf-8",
            errors="strict",
        )
    except (OSError, UnicodeDecodeError) as error:
        return f"cannot read root manifest for test-hook closure: {error}"
    if "s20-530-test-hooks" in root_payload:
        return "workspace root gains S20-530 test-hook authority"
    return None


def native_lib_harness_problem(manifest: bytes) -> str | None:
    try:
        parsed = tomllib.loads(manifest.decode("utf-8", errors="strict"))
    except (UnicodeDecodeError, tomllib.TOMLDecodeError) as error:
        return f"manifest is not strict TOML: {error}"
    library = parsed.get("lib", {})
    if not isinstance(library, dict):
        return "[lib] is not a table"
    if set(library) - {"path"}:
        return "[lib] contains a target or harness override"
    if library.get("path", "src/lib.rs") != "src/lib.rs":
        return "[lib] path does not resolve through exact src/lib.rs"
    return None


def owner_manifest_build_authority_problem(manifest: bytes) -> str | None:
    try:
        parsed = tomllib.loads(manifest.decode("utf-8", errors="strict"))
    except (UnicodeDecodeError, tomllib.TOMLDecodeError) as error:
        return f"manifest is not strict TOML: {error}"
    package = parsed.get("package", {})
    if not isinstance(package, dict):
        return "[package] is not a table"
    if "build" in package:
        return "[package].build authority is forbidden"
    if "build-dependencies" in parsed:
        return "owner build dependencies are forbidden"
    targets = parsed.get("target", {})
    if not isinstance(targets, dict):
        return "[target] is not a table"
    for target, table in targets.items():
        if not isinstance(table, dict):
            return f"target {target!r} is not a table"
        if "build-dependencies" in table:
            return f"target {target!r} build dependencies are forbidden"
    return None


def owner_source_external_authority_problem(source: str, relative: str) -> str | None:
    projected = rust_code_projection(source)
    owner_lib_roots = {
        "crates/sley-store/src/lib.rs",
        "crates/sley-txn/src/lib.rs",
        "crates/sley-repo/src/lib.rs",
    }
    allowed_doc_includes: list[tuple[int, int]] = []
    for match in re.finditer(r"#\s*!\s*\[", projected):
        attribute = rust_attribute_end(source, match.start())
        if attribute is None:
            return "unterminated Rust inner attribute"
        end, normalized = attribute
        if normalized != 'doc=include_str!("../README.md")':
            continue
        if relative not in owner_lib_roots:
            return "README doc include is not in an owner crate root"
        if brace_depth_at(projected, [True] * len(projected), match.start()) != 0:
            return "README doc include is not a crate-root inner attribute"
        allowed_doc_includes.append((match.start(), end))
    if relative in owner_lib_roots and len(allowed_doc_includes) != 1:
        return "owner crate root lacks exactly one README doc include"
    if allowed_doc_includes:
        output = list(projected)
        for start, end in allowed_doc_includes:
            for index in range(start, end):
                if output[index] != "\n":
                    output[index] = " "
        projected = "".join(output)
    forbidden_macros = re.findall(
        r"\b(include|include_str|include_bytes|env|option_env)\s*!\s*\(",
        projected,
    )
    if forbidden_macros:
        return f"external-input macro authority is forbidden: {forbidden_macros[0]}!"
    for use in re.finditer(
        r"\b(?:pub(?:\([^)]*\))?\s+)?use\s+(?P<body>.*?);",
        projected,
        re.DOTALL,
    ):
        imported = re.search(
            r"\b(include|include_str|include_bytes|env|option_env)\b",
            use["body"],
        )
        if imported is not None:
            return f"external-input macro import is forbidden: {imported[1]}"
    for match in re.finditer(r"#\s*!?\s*\[", projected):
        attribute = rust_attribute_end(projected, match.start())
        if attribute is None:
            return "unterminated Rust attribute"
        _end, normalized = attribute
        if "path=" in normalized:
            return "#[path] module authority is forbidden"
    return None


def declared_input_path_problem(
    source_root: Path,
    input_paths: frozenset[str],
    base: Path,
    declared: str,
    label: str,
) -> str | None:
    if not declared or "\0" in declared:
        return f"{label} is empty or contains NUL"
    candidate = Path(declared)
    if candidate.is_absolute():
        return f"{label} is absolute: {declared!r}"
    root = source_root.resolve(strict=False)
    resolved = (base / candidate).resolve(strict=False)
    try:
        relative = resolved.relative_to(root).as_posix()
    except ValueError:
        return f"{label} escapes the workspace snapshot: {declared!r}"
    if relative in {"", "."}:
        return None if input_paths else f"{label} resolves to an empty snapshot"
    if relative in input_paths:
        return None
    prefix = f"{relative.rstrip('/')}/"
    if any(path.startswith(prefix) for path in input_paths):
        return None
    return f"{label} is absent from the hashed workspace inputs: {relative}"


def local_source_url_problem(value: str, label: str) -> str | None:
    normalized = value.strip().lower()
    scheme = normalized.split(":", 1)[0] if ":" in normalized else ""
    if (
        scheme == "file"
        or scheme.endswith("+file")
        or normalized.startswith(("/", "./", "../", "~/", "\\\\"))
        or re.match(r"^[a-z]:[\\/]", normalized)
    ):
        return f"{label} names an external local source: {value!r}"
    return None


def cargo_manifest_execution_path_problem(
    source_root: Path,
    relative: str,
    input_paths: frozenset[str],
) -> str | None:
    path = source_root / relative
    try:
        parsed = tomllib.loads(path.read_text(encoding="utf-8", errors="strict"))
    except (OSError, UnicodeDecodeError, tomllib.TOMLDecodeError) as error:
        return f"cannot parse {relative}: {error}"
    base = path.parent

    def validate(value: object, label: str) -> str | None:
        if not isinstance(value, str):
            return f"{label} is not text"
        return declared_input_path_problem(source_root, input_paths, base, value, label)

    def walk(value: object, trail: tuple[str, ...] = ()) -> str | None:
        if isinstance(value, dict):
            for key, child in value.items():
                child_trail = (*trail, str(key))
                label = f"{relative} {'.'.join(child_trail)}"
                if key == "path":
                    if problem := validate(child, label):
                        return problem
                if key in {"git", "registry", "url"} and isinstance(child, str):
                    if problem := local_source_url_problem(child, label):
                        return problem
                if trail == ("package",) and key in {
                    "build",
                    "workspace",
                    "readme",
                    "license-file",
                }:
                    if isinstance(child, str) and (problem := validate(child, label)):
                        return problem
                if trail == ("workspace",) and key in {
                    "members",
                    "default-members",
                    "exclude",
                }:
                    if not isinstance(child, list) or not all(
                        isinstance(item, str) for item in child
                    ):
                        return f"{label} is not a text array"
                    for item in child:
                        assert isinstance(item, str)
                        if any(marker in item for marker in ("*", "?", "[", "]")):
                            return f"{label} uses a workspace glob: {item!r}"
                        if problem := validate(item, label):
                            return problem
                if problem := walk(child, child_trail):
                    return problem
        elif isinstance(value, list):
            for child in value:
                if problem := walk(child, trail):
                    return problem
        return None

    return walk(parsed)


def rust_external_input_problem(
    source_root: Path,
    relative: str,
    input_paths: frozenset[str],
) -> str | None:
    path = source_root / relative
    try:
        source = path.read_text(encoding="utf-8", errors="strict")
    except (OSError, UnicodeDecodeError) as error:
        return f"cannot parse Rust source {relative}: {error}"
    mask = rust_code_mask(source)
    macro_pattern = re.compile(
        r"\b(?P<macro>include|include_str|include_bytes)\s*!\s*\("
    )
    literal_pattern = re.compile(r'\s*"(?P<path>[^"\\\r\n]*)"\s*')
    for match in macro_pattern.finditer(source):
        if not mask[match.start()]:
            continue
        opening = source.find("(", match.start(), match.end())
        closing = matching_delimiter(source, mask, opening, "(", ")")
        if closing is None:
            return f"{relative} has an unterminated {match['macro']}! input"
        literal = literal_pattern.fullmatch(source[opening + 1 : closing])
        if literal is None:
            return f"{relative} {match['macro']}! input is not one exact literal path"
        if match["macro"] == "include" and Path(literal["path"]).suffix != ".rs":
            return f"{relative} include! target is not an exact .rs input"
        if problem := declared_input_path_problem(
            source_root,
            input_paths,
            path.parent,
            literal["path"],
            f"{relative} {match['macro']}!",
        ):
            return problem

    projected = rust_code_projection(source)
    for match in re.finditer(r"#\s*!?\s*\[", projected):
        attribute = rust_attribute_end(projected, match.start())
        if attribute is None:
            return f"{relative} has an unterminated Rust attribute"
        end, normalized = attribute
        if "path=" not in normalized:
            continue
        raw = source[match.start() : end]
        literals = re.findall(r'\bpath\s*=\s*"([^"\\\r\n]*)"', raw)
        if not literals:
            return f"{relative} has a nonliteral Rust path attribute"
        for declared in literals:
            if Path(declared).suffix != ".rs":
                return f"{relative} #[path] target is not an exact .rs input"
            if problem := declared_input_path_problem(
                source_root,
                input_paths,
                path.parent,
                declared,
                f"{relative} #[path]",
            ):
                return problem
    return None


def python_local_source_problem(
    source_root: Path,
    relative: str,
    input_paths: frozenset[str],
) -> str | None:
    path = source_root / relative
    try:
        parsed = tomllib.loads(path.read_text(encoding="utf-8", errors="strict"))
    except (OSError, UnicodeDecodeError, tomllib.TOMLDecodeError) as error:
        return f"cannot parse {relative}: {error}"
    base = path.parent

    def validate(value: object, label: str) -> str | None:
        if not isinstance(value, str):
            return f"{label} is not text"
        return declared_input_path_problem(source_root, input_paths, base, value, label)

    def validate_array(value: object, label: str) -> str | None:
        if not isinstance(value, list) or not all(
            isinstance(item, str) for item in value
        ):
            return f"{label} is not a local-path array"
        for item in value:
            assert isinstance(item, str)
            if problem := validate(item, label):
                return problem
        return None

    def walk(value: object, trail: tuple[str, ...] = ()) -> str | None:
        if isinstance(value, dict):
            for key, child in value.items():
                child_trail = (*trail, str(key))
                label = f"{relative} {'.'.join(child_trail)}"
                if key in {"path", "directory", "editable"}:
                    if problem := validate(child, label):
                        return problem
                if key in {
                    "file",
                    "license-file",
                    "license_file",
                    "readme",
                }:
                    if isinstance(child, str) and (problem := validate(child, label)):
                        return problem
                    if isinstance(child, list) and (
                        problem := validate_array(child, label)
                    ):
                        return problem
                    if not isinstance(child, (str, list, dict)):
                        return f"{label} is not a local path or path table"
                if key in {"git", "registry", "url"} and isinstance(child, str):
                    if problem := local_source_url_problem(child, label):
                        return problem
                if key in {
                    "backend-path",
                    "exclude",
                    "license-files",
                    "license_files",
                    "members",
                    "packages",
                    "script-files",
                    "script_files",
                }:
                    if isinstance(child, str):
                        if problem := validate(child, label):
                            return problem
                    elif problem := validate_array(child, label):
                        return problem
                if problem := walk(child, child_trail):
                    return problem
        elif isinstance(value, list):
            for child in value:
                if isinstance(child, str):
                    target = child.strip()
                    direct = re.search(r"\s@\s*(?P<target>\S+)", target)
                    if direct is not None:
                        target = direct["target"]
                    elif target.startswith("-e "):
                        target = target[3:].strip()
                    if problem := local_source_url_problem(
                        target, f"{relative} direct requirement"
                    ):
                        return problem
                if problem := walk(child, trail):
                    return problem
        return None

    return walk(parsed)


def workspace_execution_input_problem(
    source_root: Path, inputs: dict[str, dict[str, str]]
) -> str | None:
    input_paths = frozenset(inputs)
    if "Cargo.toml" not in input_paths:
        return "workspace input closure lacks Cargo.toml"
    for relative in sorted(input_paths):
        pure = Path(relative)
        if pure.is_absolute() or ".." in pure.parts:
            return f"workspace input path escapes the snapshot: {relative!r}"
        if pure.name == "Cargo.toml":
            if problem := cargo_manifest_execution_path_problem(
                source_root, relative, input_paths
            ):
                return problem
        if pure.suffix == ".rs":
            if problem := rust_external_input_problem(
                source_root, relative, input_paths
            ):
                return problem
        if pure.name in {"pyproject.toml", "uv.toml", "uv.lock"}:
            if problem := python_local_source_problem(
                source_root, relative, input_paths
            ):
                return problem
    return None


def cargo_execution_config_problem(paths: object) -> str | None:
    if not isinstance(paths, (tuple, list, set, frozenset)):
        return "workspace path vocabulary is malformed"
    forbidden = sorted(
        path
        for path in paths
        if isinstance(path, str)
        and Path(path).name in {"config", "config.toml"}
        and ".cargo" in Path(path).parts
    )
    if forbidden:
        return f"workspace Cargo execution config is forbidden: {forbidden!r}"
    return None


def require_native_lib_harness_contract() -> None:
    for crate in TEST_LIST_CRATES:
        path = ROOT / f"crates/{crate}/Cargo.toml"
        if problem := native_lib_harness_problem(path.read_bytes()):
            fail(f"{crate} native lib harness differs: {problem}")
    inputs = workspace_input_hashes()
    if problem := cargo_execution_config_problem(tuple(inputs)):
        fail(problem)
    if problem := workspace_execution_input_problem(ROOT, inputs):
        fail(f"workspace execution-input closure differs: {problem}")


REVIEW_PHASE_BY_RESULT = {
    "PASS_CONTRACT_FREEZE": "contract_freeze",
    "PASS_IMPLEMENTATION": "implementation",
}
REVIEW_RECEIPT_RESULT = "PASS_TRUSTED_LOCAL_REVIEW_RECEIPTS"
REVIEW_RECEIPT_FILE_LIMIT_BYTES = 32 * 1024 * 1024


def canonical_json_text(value: object) -> str:
    return json.dumps(
        value,
        ensure_ascii=False,
        separators=(",", ":"),
        allow_nan=False,
    )


def phase_review_field_order(result: str) -> tuple[str, ...]:
    fields = (
        "result",
        "reviewer_role",
        "phase",
        "request_nonce",
        "request_sha256",
        "session_id",
        "reviewed_at_utc",
        "session_json_sha256",
        "trajectory_sha256",
        "contract_set_sha256",
    )
    if result == "PASS_IMPLEMENTATION":
        fields += ("source_set_sha256", "validated_commit")
    return fields + (
        "limit_source_set_sha256",
        "scanner_contract_sha256",
        "entry_exception_ledger_sha256",
        "control_exception_ledger_sha256",
        "exception_partition_sha256",
        "evidence_payload_sha256",
    )


def phase_review_request_payload(
    reviewer: str,
    result: str,
    request_nonce: str,
    contract_set_sha256: str,
    evidence_payload_sha256: str,
    source_set_sha256: str | None = None,
    validated_commit: str | None = None,
) -> dict[str, object]:
    phase = REVIEW_PHASE_BY_RESULT[result]
    payload: dict[str, object] = {
        "contract": "s20-530-specialist-review-request-v1",
        "reviewer_role": reviewer,
        "phase": phase,
        "request_nonce": request_nonce,
        "contract_set_sha256": contract_set_sha256,
    }
    if result == "PASS_IMPLEMENTATION":
        payload.update(
            {
                "source_set_sha256": source_set_sha256,
                "validated_commit": validated_commit,
            }
        )
    payload.update(
        {
            "limit_source_set_sha256": LIMIT_EXCEPTION_PARTITION_FREEZE[
                "source_set_sha256"
            ],
            "scanner_contract_sha256": LIMIT_EXCEPTION_PARTITION_FREEZE[
                "scanner_contract_sha256"
            ],
            "entry_exception_ledger_sha256": LIMIT_EXCEPTION_PARTITION_FREEZE[
                "entry_ledger_sha256"
            ],
            "control_exception_ledger_sha256": LIMIT_EXCEPTION_PARTITION_FREEZE[
                "control_ledger_sha256"
            ],
            "exception_partition_sha256": LIMIT_EXCEPTION_PARTITION_FREEZE_SHA256,
            "evidence_payload_sha256": evidence_payload_sha256,
        }
    )
    return payload


def phase_review_verdict_payload(
    reviewer: str,
    result: str,
    request_nonce: str,
    request_sha256: str,
    contract_set_sha256: str,
    evidence_payload_sha256: str,
    source_set_sha256: str | None = None,
    validated_commit: str | None = None,
) -> dict[str, object]:
    request = phase_review_request_payload(
        reviewer,
        result,
        request_nonce,
        contract_set_sha256,
        evidence_payload_sha256,
        source_set_sha256,
        validated_commit,
    )
    verdict = {"result": result}
    for key, value in request.items():
        if key == "contract":
            continue
        verdict[key] = value
        if key == "request_nonce":
            verdict["request_sha256"] = request_sha256
    return verdict


def phase_reviews_problem(
    reviews: object,
    result: str,
    contract_set_sha256: str,
    evidence_payload_sha256: str,
    source_set_sha256: str | None = None,
    validated_commit: str | None = None,
) -> str | None:
    phase = REVIEW_PHASE_BY_RESULT.get(result)
    if phase is None:
        return "review result is unknown"
    if not isinstance(reviews, dict) or tuple(reviews) != REVIEWERS:
        return f"{result} review owners/order differ"
    if result == "PASS_IMPLEMENTATION":
        if (
            not isinstance(source_set_sha256, str)
            or re.fullmatch(r"[0-9a-f]{64}", source_set_sha256) is None
            or not isinstance(validated_commit, str)
            or re.fullmatch(r"[0-9a-f]{40}", validated_commit) is None
        ):
            return "implementation review authority is malformed"
    expected_keys = phase_review_field_order(result)
    nonces: set[str] = set()
    session_ids: set[str] = set()
    for reviewer, verdict in reviews.items():
        if not isinstance(verdict, dict) or tuple(verdict) != expected_keys:
            return f"{reviewer} {result} review fields/order differ"
        if verdict.get("result") != result:
            return f"{reviewer} review is not exact {result}"
        if verdict.get("reviewer_role") != reviewer:
            return f"{reviewer} review role differs"
        if verdict.get("phase") != phase:
            return f"{reviewer} review phase differs"
        request_nonce = verdict.get("request_nonce")
        if (
            not isinstance(request_nonce, str)
            or re.fullmatch(r"[0-9a-f]{32}", request_nonce) is None
            or request_nonce in nonces
        ):
            return f"{reviewer} review nonce is malformed or replayed"
        nonces.add(request_nonce)
        session_id = verdict.get("session_id")
        session_phase = phase.replace("_", "-")
        if (
            not isinstance(session_id, str)
            or re.fullmatch(
                rf"forge-{reviewer}-s20-530-{session_phase}-"
                r"[0-9]{8}T[0-9]{6}-[0-9a-f]{8}",
                session_id,
            )
            is None
            or session_id in session_ids
        ):
            return f"{reviewer} review session is malformed or replayed"
        session_ids.add(session_id)
        reviewed_at = verdict.get("reviewed_at_utc")
        if (
            not isinstance(reviewed_at, str)
            or re.fullmatch(
                r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:"
                r"[0-9]{2}(?:\.[0-9]{1,9})?Z",
                reviewed_at,
            )
            is None
        ):
            return f"{reviewer} review timestamp is malformed"
        for field in (
            "request_sha256",
            "session_json_sha256",
            "trajectory_sha256",
        ):
            value = verdict.get(field)
            if (
                not isinstance(value, str)
                or re.fullmatch(r"[0-9a-f]{64}", value) is None
            ):
                return f"{reviewer} {field} is malformed"
        if verdict.get("contract_set_sha256") != contract_set_sha256:
            return f"{reviewer} review is bound to a stale contract"
        if verdict.get("evidence_payload_sha256") != evidence_payload_sha256:
            return f"{reviewer} review is bound to stale evidence"
        if result == "PASS_IMPLEMENTATION":
            if verdict.get("source_set_sha256") != source_set_sha256:
                return f"{reviewer} implementation review is bound to stale source"
            if verdict.get("validated_commit") != validated_commit:
                return f"{reviewer} implementation review commit differs"
        frozen_bindings = {
            "limit_source_set_sha256": LIMIT_EXCEPTION_PARTITION_FREEZE[
                "source_set_sha256"
            ],
            "scanner_contract_sha256": LIMIT_EXCEPTION_PARTITION_FREEZE[
                "scanner_contract_sha256"
            ],
            "entry_exception_ledger_sha256": LIMIT_EXCEPTION_PARTITION_FREEZE[
                "entry_ledger_sha256"
            ],
            "control_exception_ledger_sha256": LIMIT_EXCEPTION_PARTITION_FREEZE[
                "control_ledger_sha256"
            ],
            "exception_partition_sha256": LIMIT_EXCEPTION_PARTITION_FREEZE_SHA256,
        }
        for field, expected in frozen_bindings.items():
            if verdict.get(field) != expected:
                return f"{reviewer} {field} differs"
        request_payload = phase_review_request_payload(
            reviewer,
            result,
            request_nonce,
            contract_set_sha256,
            evidence_payload_sha256,
            source_set_sha256,
            validated_commit,
        )
        if verdict.get("request_sha256") != canonical_json_sha256(request_payload):
            return f"{reviewer} review request digest differs"
    return None


def require_phase_reviews(
    reviews: object,
    result: str,
    contract_set_sha256: str,
    evidence_payload_sha256: str,
    source_set_sha256: str | None = None,
    validated_commit: str | None = None,
) -> dict[str, object]:
    if problem := phase_reviews_problem(
        reviews,
        result,
        contract_set_sha256,
        evidence_payload_sha256,
        source_set_sha256,
        validated_commit,
    ):
        fail(problem)
    assert isinstance(reviews, dict)
    return reviews


def review_receipt_verification_payload(
    phase: str,
    evidence_path: Path,
    reviews: dict[str, object],
) -> dict[str, object]:
    verified: dict[str, object] = {}
    for reviewer, verdict in reviews.items():
        assert isinstance(verdict, dict)
        verified[reviewer] = {
            "session_id": verdict["session_id"],
            "reviewed_at_utc": verdict["reviewed_at_utc"],
            "session_json_sha256": verdict["session_json_sha256"],
            "trajectory_sha256": verdict["trajectory_sha256"],
        }
    return {
        "command": (
            "/usr/bin/python3 -I -B scripts/check_s20_530_crash_recovery.py "
            f"--verify-review-receipts {phase}"
        ),
        "result": REVIEW_RECEIPT_RESULT,
        "phase": phase,
        "evidence": str(evidence_path.relative_to(ROOT)),
        "review_receipts_sha256": canonical_json_sha256(reviews),
        "verified_receipts": verified,
    }


def review_receipt_verification_problem(
    recorded: object,
    phase: str,
    evidence_path: Path,
    reviews: dict[str, object],
) -> str | None:
    payload = review_receipt_verification_payload(phase, evidence_path, reviews)
    expected = {**payload, "payload_sha256": canonical_json_sha256(payload)}
    if not isinstance(recorded, dict) or tuple(recorded) != tuple(expected):
        return f"{phase} review-receipt verification fields/order differ"
    if recorded != expected:
        return f"{phase} review-receipt verification payload differs"
    return None


def require_review_receipt_verification(
    recorded: object,
    phase: str,
    evidence_path: Path,
    reviews: dict[str, object],
) -> None:
    if problem := review_receipt_verification_problem(
        recorded, phase, evidence_path, reviews
    ):
        fail(problem)


def read_bounded_authority_bytes(
    directory_fd: int,
    name: str,
    label: str,
    size_limit: int,
) -> bytes:
    descriptor = os.open(
        name,
        os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC,
        dir_fd=directory_fd,
    )
    try:
        before = os.fstat(descriptor)
        if not stat.S_ISREG(before.st_mode):
            raise ValueError(f"{label} is not a regular file")
        if before.st_uid != os.geteuid() or before.st_gid != os.getegid():
            raise ValueError(f"{label} is not owned by the validation uid/gid")
        if before.st_mode & stat.S_IWOTH:
            raise ValueError(f"{label} is world-writable")
        if before.st_size > size_limit:
            raise ValueError(f"{label} exceeds the receipt size limit")
        content = bytearray()
        while True:
            chunk = os.read(descriptor, size_limit + 1 - len(content))
            if not chunk:
                break
            content.extend(chunk)
            if len(content) > size_limit:
                raise ValueError(f"{label} exceeds the receipt size limit")
        after = os.fstat(descriptor)
        identity_fields = ("st_dev", "st_ino", "st_mode", "st_uid", "st_gid", "st_size")
        if any(
            getattr(before, field) != getattr(after, field) for field in identity_fields
        ):
            raise ValueError(f"{label} changed while being read")
        return bytes(content)
    finally:
        os.close(descriptor)


def trusted_review_receipt_bytes(
    reviewer: str,
    session_id: str,
) -> tuple[bytes, bytes]:
    descriptor, _metadata = open_authority_directory(
        Path(pwd.getpwuid(os.geteuid()).pw_dir), "review authority home"
    )
    try:
        for component in (".openclaw", "agents", reviewer, "sessions"):
            child, _metadata = open_authority_directory(
                component,
                f"review authority {component}",
                directory_fd=descriptor,
            )
            os.close(descriptor)
            descriptor = child
        session = read_bounded_authority_bytes(
            descriptor,
            f"{session_id}.jsonl",
            f"{reviewer} review session",
            REVIEW_RECEIPT_FILE_LIMIT_BYTES,
        )
        trajectory = read_bounded_authority_bytes(
            descriptor,
            f"{session_id}.trajectory.jsonl",
            f"{reviewer} review trajectory",
            REVIEW_RECEIPT_FILE_LIMIT_BYTES,
        )
        return session, trajectory
    finally:
        os.close(descriptor)


def review_message_text(message: object) -> str:
    if not isinstance(message, dict):
        return ""
    content = message.get("content")
    if isinstance(content, str):
        return content
    if not isinstance(content, list):
        return ""
    parts: list[str] = []
    for part in content:
        if isinstance(part, dict) and part.get("type") == "text":
            text = part.get("text")
            if isinstance(text, str):
                parts.append(text)
    return "\n".join(parts)


def verify_trusted_review_session(
    reviewer: str,
    verdict: dict[str, object],
    result: str,
    contract_set_sha256: str,
    evidence_payload_sha256: str,
    source_set_sha256: str | None,
    validated_commit: str | None,
    trusted_bytes: tuple[bytes, bytes] | None = None,
) -> None:
    session_id = verdict["session_id"]
    request_nonce = verdict["request_nonce"]
    request_sha256 = verdict["request_sha256"]
    assert isinstance(session_id, str)
    assert isinstance(request_nonce, str)
    assert isinstance(request_sha256, str)
    session, trajectory = (
        trusted_review_receipt_bytes(reviewer, session_id)
        if trusted_bytes is None
        else trusted_bytes
    )
    if hashlib.sha256(session).hexdigest() != verdict["session_json_sha256"]:
        fail(f"{reviewer} trusted session digest differs")
    if hashlib.sha256(trajectory).hexdigest() != verdict["trajectory_sha256"]:
        fail(f"{reviewer} trusted trajectory digest differs")

    request_payload = phase_review_request_payload(
        reviewer,
        result,
        request_nonce,
        contract_set_sha256,
        evidence_payload_sha256,
        source_set_sha256,
        validated_commit,
    )
    if canonical_json_sha256(request_payload) != request_sha256:
        fail(f"{reviewer} trusted request digest differs")
    verdict_payload = phase_review_verdict_payload(
        reviewer,
        result,
        request_nonce,
        request_sha256,
        contract_set_sha256,
        evidence_payload_sha256,
        source_set_sha256,
        validated_commit,
    )
    request_marker = "S20_530_REVIEW_REQUEST_JSON=" + canonical_json_text(
        request_payload
    )
    verdict_marker = "S20_530_REVIEW_VERDICT_JSON=" + canonical_json_text(
        verdict_payload
    )
    request_occurrences = 0
    verdict_occurrences = 0
    verdict_timestamp: str | None = None
    session_record_count = 0
    for index, line in enumerate(session.splitlines(), start=1):
        try:
            item = strict_json_object(line, f"{reviewer} session line {index}")
        except ValueError as error:
            fail(str(error))
        if item.get("type") == "session":
            session_record_count += 1
            if item.get("id") != session_id:
                fail(f"{reviewer} trusted session identity differs")
        if item.get("type") != "message":
            continue
        message = item.get("message")
        if not isinstance(message, dict):
            continue
        text = review_message_text(message)
        if message.get("role") == "user":
            request_occurrences += text.count(request_marker)
        elif message.get("role") == "assistant":
            count = text.count(verdict_marker)
            verdict_occurrences += count
            if count:
                timestamp = item.get("timestamp")
                if not isinstance(timestamp, str):
                    fail(f"{reviewer} verdict timestamp is absent")
                verdict_timestamp = timestamp
    if session_record_count != 1:
        fail(f"{reviewer} trusted session header count differs")
    if request_occurrences != 1:
        fail(f"{reviewer} trusted request marker count differs")
    if verdict_occurrences != 1:
        fail(f"{reviewer} trusted verdict marker count differs")
    if verdict_timestamp != verdict["reviewed_at_utc"]:
        fail(f"{reviewer} trusted verdict timestamp differs")


def verify_review_receipts(phase: str) -> None:
    phase_contract = {
        "contract_freeze": (
            FREEZE_EVIDENCE,
            "s20-530-crash-recovery-contract-freeze-v8",
            "PASS_CONTRACT_FROZEN",
            "PASS_CONTRACT_FREEZE",
        ),
        "implementation": (
            CLOSEOUT_EVIDENCE,
            "s20-530-crash-recovery-closeout-v1",
            "PASS_CRASH_RECOVERY_MATRIX",
            "PASS_IMPLEMENTATION",
        ),
    }.get(phase)
    if phase_contract is None:
        fail("review-receipt phase must be contract_freeze or implementation")
    evidence_path, identity, evidence_result, review_result = phase_contract
    evidence = load_json(evidence_path)
    if (
        evidence.get("contract") != identity
        or evidence.get("result") != evidence_result
    ):
        fail(f"{phase} evidence identity/result differs")
    hashes = require_frozen_contract_integrity()
    contract_set_sha256 = canonical_json_sha256(hashes)
    if evidence.get("contract_set_sha256") != contract_set_sha256:
        fail(f"{phase} evidence contract-set digest differs")
    payload_sha256 = review_payload_sha256(evidence)
    source_set_sha256: str | None = None
    validated_commit: str | None = None
    if phase == "implementation":
        validation = evidence.get("validation")
        if not isinstance(validation, dict):
            fail("implementation review validation payload is absent")
        source_set_sha256 = validation.get("source_set_sha256")  # type: ignore[assignment]
        validated_commit = validation.get("validated_commit")  # type: ignore[assignment]
    reviews = require_phase_reviews(
        evidence.get("reviews"),
        review_result,
        contract_set_sha256,
        payload_sha256,
        source_set_sha256,
        validated_commit,
    )
    for reviewer, verdict in reviews.items():
        assert isinstance(verdict, dict)
        verify_trusted_review_session(
            reviewer,
            verdict,
            review_result,
            contract_set_sha256,
            payload_sha256,
            source_set_sha256,
            validated_commit,
        )
    payload = review_receipt_verification_payload(phase, evidence_path, reviews)
    recorded = evidence.get("review_receipt_verification")
    if recorded not in (None, {}):
        if problem := review_receipt_verification_problem(
            recorded, phase, evidence_path, reviews
        ):
            fail(problem)
    result = {**payload, "payload_sha256": canonical_json_sha256(payload)}
    print(json.dumps(result, indent=2, ensure_ascii=False))


def synthetic_phase_reviews(
    result: str,
    contract_set_sha256: str,
    evidence_payload_sha256: str,
    source_set_sha256: str | None = None,
    validated_commit: str | None = None,
) -> dict[str, object]:
    phase = REVIEW_PHASE_BY_RESULT[result]
    session_phase = phase.replace("_", "-")
    reviews: dict[str, object] = {}
    for index, reviewer in enumerate(REVIEWERS, start=1):
        nonce = f"{index:032x}"
        request = phase_review_request_payload(
            reviewer,
            result,
            nonce,
            contract_set_sha256,
            evidence_payload_sha256,
            source_set_sha256,
            validated_commit,
        )
        row: dict[str, object] = {
            "result": result,
            "reviewer_role": reviewer,
            "phase": phase,
            "request_nonce": nonce,
            "request_sha256": canonical_json_sha256(request),
            "session_id": (
                f"forge-{reviewer}-s20-530-{session_phase}-"
                f"20260831T00000{index}-{index:08x}"
            ),
            "reviewed_at_utc": f"2026-08-31T00:00:0{index}.000Z",
            "session_json_sha256": f"{index + 3:x}" * 64,
            "trajectory_sha256": f"{index + 6:x}" * 64,
            "contract_set_sha256": contract_set_sha256,
        }
        if result == "PASS_IMPLEMENTATION":
            row.update(
                {
                    "source_set_sha256": source_set_sha256,
                    "validated_commit": validated_commit,
                }
            )
        row.update(
            {
                "limit_source_set_sha256": LIMIT_EXCEPTION_PARTITION_FREEZE[
                    "source_set_sha256"
                ],
                "scanner_contract_sha256": LIMIT_EXCEPTION_PARTITION_FREEZE[
                    "scanner_contract_sha256"
                ],
                "entry_exception_ledger_sha256": LIMIT_EXCEPTION_PARTITION_FREEZE[
                    "entry_ledger_sha256"
                ],
                "control_exception_ledger_sha256": LIMIT_EXCEPTION_PARTITION_FREEZE[
                    "control_ledger_sha256"
                ],
                "exception_partition_sha256": LIMIT_EXCEPTION_PARTITION_FREEZE_SHA256,
                "evidence_payload_sha256": evidence_payload_sha256,
            }
        )
        reviews[reviewer] = row
    return reviews


def require_review_receipt_negative_controls() -> None:
    contract_set_sha256 = "a" * 64
    evidence_payload_sha256 = "b" * 64
    source_set_sha256 = "c" * 64
    validated_commit = "d" * 40
    for result, source_set, revision in (
        ("PASS_CONTRACT_FREEZE", None, None),
        ("PASS_IMPLEMENTATION", source_set_sha256, validated_commit),
    ):
        reviews = synthetic_phase_reviews(
            result,
            contract_set_sha256,
            evidence_payload_sha256,
            source_set,
            revision,
        )
        if problem := phase_reviews_problem(
            reviews,
            result,
            contract_set_sha256,
            evidence_payload_sha256,
            source_set,
            revision,
        ):
            fail(f"checker self-test rejected exact review receipts: {problem}")
        hostile_reviews: list[dict[str, object]] = []
        for field, value in (
            ("request_sha256", "0" * 64),
            ("reviewer_role", "vulcan"),
            ("entry_exception_ledger_sha256", "0" * 64),
        ):
            hostile = json.loads(json.dumps(reviews))
            assert isinstance(hostile, dict)
            row = hostile["nabu"]
            assert isinstance(row, dict)
            row[field] = value
            hostile_reviews.append(hostile)
        replayed = json.loads(json.dumps(reviews))
        assert isinstance(replayed, dict)
        nabu = replayed["nabu"]
        ariadne = replayed["ariadne"]
        assert isinstance(nabu, dict) and isinstance(ariadne, dict)
        ariadne["request_nonce"] = nabu["request_nonce"]
        hostile_reviews.append(replayed)
        missing = json.loads(json.dumps(reviews))
        assert isinstance(missing, dict)
        row = missing["nabu"]
        assert isinstance(row, dict)
        row.pop("trajectory_sha256")
        hostile_reviews.append(missing)
        for hostile in hostile_reviews:
            if (
                phase_reviews_problem(
                    hostile,
                    result,
                    contract_set_sha256,
                    evidence_payload_sha256,
                    source_set,
                    revision,
                )
                is None
            ):
                fail("checker self-test accepted hostile review receipts")

        phase = REVIEW_PHASE_BY_RESULT[result]
        evidence_path = (
            FREEZE_EVIDENCE if result == "PASS_CONTRACT_FREEZE" else CLOSEOUT_EVIDENCE
        )
        payload = review_receipt_verification_payload(phase, evidence_path, reviews)
        exact = {**payload, "payload_sha256": canonical_json_sha256(payload)}
        if problem := review_receipt_verification_problem(
            exact, phase, evidence_path, reviews
        ):
            fail(f"checker self-test rejected exact receipt verification: {problem}")
        stale = dict(exact)
        stale["payload_sha256"] = "0" * 64
        if (
            review_receipt_verification_problem(stale, phase, evidence_path, reviews)
            is None
        ):
            fail("checker self-test accepted stale receipt verification")

    reviews = synthetic_phase_reviews(
        "PASS_CONTRACT_FREEZE",
        contract_set_sha256,
        evidence_payload_sha256,
    )
    row = reviews["nabu"]
    assert isinstance(row, dict)
    request = phase_review_request_payload(
        "nabu",
        "PASS_CONTRACT_FREEZE",
        row["request_nonce"],  # type: ignore[arg-type]
        contract_set_sha256,
        evidence_payload_sha256,
    )
    verdict = phase_review_verdict_payload(
        "nabu",
        "PASS_CONTRACT_FREEZE",
        row["request_nonce"],  # type: ignore[arg-type]
        row["request_sha256"],  # type: ignore[arg-type]
        contract_set_sha256,
        evidence_payload_sha256,
    )
    request_marker = "S20_530_REVIEW_REQUEST_JSON=" + canonical_json_text(request)
    verdict_marker = "S20_530_REVIEW_VERDICT_JSON=" + canonical_json_text(verdict)
    exact_lines = (
        {
            "type": "session",
            "id": row["session_id"],
            "timestamp": "2026-08-31T00:00:00.000Z",
        },
        {
            "type": "message",
            "timestamp": "2026-08-31T00:00:00.500Z",
            "message": {"role": "user", "content": request_marker},
        },
        {
            "type": "message",
            "timestamp": row["reviewed_at_utc"],
            "message": {"role": "assistant", "content": verdict_marker},
        },
    )
    session = (
        "\n".join(canonical_json_text(line) for line in exact_lines) + "\n"
    ).encode("utf-8")
    trajectory = b'{"type":"trusted-trajectory-fixture"}\n'
    row["session_json_sha256"] = hashlib.sha256(session).hexdigest()
    row["trajectory_sha256"] = hashlib.sha256(trajectory).hexdigest()
    verify_trusted_review_session(
        "nabu",
        row,
        "PASS_CONTRACT_FREEZE",
        contract_set_sha256,
        evidence_payload_sha256,
        None,
        None,
        (session, trajectory),
    )

    def expect_trusted_rejection(
        hostile_row: dict[str, object],
        hostile_session: bytes,
        hostile_trajectory: bytes,
    ) -> None:
        with redirect_stderr(io.StringIO()):
            try:
                verify_trusted_review_session(
                    "nabu",
                    hostile_row,
                    "PASS_CONTRACT_FREEZE",
                    contract_set_sha256,
                    evidence_payload_sha256,
                    None,
                    None,
                    (hostile_session, hostile_trajectory),
                )
            except SystemExit:
                return
        fail("checker self-test accepted a hostile trusted review session")

    stale_trajectory = dict(row)
    stale_trajectory["trajectory_sha256"] = "0" * 64
    expect_trusted_rejection(stale_trajectory, session, trajectory)
    for old, new in (
        (request_marker, "S20_530_REVIEW_REQUEST_JSON={}"),
        (verdict_marker, "S20_530_REVIEW_VERDICT_JSON={}"),
        (str(row["session_id"]), "forge-nabu-s20-530-contract-freeze-wrong"),
    ):
        encoded_old = canonical_json_text(old)[1:-1].encode("utf-8")
        encoded_new = canonical_json_text(new)[1:-1].encode("utf-8")
        hostile_session = session.replace(encoded_old, encoded_new, 1)
        if hostile_session == session:
            fail("checker self-test review-session mutation did not apply")
        hostile_row = dict(row)
        hostile_row["session_json_sha256"] = hashlib.sha256(hostile_session).hexdigest()
        expect_trusted_rejection(hostile_row, hostile_session, trajectory)
    stale_timestamp = dict(row)
    stale_timestamp["reviewed_at_utc"] = "2026-08-31T00:00:09.000Z"
    expect_trusted_rejection(stale_timestamp, session, trajectory)


def require_freeze_anchor(package: dict[str, object], hashes: dict[str, str]) -> None:
    relative = str(FREEZE_EVIDENCE.relative_to(ROOT))
    commits = tuple(
        line
        for line in git_text(
            "log", "--format=%H", "--diff-filter=A", "--", relative
        ).splitlines()
        if line
    )
    if len(commits) != 1:
        fail("contract-freeze evidence lacks one immutable addition commit")
    revision = commits[0]
    if package.get("freeze_commit") != revision:
        fail("machine summary freeze commit differs")
    if not revision_is_ancestor(revision):
        fail("contract-freeze commit is not an ancestor of HEAD")
    try:
        committed_evidence = committed_blob(revision, relative)
        current_evidence = FREEZE_EVIDENCE.read_bytes()
    except OSError as error:
        fail(f"cannot compare contract-freeze evidence: {error}")
    if committed_evidence != current_evidence:
        fail("contract-freeze evidence changed after its addition commit")
    committed_paths = {
        "spec_sha256": str(SPEC.relative_to(ROOT)),
        "adr_sha256": str(ADR.relative_to(ROOT)),
        "checker_sha256": str(Path(__file__).resolve().relative_to(ROOT)),
        "runner_sha256": str(RUNNER.relative_to(ROOT)),
        "reconciler_sha256": str(RECONCILER.relative_to(ROOT)),
    }
    for field, path in committed_paths.items():
        digest = hashlib.sha256(committed_blob(revision, path)).hexdigest()
        if digest != hashes[field]:
            fail(f"freeze commit {field} differs from reviewed contract")


def freeze_deterministic_inputs_problem(
    deterministic: object,
    hashes: object,
    matrix_rows: object,
) -> str | None:
    hash_fields = (
        "matrix_rows_sha256",
        "spec_sha256",
        "adr_sha256",
        "checker_sha256",
        "checker_contract_sha256",
        "runner_sha256",
        "reconciler_sha256",
    )
    if not isinstance(hashes, dict) or tuple(hashes) != hash_fields:
        return "contract hash fields/order differ"
    if any(
        not isinstance(value, str) or re.fullmatch(r"[0-9a-f]{64}", value) is None
        for value in hashes.values()
    ):
        return "contract hash value differs"
    if not isinstance(deterministic, dict) or tuple(deterministic) != (
        "matrix_rows",
        *hash_fields,
    ):
        return "deterministic input fields/order differ"
    if not exact_json_scalar_equal(deterministic.get("matrix_rows"), matrix_rows):
        return "matrix count differs"
    for field, expected in hashes.items():
        if not exact_json_scalar_equal(deterministic.get(field), expected):
            return f"{field} differs"
    return None


S20_530_IMPLEMENTATION_REVIEW_OBLIGATIONS = {
    "implementation_helper_body_manifests": "FINAL_REVIEW_REQUIRED",
    "dual_site_proof_manifests": "FINAL_REVIEW_REQUIRED_5_FIELDS",
    "limit_event_owner_body_control_ancestries": (
        "FINAL_REVIEW_REQUIRED_30_EVENTS_EXACT_V8_PARTITION"
    ),
    "limit_event_entry_call_paths": (
        "FINAL_REVIEW_REQUIRED_ALL_PUBLIC_ROOTS_EXACT_V8_PARTITION"
    ),
    "independent_exception_reconciliation": "FINAL_REVIEW_REQUIRED_EXACT_TIER_2",
    "test_to_production_shared_state_authority": (
        "FINAL_REVIEW_REQUIRED_COMPLETE_LOCAL_DEPENDENCY_CLOSURE"
    ),
}


def require_freeze_evidence(
    package: dict[str, object], implementation_complete: bool
) -> tuple[str, dict[str, object]]:
    hashes = require_frozen_contract_integrity()
    evidence = load_json(FREEZE_EVIDENCE)
    if evidence.get("contract") != "s20-530-crash-recovery-contract-freeze-v8":
        fail("contract-freeze evidence identity differs")
    if evidence.get("result") != "PASS_CONTRACT_FROZEN":
        fail("contract-freeze evidence is not PASS_CONTRACT_FROZEN")
    deterministic = evidence.get("deterministic_inputs")
    if problem := freeze_deterministic_inputs_problem(
        deterministic,
        hashes,
        len(MATRIX_IDS),
    ):
        fail(f"contract-freeze {problem}")
    contract_set_sha256 = canonical_json_sha256(hashes)
    if evidence.get("contract_set_sha256") != contract_set_sha256:
        fail("contract-freeze set digest differs")
    if evidence.get("review_obligations") != S20_530_IMPLEMENTATION_REVIEW_OBLIGATIONS:
        fail("contract-freeze implementation review obligations differ")
    reviews = require_phase_reviews(
        evidence.get("reviews"),
        "PASS_CONTRACT_FREEZE",
        contract_set_sha256,
        review_payload_sha256(evidence),
    )
    require_review_receipt_verification(
        evidence.get("review_receipt_verification"),
        "contract_freeze",
        FREEZE_EVIDENCE,
        reviews,
    )
    if evidence.get("implementation_complete") is not False:
        fail("contract-freeze evidence must not claim implementation")
    if package.get("contract_freeze_evidence") != str(
        FREEZE_EVIDENCE.relative_to(ROOT)
    ):
        fail("machine summary freeze-evidence path differs")
    if package.get("contract_set_sha256") != contract_set_sha256:
        fail("machine summary contract-set digest differs")
    if package.get("contract_reviews") != reviews:
        fail("machine summary contract reviews differ from freeze evidence")
    if implementation_complete:
        require_freeze_anchor(package, hashes)
    return contract_set_sha256, reviews


def require_implementation(
    package: dict[str, object], contract_set_sha256: str
) -> None:
    if problem := recovery_ancestry_test_hook_authority_problem():
        fail(f"recovery-ancestry test-hook authority differs: {problem}")
    for relative in PUBLIC_API_SOURCE_PATHS:
        text = (ROOT / relative).read_text(encoding="utf-8")
        if problem := normal_build_fault_authority_problem(text):
            fail(f"{relative} fault selector is not test-only: {problem}")

    require_public_recovery_api()

    evidence = load_json(CLOSEOUT_EVIDENCE)
    if evidence.get("contract") != "s20-530-crash-recovery-closeout-v1":
        fail("closeout evidence identity differs")
    if evidence.get("result") != "PASS_CRASH_RECOVERY_MATRIX":
        fail("closeout evidence is not PASS_CRASH_RECOVERY_MATRIX")
    if evidence.get("implementation_complete") is not True:
        fail("closeout evidence must claim exact completed implementation")
    if evidence.get("contract_set_sha256") != contract_set_sha256:
        fail("closeout evidence contract-set digest differs")
    test_plan = load_json(TEST_PLAN)
    if tuple(test_plan) != (
        "contract",
        "contract_set_sha256",
        "matrix_test_map",
        "limit_runtime_helpers",
        "limit_runtime_helpers_sha256",
        "limit_runtime_cases",
        "limit_runtime_cases_sha256",
        "limit_event_owner_bodies",
        "limit_event_owner_bodies_sha256",
        "limit_event_control_ancestries",
        "limit_event_control_ancestries_sha256",
        "limit_event_control_exception_ledger",
        "limit_event_control_exception_ledger_sha256",
        "limit_event_entry_call_paths",
        "limit_event_entry_call_paths_sha256",
        "limit_event_entry_exception_ledger",
        "limit_event_entry_exception_ledger_sha256",
        "limit_exception_reconciler",
        "limit_exception_reconciler_sha256",
        "limit_shared_state_authority",
        "limit_shared_state_authority_sha256",
        "limit_runtime_site_proofs",
        "limit_runtime_site_proofs_sha256",
        "limit_event_observations",
        "limit_event_observations_sha256",
        "mapped_test_bodies",
        "mapped_test_bodies_sha256",
    ):
        fail("S20-530 test-plan fields/order differ")
    if test_plan.get("contract") != "s20-530-crash-recovery-test-plan-v1":
        fail("S20-530 test-plan identity differs")
    if test_plan.get("contract_set_sha256") != contract_set_sha256:
        fail("S20-530 test plan is bound to a stale contract")
    if evidence.get("test_plan") != str(TEST_PLAN.relative_to(ROOT)):
        fail("closeout test-plan path differs")
    if evidence.get("test_plan_sha256") != repository_file_sha256(TEST_PLAN):
        fail("closeout test-plan digest differs")
    row_map = test_plan.get("matrix_test_map")
    if not isinstance(row_map, dict) or tuple(row_map) != MATRIX_IDS:
        fail("closeout test map does not cover the exact ordered matrix")
    sources = {
        relative: (ROOT / relative).read_text(encoding="utf-8")
        for relative in OWNER_SOURCES
    }
    sources["crates/sley-txn/src/maintenance.rs"] = (
        ROOT / "crates/sley-txn/src/maintenance.rs"
    ).read_text(encoding="utf-8")
    if problem := limit_runtime_probe_binding_problem(sources):
        fail(f"limit runtime comparison-helper binding differs: {problem}")
    authority_sources = {
        relative: (ROOT / relative).read_text(encoding="utf-8")
        for relative in PUBLIC_API_SOURCE_PATHS
    }
    limit_authority_sources = {
        relative: (ROOT / relative).read_text(encoding="utf-8")
        for relative in limit_production_source_paths()
    }
    if problem := cross05_production_contract_problem(authority_sources):
        fail(f"CROSS-05 production binding differs: {problem}")
    if problem := gc_recovery_source_authority_problem(
        sources["crates/sley-repo/src/gc.rs"]
    ):
        fail(f"GC recovery source authority differs: {problem}")
    if problem := gc_recovery_row_mapping_problem(row_map):
        fail(f"GC recovery row mapping differs: {problem}")
    for relative, source in authority_sources.items():
        if problem := mapped_source_macro_authority_problem(source):
            fail(
                f"mapped test source has macro namespace authority in {relative}: {problem}"
            )
        if problem := mapped_source_process_authority_problem(source):
            fail(f"mapped test source has process authority in {relative}: {problem}")
        if problem := mapped_source_raw_output_authority_problem(source):
            fail(
                f"mapped test source has raw output authority in {relative}: {problem}"
            )
        if problem := mapped_source_ffi_authority_problem(source):
            fail(f"mapped test source has FFI authority in {relative}: {problem}")
    require_test_only_durability_cut_authority(sources, row_map)
    require_error_source_helpers(sources)
    require_snapshot_helpers(sources)
    require_owned_entry_fixture_helpers(sources)
    if problem := grouped_m2_probe_adapter_source_problem(sources):
        fail(f"grouped M2 probe-adapter source authority differs: {problem}")
    used_tests: list[str] = []
    test_owners: dict[str, str] = {}
    qualified_tests: dict[str, str] = {}
    for row_id, entry in row_map.items():
        if not isinstance(entry, dict) or entry.get("result") != "PASS":
            fail(f"{row_id} test-map entry is not a PASS object")
        if row_id in EVIDENCE_FAMILIES:
            subcases = entry.get("subcases")
            if (
                not isinstance(subcases, dict)
                or tuple(subcases) != EVIDENCE_FAMILIES[row_id]
            ):
                fail(f"{row_id} subcase order or vocabulary differs")
            for subcase_id, subcase in subcases.items():
                if row_id in GROUPED_ERROR_CASES:
                    require_grouped_error_evidence(
                        row_id,
                        subcase_id,
                        subcase,
                        sources,
                        used_tests,
                        test_owners,
                        qualified_tests,
                    )
                    continue
                owner, qualified = require_evidence_tests(
                    row_id, subcase_id, subcase, sources, used_tests
                )
                test_owners[used_tests[-1]] = crate_for_source(owner)
                qualified_tests[used_tests[-1]] = qualified
                if row_id in OWNED_ENTRY_FAMILIES:
                    require_owned_entry_evidence(
                        row_id,
                        subcase_id,
                        subcase,
                        owner,
                        sources[owner],
                    )
                    if (
                        subcase_id in OWNED_ENTRY_FATAL_SUBCASES
                        and (row_id, subcase_id) not in OWNED_ENTRY_MULTIFAULT_CASES
                    ):
                        require_preflight_canary_evidence(row_id, subcase_id, subcase)
                elif row_id in GC_PARTIAL_REPORT_ROWS:
                    require_gc_partial_report_evidence(row_id, subcase_id, subcase)
                elif row_id == "CROSS-05":
                    require_cross05_evidence(
                        subcase_id,
                        subcase,
                        owner,
                        sources[owner],
                    )
                elif row_id in ERROR_CASE_SPECS:
                    require_error_case_evidence(
                        row_id,
                        subcase_id,
                        subcase,
                        owner,
                        sources[owner],
                    )
                    if row_id in PREFLIGHT_CANARIES:
                        require_preflight_canary_evidence(row_id, subcase_id, subcase)
                else:
                    if subcase.get("no_mutation") is not True:
                        fail(f"{row_id}/{subcase_id} lacks no-mutation evidence")
                    if row_id in CORRUPTION_CODES:
                        expected_code = CORRUPTION_CODES[row_id][subcase_id]
                        if subcase.get("expected_result") != expected_code:
                            fail(f"{row_id}/{subcase_id} expected result differs")
                        require_semantic_assertions(
                            f"{row_id}/{subcase_id}",
                            subcase,
                            ("expected_result", "no_mutation"),
                        )
                        require_exact_result_assertion(
                            f"{row_id}/{subcase_id}",
                            subcase,
                            "expected_result",
                            expected_code,
                            require_projection=True,
                        )
                    if row_id in PREFLIGHT_CANARIES and not row_id.startswith("LIMIT-"):
                        require_preflight_canary_evidence(row_id, subcase_id, subcase)
                if row_id.startswith("LIMIT-"):
                    expected_limit_result = limit_plus_one_expected_result(
                        row_id, subcase_id
                    )
                    expected_limit_owner = LIMIT_DEFAULTS[row_id][subcase_id][0]
                    if owner != expected_limit_owner:
                        fail(
                            f"{row_id}/{subcase_id} limit test owner differs: "
                            f"expected {expected_limit_owner}, found {owner}"
                        )
                    if subcase.get("exact_limit_success") is not True:
                        fail(f"{row_id}/{subcase_id} lacks exact-limit success")
                    if subcase.get("limit_plus_one_code") != expected_limit_result:
                        fail(f"{row_id}/{subcase_id} limit+1 code differs")
                    if subcase.get("no_partial_report") is not True:
                        fail(f"{row_id}/{subcase_id} lacks no-partial-report evidence")
                    semantic_fields = (
                        "no_mutation",
                        "frozen_default",
                        "exact_limit_success",
                        "limit_plus_one_code",
                        "no_partial_report",
                    )
                    require_semantic_assertions(
                        f"{row_id}/{subcase_id}",
                        subcase,
                        semantic_fields,
                        custom_fields=frozenset(
                            {
                                "no_mutation",
                                "exact_limit_success",
                                "limit_plus_one_code",
                                "no_partial_report",
                            }
                        ),
                    )
                    require_exact_limit_default_assertion(row_id, subcase_id, subcase)
                    require_exact_limit_error_assertion(
                        row_id,
                        subcase_id,
                        subcase,
                        expected_limit_result,
                    )
                    require_limit_operation_evidence(
                        row_id,
                        subcase_id,
                        subcase,
                        owner,
                        sources[owner],
                    )
                if (row_id, subcase_id) in MULTIFAULT_CASES:
                    require_multifault_evidence(
                        row_id,
                        subcase_id,
                        subcase,
                        owner,
                        sources[owner],
                    )
        else:
            owner, qualified = require_evidence_tests(
                row_id, None, entry, sources, used_tests
            )
            test_owners[used_tests[-1]] = crate_for_source(owner)
            qualified_tests[used_tests[-1]] = qualified
            if row_id in NON_GC_DURABILITY_ROWS:
                require_durability_result_evidence(
                    row_id,
                    entry,
                    owner,
                    sources[owner],
                )
            elif row_id in RECOVERY_SUCCESS_EXPECTATIONS:
                require_recovery_success_evidence(
                    row_id,
                    entry,
                    owner,
                    sources[owner],
                )
            elif row_id in ROW_ERROR_SPECS:
                require_error_case_evidence(
                    row_id,
                    None,
                    entry,
                    owner,
                    sources[owner],
                )
                if row_id in PREFLIGHT_CANARIES:
                    require_preflight_canary_evidence(row_id, None, entry)
            else:
                if entry.get("immediate_state_verified") is not True:
                    fail(f"{row_id} lacks immediate-state evidence")
                if entry.get("recovery_result_verified") is not True:
                    fail(f"{row_id} lacks recovery-result evidence")
                require_semantic_assertions(
                    row_id,
                    entry,
                    ("immediate_state_verified", "recovery_result_verified"),
                )
    if len(used_tests) != 419:
        fail(f"closeout test map has {len(used_tests)} mapped tests instead of 419")
    expected_test_bodies = mapped_test_body_manifest(
        used_tests,
        sources,
        qualified_tests,
    )
    recorded_test_bodies = test_plan.get("mapped_test_bodies")
    if (
        not isinstance(recorded_test_bodies, dict)
        or tuple(recorded_test_bodies) != tuple(used_tests)
        or recorded_test_bodies != expected_test_bodies
    ):
        fail("mapped test-body review manifest differs from current exact bodies")
    for test, record in recorded_test_bodies.items():
        if not isinstance(record, dict) or tuple(record) != (
            "source",
            "qualified_test",
            "body_sha256",
        ):
            fail(f"mapped test-body review fields/order differ for {test}")
    mapped_test_bodies_sha256 = canonical_json_sha256(expected_test_bodies)
    recorded_test_bodies_sha256 = canonical_json_sha256(recorded_test_bodies)
    if (
        test_plan.get("mapped_test_bodies_sha256") != mapped_test_bodies_sha256
        or recorded_test_bodies_sha256 != mapped_test_bodies_sha256
    ):
        fail("mapped test-body review-manifest digest differs")
    if evidence.get("mapped_test_bodies_sha256") != mapped_test_bodies_sha256:
        fail("closeout evidence is bound to stale mapped test bodies")
    expected_runtime_helpers = limit_runtime_helper_body_manifest(sources)
    recorded_runtime_helpers = test_plan.get("limit_runtime_helpers")
    if (
        not isinstance(recorded_runtime_helpers, dict)
        or tuple(recorded_runtime_helpers) != tuple(expected_runtime_helpers)
        or recorded_runtime_helpers != expected_runtime_helpers
    ):
        fail("limit runtime helper-body review manifest differs")
    for key, record in recorded_runtime_helpers.items():
        if not isinstance(record, dict) or tuple(record) != (
            "source",
            "owner",
            "function",
            "attribute_chain_sha256",
            "body_sha256",
        ):
            fail(f"limit runtime helper-body fields differ for {key}")
    runtime_helpers_sha256 = canonical_json_sha256(expected_runtime_helpers)
    if (
        test_plan.get("limit_runtime_helpers_sha256") != runtime_helpers_sha256
        or canonical_json_sha256(recorded_runtime_helpers) != runtime_helpers_sha256
    ):
        fail("limit runtime helper-body review-manifest digest differs")
    expected_runtime_cases = limit_runtime_case_manifest(
        row_map,
        expected_test_bodies,
        expected_runtime_helpers,
    )
    recorded_runtime_cases = test_plan.get("limit_runtime_cases")
    if (
        not isinstance(recorded_runtime_cases, dict)
        or tuple(recorded_runtime_cases) != tuple(expected_runtime_cases)
        or recorded_runtime_cases != expected_runtime_cases
    ):
        fail("limit runtime case review manifest differs")
    runtime_cases_sha256 = canonical_json_sha256(expected_runtime_cases)
    if (
        test_plan.get("limit_runtime_cases_sha256") != runtime_cases_sha256
        or canonical_json_sha256(recorded_runtime_cases) != runtime_cases_sha256
    ):
        fail("limit runtime case review-manifest digest differs")
    expected_owner_bodies = limit_event_owner_body_manifest(sources)
    recorded_owner_bodies = test_plan.get("limit_event_owner_bodies")
    if (
        not isinstance(recorded_owner_bodies, dict)
        or tuple(recorded_owner_bodies) != tuple(expected_owner_bodies)
        or recorded_owner_bodies != expected_owner_bodies
    ):
        fail("limit-event owner-body review manifest differs from exact production")
    for key, record in recorded_owner_bodies.items():
        if not isinstance(record, dict) or tuple(record) != (
            "source",
            "owner",
            "function",
            "attribute_chain_sha256",
            "body_sha256",
        ):
            fail(f"limit-event owner-body review fields differ for {key}")
    owner_bodies_sha256 = canonical_json_sha256(expected_owner_bodies)
    if (
        test_plan.get("limit_event_owner_bodies_sha256") != owner_bodies_sha256
        or canonical_json_sha256(recorded_owner_bodies) != owner_bodies_sha256
    ):
        fail("limit-event owner-body review-manifest digest differs")
    expected_control_ancestries = limit_event_control_ancestry_manifest(
        limit_authority_sources
    )
    recorded_control_ancestries = test_plan.get("limit_event_control_ancestries")
    if (
        not isinstance(recorded_control_ancestries, dict)
        or tuple(recorded_control_ancestries) != tuple(LIMIT_EVENT_SPECS)
        or recorded_control_ancestries != expected_control_ancestries
    ):
        fail("limit-event control-ancestry review manifest differs")
    for event_id, record in recorded_control_ancestries.items():
        if not isinstance(record, dict) or tuple(record) != (
            "source",
            "owner",
            "function",
            "owner_body",
            "owner_attribute_chain_sha256",
            "owner_body_sha256",
            "owner_function_macros",
            "ordered_scopes",
            "dominating_exits",
            "collection_mutations",
        ):
            fail(f"limit-event control-ancestry fields differ for {event_id}")
        scopes = record["ordered_scopes"]
        if not isinstance(scopes, list):
            fail(f"limit-event control scopes differ for {event_id}")
        for scope in scopes:
            if not isinstance(scope, dict) or tuple(scope) != (
                "header",
                "header_sha256",
                "identifiers",
                "calls",
                "macros",
                "resolved_values",
                "resolved_authority",
                "kind",
                "edge_liveness",
            ):
                fail(f"limit-event control scope fields differ for {event_id}")
    control_ancestries_sha256 = canonical_json_sha256(expected_control_ancestries)
    if (
        test_plan.get("limit_event_control_ancestries_sha256")
        != control_ancestries_sha256
        or canonical_json_sha256(recorded_control_ancestries)
        != control_ancestries_sha256
        or evidence.get("limit_event_control_ancestries_sha256")
        != control_ancestries_sha256
    ):
        fail("limit-event control-ancestry review-manifest digest differs")
    expected_control_ledger = limit_event_control_exception_partition(
        expected_control_ancestries,
        limit_authority_sources,
    )
    recorded_control_ledger = test_plan.get("limit_event_control_exception_ledger")
    if problem := limit_exception_ledger_match_problem(
        recorded_control_ledger,
        expected_control_ledger,
        "CONTROL_ANCESTRY",
    ):
        fail(f"limit-event control exception ledger differs: {problem}")
    control_ledger_sha256 = canonical_json_sha256(expected_control_ledger)
    if (
        test_plan.get("limit_event_control_exception_ledger_sha256")
        != control_ledger_sha256
        or canonical_json_sha256(recorded_control_ledger) != control_ledger_sha256
        or evidence.get("limit_event_control_exception_ledger_sha256")
        != control_ledger_sha256
    ):
        fail("limit-event control exception-ledger digest differs")
    expected_entry_paths = limit_event_entry_call_path_manifest(limit_authority_sources)
    recorded_entry_paths = test_plan.get("limit_event_entry_call_paths")
    if recorded_entry_paths != expected_entry_paths:
        fail("limit-event entry-call-path review manifest differs")
    entry_paths_sha256 = canonical_json_sha256(expected_entry_paths)
    if (
        test_plan.get("limit_event_entry_call_paths_sha256") != entry_paths_sha256
        or canonical_json_sha256(recorded_entry_paths) != entry_paths_sha256
        or evidence.get("limit_event_entry_call_paths_sha256") != entry_paths_sha256
    ):
        fail("limit-event entry-call-path review-manifest digest differs")
    expected_entry_ledger = limit_event_entry_exception_partition(
        expected_entry_paths,
        limit_authority_sources,
    )
    recorded_entry_ledger = test_plan.get("limit_event_entry_exception_ledger")
    if problem := limit_exception_ledger_match_problem(
        recorded_entry_ledger,
        expected_entry_ledger,
        "ENTRY_PATH",
    ):
        fail(f"limit-event entry exception ledger differs: {problem}")
    entry_ledger_sha256 = canonical_json_sha256(expected_entry_ledger)
    if (
        test_plan.get("limit_event_entry_exception_ledger_sha256")
        != entry_ledger_sha256
        or canonical_json_sha256(recorded_entry_ledger) != entry_ledger_sha256
        or evidence.get("limit_event_entry_exception_ledger_sha256")
        != entry_ledger_sha256
    ):
        fail("limit-event entry exception-ledger digest differs")
    if problem := limit_exception_partition_freeze_problem(
        expected_entry_ledger,
        expected_control_ledger,
    ):
        fail(f"limit-event exception partition freeze differs: {problem}")
    expected_reconciler = limit_exception_reconciler_manifest()
    recorded_reconciler = test_plan.get("limit_exception_reconciler")
    if recorded_reconciler != expected_reconciler:
        fail("limit-event exception reconciler manifest differs")
    reconciler_manifest_sha256 = canonical_json_sha256(expected_reconciler)
    if (
        test_plan.get("limit_exception_reconciler_sha256") != reconciler_manifest_sha256
        or canonical_json_sha256(recorded_reconciler) != reconciler_manifest_sha256
        or evidence.get("limit_exception_reconciler_sha256")
        != reconciler_manifest_sha256
    ):
        fail("limit-event exception reconciler-manifest digest differs")
    expected_shared_state = limit_shared_state_authority_manifest(
        limit_authority_sources
    )
    recorded_shared_state = test_plan.get("limit_shared_state_authority")
    if recorded_shared_state != expected_shared_state:
        fail("limit shared-state authority review manifest differs")
    shared_state_sha256 = canonical_json_sha256(expected_shared_state)
    if (
        test_plan.get("limit_shared_state_authority_sha256") != shared_state_sha256
        or canonical_json_sha256(recorded_shared_state) != shared_state_sha256
        or evidence.get("limit_shared_state_authority_sha256") != shared_state_sha256
    ):
        fail("limit shared-state authority review-manifest digest differs")
    expected_site_proofs = limit_runtime_site_proof_manifest(
        expected_runtime_cases,
        expected_owner_bodies,
    )
    recorded_site_proofs = test_plan.get("limit_runtime_site_proofs")
    if (
        not isinstance(recorded_site_proofs, dict)
        or tuple(recorded_site_proofs) != tuple(expected_site_proofs)
        or recorded_site_proofs != expected_site_proofs
    ):
        fail("limit runtime dual-site proof manifest differs")
    site_proofs_sha256 = canonical_json_sha256(expected_site_proofs)
    if (
        test_plan.get("limit_runtime_site_proofs_sha256") != site_proofs_sha256
        or canonical_json_sha256(recorded_site_proofs) != site_proofs_sha256
    ):
        fail("limit runtime dual-site proof-manifest digest differs")
    expected_observations = limit_event_observation_manifest(
        row_map,
        expected_test_bodies,
        expected_owner_bodies,
    )
    recorded_observations = test_plan.get("limit_event_observations")
    if (
        not isinstance(recorded_observations, dict)
        or tuple(recorded_observations) != tuple(LIMIT_EVENT_SPECS)
        or recorded_observations != expected_observations
    ):
        fail("limit-event runtime-observation review manifest differs")
    for event_id, record in recorded_observations.items():
        if not isinstance(record, dict) or tuple(record) != (
            "owner_body",
            "owner_attribute_chain_sha256",
            "owner_body_sha256",
            "charged_limit_tests",
        ):
            fail(f"limit-event runtime-observation fields differ for {event_id}")
    observations_sha256 = canonical_json_sha256(expected_observations)
    if (
        test_plan.get("limit_event_observations_sha256") != observations_sha256
        or canonical_json_sha256(recorded_observations) != observations_sha256
    ):
        fail("limit-event runtime-observation review-manifest digest differs")
    source_set_sha256, validated_commit = require_execution_evidence(
        evidence, used_tests, test_owners, qualified_tests
    )
    reviews = require_phase_reviews(
        evidence.get("reviews"),
        "PASS_IMPLEMENTATION",
        contract_set_sha256,
        review_payload_sha256(evidence),
        source_set_sha256,
        validated_commit,
    )
    require_review_receipt_verification(
        evidence.get("review_receipt_verification"),
        "implementation",
        CLOSEOUT_EVIDENCE,
        reviews,
    )
    if package.get("implementation_reviews") != reviews:
        fail("machine summary implementation reviews differ from closeout evidence")
    if package.get("validation_evidence") != str(CLOSEOUT_EVIDENCE.relative_to(ROOT)):
        fail("machine summary closeout-evidence path differs")


def require_public_recovery_api() -> None:
    authority_sources = {
        relative: (ROOT / relative).read_text(encoding="utf-8")
        for relative in limit_production_source_paths()
    }
    store = production_rust(ROOT / "crates/sley-store/src/lib.rs")
    txn = production_rust(ROOT / "crates/sley-txn/src/repository.rs")
    txn_lib = production_rust(ROOT / "crates/sley-txn/src/lib.rs")
    refs = production_rust(ROOT / "crates/sley-repo/src/refs.rs")
    gc = production_rust(ROOT / "crates/sley-repo/src/gc.rs")
    txn_normal = normal_build_rust(
        authority_sources["crates/sley-txn/src/repository.rs"]
    )

    recovery_sources = {
        "crates/sley-store/src/lib.rs": store,
        "crates/sley-txn/src/repository.rs": txn,
        "crates/sley-repo/src/refs.rs": refs,
        "crates/sley-repo/src/gc.rs": gc,
    }
    for relative, expected in EXPECTED_PUBLIC_RECOVERY_SURFACE.items():
        found = public_recovery_surface(recovery_sources[relative])
        if found != tuple(sorted(expected)):
            fail(
                f"production public recovery surface differs in {relative}: "
                f"expected {tuple(sorted(expected))!r}, found {found!r}"
            )
    if problem := public_api_baseline_problem():
        fail(problem)

    for obsolete in (
        "RecoveryAncestryLimits",
        "verify_recovery_ancestries_with_maintenance",
        "RecoveryRevisionFacts",
        "retained_revisions",
    ):
        if re.search(rf"\b{re.escape(obsolete)}\b", txn_normal):
            fail(f"production transaction source retains superseded API {obsolete}")
    if re.search(r"\.\s*object_path\s*\(", txn_normal):
        fail("transaction recovery bypasses the bounded store metadata bridge")

    require_impl_method(
        store,
        "ObjectStore",
        "bounded_object_len",
        r"pub\s+fn\s+bounded_object_len\s*\(\s*&self\s*,\s*"
        r"object_id\s*:\s*ObjectId\s*,?\s*\)\s*->\s*Result\s*<\s*u64\s*>",
        "exact public bounded object-length API",
    )
    if problem := bounded_object_len_body_problem(store):
        fail(f"bounded object-length bridge differs: {problem}")

    receipt_metadata_signatures = rust_direct_function_signature(
        txn,
        "recovery_receipt_metadata",
        "private",
    )
    receipt_metadata_pattern = (
        r"fn\s+recovery_receipt_metadata\s*\(\s*path\s*:\s*&Path\s*,?\s*\)\s*"
        r"->\s*Result\s*<\s*fs\s*::\s*Metadata\s*,\s*CommitError\s*>"
    )
    if (
        len(receipt_metadata_signatures) != 1
        or re.fullmatch(
            receipt_metadata_pattern,
            receipt_metadata_signatures[0],
            re.DOTALL,
        )
        is None
    ):
        fail(
            "production transaction source lacks one exact private "
            "recovery-receipt metadata bridge"
        )
    if problem := recovery_receipt_metadata_body_problem(txn):
        fail(f"recovery-receipt metadata bridge differs: {problem}")

    require_impl_method(
        txn,
        "TransactionRepository",
        "acquire_exclusive_maintenance",
        r"pub\s+fn\s+acquire_exclusive_maintenance\s*\(\s*&self\s*\)\s*"
        r"->\s*Result\s*<\s*RepositoryMaintenanceGuard\s*,\s*CommitError\s*>",
        "exact public transaction maintenance-acquisition API",
    )
    require_impl_method(
        txn,
        "TransactionRepository",
        "recover_with_maintenance",
        r"pub\s+fn\s+recover_with_maintenance\s*\(\s*&self\s*,\s*"
        r"maintenance\s*:\s*&RepositoryMaintenanceGuard\s*,?\s*\)\s*"
        r"->\s*Result\s*<\s*RecoveryReport\s*,\s*CommitError\s*>",
        "exact public guarded transaction-recovery API",
    )
    require_exact_public_struct_fields(
        txn,
        "RecoveryReport",
        (
            ("removed_object_stages", "u64"),
            ("removed_receipt_stages", "u64"),
            ("removed_head_stages", "u64"),
            ("accepted_transaction_id", "Option<TransactionId>"),
            ("verified_ancestry_transactions", "u64"),
        ),
    )
    require_exact_private_struct_fields(
        txn,
        "RecoveryRevisionClaim",
        (
            ("transaction_id", "TransactionId"),
            ("workspace_id", "WorkspaceId"),
            ("state_root", "StateRoot"),
            ("schema_epoch_id", "SchemaEpochId"),
            ("policy_root_id", "PolicyRootId"),
            ("dependency_roots", "Vec<StateRoot>"),
        ),
    )
    require_exact_private_struct_fields(
        txn,
        "RecoveryAncestryRequest",
        (
            ("first_claim", "RecoveryRevisionClaim"),
            ("head_claim", "RecoveryRevisionClaim"),
        ),
    )
    require_exact_public_struct_fields(
        txn,
        "RecoveryWorkUsage",
        (
            ("receipt_bytes", "u64"),
            ("binding_visits", "u64"),
            ("object_verifications", "u64"),
            ("object_bytes", "u64"),
        ),
    )
    require_exact_public_struct_fields(
        txn,
        "RecoveryAncestryHeadReport",
        (
            ("head_transaction_id", "TransactionId"),
            ("verified_transactions", "u64"),
            ("work", "RecoveryWorkUsage"),
        ),
    )
    require_exact_public_struct_fields(
        txn,
        "RecoveryAncestryReport",
        (
            ("heads", "Vec<RecoveryAncestryHeadReport>"),
            ("verified_transactions", "u64"),
            ("work", "RecoveryWorkUsage"),
        ),
    )
    require_impl_method(
        txn,
        "RecoveryRevisionClaim",
        "new",
        r"pub\s+fn\s+new\s*\(\s*"
        r"transaction_id\s*:\s*TransactionId\s*,\s*workspace_id\s*:\s*WorkspaceId\s*,\s*"
        r"state_root\s*:\s*StateRoot\s*,\s*schema_epoch_id\s*:\s*SchemaEpochId\s*,\s*"
        r"policy_root_id\s*:\s*PolicyRootId\s*,\s*dependency_roots\s*:\s*Vec\s*<\s*StateRoot\s*>\s*,?\s*"
        r"\)\s*->\s*Self",
        "exact RecoveryRevisionClaim constructor",
    )
    require_impl_method(
        txn,
        "RecoveryAncestryRequest",
        "with_claims",
        r"pub\s+fn\s+with_claims\s*\(\s*"
        r"first_claim\s*:\s*RecoveryRevisionClaim\s*,\s*head_claim\s*:\s*RecoveryRevisionClaim\s*,?\s*"
        r"\)\s*->\s*Self",
        "exact RecoveryAncestryRequest constructor",
    )
    if problem := recovery_constructor_bodies_problem(txn):
        fail(f"recovery constructor contract differs: {problem}")
    require_exact_enum_body(
        txn,
        "RecoveryAncestryError",
        "Cycle,LimitExceeded,ClaimMismatch{request_index:u64,claim_index:u64,},Verification(CommitError),",
    )
    if problem := recovery_ancestry_error_traits_problem(txn):
        fail(f"RecoveryAncestryError trait contract differs: {problem}")
    require_impl_method(
        txn,
        "TransactionRepository",
        "verify_branch_recovery_ancestries_with_maintenance",
        r"pub\s+fn\s+verify_branch_recovery_ancestries_with_maintenance\s*\(\s*&self\s*,\s*"
        r"maintenance\s*:\s*&RepositoryMaintenanceGuard\s*,\s*"
        r"requests\s*:\s*&\[RecoveryAncestryRequest\]\s*,?\s*\)\s*"
        r"->\s*Result\s*<\s*RecoveryAncestryReport\s*,\s*RecoveryAncestryError\s*>",
        "exact public branch-recovery verifier",
    )
    require_impl_method(
        txn,
        "TransactionRepository",
        "verify_accepted_recovery_ancestry",
        r"fn\s+verify_accepted_recovery_ancestry\s*\(.*",
        "private accepted-recovery ancestry core",
        visibility="private",
    )
    require_repository_exports(
        txn_lib,
        (
            "AcceptedHead",
            "CommitError",
            "CommitInput",
            "CommitOutput",
            "RecoveryAncestryError",
            "RecoveryAncestryHeadReport",
            "RecoveryAncestryReport",
            "RecoveryAncestryRequest",
            "RecoveryReport",
            "RecoveryRevisionClaim",
            "RecoveryWorkUsage",
            "TransactionRepository",
            "TrustedGenesisInput",
            "VerifiedRevision",
        ),
    )
    require_impl_method(
        refs,
        "BranchRepository",
        "recover_refs_with_maintenance",
        r"pub\s+fn\s+recover_refs_with_maintenance\s*\(\s*&self\s*,\s*"
        r"maintenance\s*:\s*&RepositoryMaintenanceGuard\s*,?\s*\)\s*"
        r"->\s*Result\s*<\s*RefRecoveryReport\s*,\s*BranchError\s*>",
        "exact public guarded ref-recovery API",
    )
    require_exact_public_struct_fields(
        refs,
        "RefRecoveryReport",
        (
            ("removed_branch_stages", "u64"),
            ("removed_ref_stages", "u64"),
            ("visible_branches", "u64"),
            ("orphan_origins", "Vec<OrphanBranchOrigin>"),
            ("verified_ancestry_transactions", "u64"),
        ),
    )
    if problem := ref_recovery_ancestry_binding_problem(refs):
        fail(f"ref recovery ancestry binding differs: {problem}")
    require_exact_public_struct_fields(
        gc,
        "GcReport",
        (
            ("examined_anchors", "Vec<RetentionAnchorKey>"),
            ("retained_roots", "Vec<StateRoot>"),
            ("reachable_objects", "Vec<ObjectId>"),
            ("inventory_objects", "Vec<ObjectId>"),
            ("deletion_candidates", "Vec<ObjectId>"),
            ("inventory_bytes", "u64"),
            ("candidate_bytes", "u64"),
            ("decision", "GcDecision"),
            ("deleted_objects", "Vec<ObjectId>"),
            ("failed_object", "Option<ObjectId>"),
        ),
    )
    require_exact_enum_body(
        gc,
        "GcWitnessRecoveryStatus",
        "RemovedExact,RemovedIncomplete,Absent,",
    )
    enum_match = re.search(
        r"pub\s+enum\s+GcWitnessRecoveryStatus\s*\{(?P<body>[^}]*)\}",
        gc,
        re.DOTALL,
    )
    if enum_match is None:
        fail("production GC source lacks public GcWitnessRecoveryStatus")
    enum_body = re.sub(
        r"^\s*(?:///[^\n]*|#\[[^\]]+\])\s*$",
        "",
        enum_match["body"],
        flags=re.MULTILINE,
    )
    variants = tuple(
        re.findall(
            r"^\s*(RemovedExact|RemovedIncomplete|Absent)\s*,\s*$",
            enum_body,
            re.MULTILINE,
        )
    )
    if variants != ("RemovedExact", "RemovedIncomplete", "Absent"):
        fail(f"GcWitnessRecoveryStatus variants/order differ: {variants!r}")
    residue = re.sub(
        r"^\s*(RemovedExact|RemovedIncomplete|Absent)\s*,\s*$",
        "",
        enum_body,
        flags=re.MULTILINE,
    )
    if residue.strip():
        fail("GcWitnessRecoveryStatus contains an extra production variant or token")
    require_top_level_rust_pattern(
        gc,
        r"pub\s+fn\s+recover_gc_witness\s*\(\s*store\s*:\s*&ObjectStore\s*,\s*"
        r"maintenance\s*:\s*&RepositoryMaintenanceGuard\s*,?\s*\)\s*"
        r"->\s*Result\s*<\s*GcWitnessRecoveryStatus\s*,\s*GcError\s*>",
        "exact public GC-witness recovery API",
    )
    require_production_limit_defaults(authority_sources)


def rust_char_literal_end(source: str, start: int) -> int | None:
    byte_literal = source.startswith("b'", start)
    quote = start + 1 if byte_literal else start
    if quote >= len(source) or source[quote] != "'":
        return None
    cursor = quote + 1
    if cursor >= len(source):
        return None
    if source[cursor] == "\\":
        cursor += 1
        if cursor >= len(source):
            return None
        escape = source[cursor]
        if escape in "nrt\\0'\"":
            cursor += 1
        elif escape == "x":
            digits = source[cursor + 1 : cursor + 3]
            if len(digits) != 2 or re.fullmatch(r"[0-9A-Fa-f]{2}", digits) is None:
                return None
            cursor += 3
        elif escape == "u" and not byte_literal:
            if cursor + 1 >= len(source) or source[cursor + 1] != "{":
                return None
            closing = source.find("}", cursor + 2)
            if closing < 0:
                return None
            digits = source[cursor + 2 : closing]
            hexadecimal = digits.replace("_", "")
            if (
                not 1 <= len(hexadecimal) <= 6
                or re.fullmatch(r"[0-9A-Fa-f_]+", digits) is None
                or re.fullmatch(r"[0-9A-Fa-f]+", hexadecimal) is None
            ):
                return None
            cursor = closing + 1
        else:
            return None
    else:
        if source[cursor] in "'\r\n":
            return None
        cursor += 1
    if cursor >= len(source) or source[cursor] != "'":
        return None
    return cursor + 1


def rust_code_mask(source: str) -> list[bool]:
    """Return positions that are Rust code rather than comments or literals."""
    mask = [True] * len(source)
    index = 0
    while index < len(source):
        if source.startswith("//", index):
            end = source.find("\n", index)
            end = len(source) if end < 0 else end
            mask[index:end] = [False] * (end - index)
            index = end
            continue
        if source.startswith("/*", index):
            depth = 1
            cursor = index + 2
            while cursor < len(source) and depth:
                if source.startswith("/*", cursor):
                    depth += 1
                    cursor += 2
                elif source.startswith("*/", cursor):
                    depth -= 1
                    cursor += 2
                else:
                    cursor += 1
            mask[index:cursor] = [False] * (cursor - index)
            index = cursor
            continue
        prefix_boundary = index == 0 or not (
            source[index - 1].isalnum() or source[index - 1] == "_"
        )
        raw = RUST_RAW_STRING_PREFIX.match(source, index) if prefix_boundary else None
        if raw is not None:
            delimiter = '"' + raw["hashes"]
            cursor = raw.end()
            end = source.find(delimiter, cursor)
            end = len(source) if end < 0 else end + len(delimiter)
            mask[index:end] = [False] * (end - index)
            index = end
            continue
        quote_index = None
        if source[index] == '"':
            quote_index = index
        elif prefix_boundary and source.startswith(('b"', 'c"'), index):
            quote_index = index + 1
        if quote_index is not None:
            cursor = quote_index + 1
            while cursor < len(source):
                if source[cursor] == "\\":
                    cursor += 2
                elif source[cursor] == '"':
                    cursor += 1
                    break
                else:
                    cursor += 1
            mask[index:cursor] = [False] * (cursor - index)
            index = cursor
            continue
        char_end = None
        if source[index] == "'":
            char_end = rust_char_literal_end(source, index)
        elif prefix_boundary and source.startswith("b'", index):
            char_end = rust_char_literal_end(source, index)
        if char_end is not None:
            mask[index:char_end] = [False] * (char_end - index)
            index = char_end
            continue
        index += 1
    return mask


def decode_rust_string_payload(payload: str) -> str | None:
    decoded: list[str] = []
    index = 0
    escapes = {
        "n": "\n",
        "r": "\r",
        "t": "\t",
        "\\": "\\",
        "0": "\0",
        "'": "'",
        '"': '"',
    }
    while index < len(payload):
        character = payload[index]
        if character != "\\":
            decoded.append(character)
            index += 1
            continue
        index += 1
        if index >= len(payload):
            return None
        escape = payload[index]
        if escape in escapes:
            decoded.append(escapes[escape])
            index += 1
            continue
        if escape == "x":
            digits = payload[index + 1 : index + 3]
            if len(digits) != 2 or re.fullmatch(r"[0-9A-Fa-f]{2}", digits) is None:
                return None
            decoded.append(chr(int(digits, 16)))
            index += 3
            continue
        if escape == "u" and index + 1 < len(payload) and payload[index + 1] == "{":
            closing = payload.find("}", index + 2)
            if closing < 0:
                return None
            digits = payload[index + 2 : closing].replace("_", "")
            if not digits or re.fullmatch(r"[0-9A-Fa-f]{1,6}", digits) is None:
                return None
            try:
                decoded.append(chr(int(digits, 16)))
            except ValueError:
                return None
            index = closing + 1
            continue
        if escape in "\r\n":
            if (
                escape == "\r"
                and index + 1 < len(payload)
                and payload[index + 1] == "\n"
            ):
                index += 1
            index += 1
            while index < len(payload) and payload[index] in " \t":
                index += 1
            continue
        return None
    return "".join(decoded)


def rust_string_literal_values(source: str) -> tuple[str, ...]:
    values: list[str] = []
    index = 0
    while index < len(source):
        if source.startswith("//", index):
            end = source.find("\n", index)
            index = len(source) if end < 0 else end
            continue
        if source.startswith("/*", index):
            depth = 1
            cursor = index + 2
            while cursor < len(source) and depth:
                if source.startswith("/*", cursor):
                    depth += 1
                    cursor += 2
                elif source.startswith("*/", cursor):
                    depth -= 1
                    cursor += 2
                else:
                    cursor += 1
            index = cursor
            continue
        prefix_boundary = index == 0 or not (
            source[index - 1].isalnum() or source[index - 1] == "_"
        )
        raw = RUST_RAW_STRING_PREFIX.match(source, index) if prefix_boundary else None
        if raw is not None:
            delimiter = '"' + raw["hashes"]
            payload_start = raw.end()
            closing = source.find(delimiter, payload_start)
            if closing < 0:
                return tuple(values)
            values.append(source[payload_start:closing])
            index = closing + len(delimiter)
            continue
        quote_index = None
        if source[index] == '"':
            quote_index = index
        elif prefix_boundary and source.startswith(('b"', 'c"'), index):
            quote_index = index + 1
        if quote_index is not None:
            cursor = quote_index + 1
            while cursor < len(source):
                if source[cursor] == "\\":
                    cursor += 2
                elif source[cursor] == '"':
                    break
                else:
                    cursor += 1
            if cursor >= len(source):
                return tuple(values)
            decoded = decode_rust_string_payload(source[quote_index + 1 : cursor])
            if decoded is not None:
                values.append(decoded)
            index = cursor + 1
            continue
        char_end = None
        if source[index] == "'":
            char_end = rust_char_literal_end(source, index)
        elif prefix_boundary and source.startswith("b'", index):
            char_end = rust_char_literal_end(source, index)
        if char_end is not None:
            index = char_end
            continue
        index += 1
    return tuple(values)


