def rust_string_literal_values_sha256(values: tuple[str, ...]) -> str:
    payload = json.dumps(
        values,
        ensure_ascii=False,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


def require_rust_scanner_positional_controls() -> None:
    for (
        relative,
        expected_length,
        expected_mask_sha256,
        expected_value_count,
        expected_values_sha256,
    ) in RUST_SCANNER_FROZEN_SOURCE_PARITY:
        source = (ROOT / relative).read_text(encoding="utf-8")
        mask = rust_code_mask(source)
        values = rust_string_literal_values(source)
        if (
            len(source) != expected_length
            or hashlib.sha256(bytes(mask)).hexdigest() != expected_mask_sha256
            or len(values) != expected_value_count
            or rust_string_literal_values_sha256(values) != expected_values_sha256
        ):
            fail(f"positional Rust scanner differs from frozen parity: {relative}")
    for (
        label,
        source,
        expected_mask_sha256,
        expected_values,
    ) in RUST_SCANNER_HOSTILE_PARITY:
        mask = rust_code_mask(source)
        values = rust_string_literal_values(source)
        if hashlib.sha256(bytes(mask)).hexdigest() != expected_mask_sha256:
            fail(f"positional Rust scanner hostile mask differs: {label}")
        if values != expected_values:
            fail(f"positional Rust scanner hostile values differ: {label}")


def matching_delimiter(
    source: str,
    mask: list[bool],
    opening: int,
    open_char: str,
    close_char: str,
) -> int | None:
    depth = 0
    for index in range(opening, len(source)):
        if not mask[index]:
            continue
        if source[index] == open_char:
            depth += 1
        elif source[index] == close_char:
            depth -= 1
            if depth == 0:
                return index
    return None


def skip_non_code_space(source: str, mask: list[bool], index: int) -> int:
    while index < len(source) and (source[index].isspace() or not mask[index]):
        index += 1
    return index


def rust_code_projection(source: str) -> str:
    mask = rust_code_mask(source)
    return "".join(
        character if mask[index] else ("\n" if character == "\n" else " ")
        for index, character in enumerate(source)
    )


def rust_attribute_end(source: str, start: int) -> tuple[int, str] | None:
    if source[start] != "#":
        return None
    cursor = start + 1
    while cursor < len(source) and source[cursor].isspace():
        cursor += 1
    if cursor < len(source) and source[cursor] == "!":
        cursor += 1
        while cursor < len(source) and source[cursor].isspace():
            cursor += 1
    if cursor >= len(source) or source[cursor] != "[":
        return None
    closing = matching_delimiter(source, [True] * len(source), cursor, "[", "]")
    if closing is None:
        return None
    return closing + 1, re.sub(r"\s+", "", source[cursor + 1 : closing])


def rust_attributed_item_end(source: str, attribute_end: int) -> int | None:
    cursor = attribute_end
    while True:
        cursor = skip_non_code_space(source, [True] * len(source), cursor)
        if cursor >= len(source) or source[cursor] != "#":
            break
        attribute = rust_attribute_end(source, cursor)
        if attribute is None:
            break
        cursor = attribute[0]
    if re.match(r"(?:(?:unsafe|default)\s+)?impl\b", source[cursor:]):
        return rust_impl_item_end(source, cursor)
    round_depth = 0
    square_depth = 0
    angle_depth = 0
    semicolon_terminated = (
        re.match(
            r"(?:(?:pub(?:\([^)]*\))?|unsafe|safe|mut)\s+)*"
            r"(?:const(?!\s+fn\b)|static|type|use|let)\b",
            source[cursor:],
        )
        is not None
    )
    expression_brace_end = -1
    for index in range(cursor, len(source)):
        if index <= expression_brace_end:
            continue
        character = source[index]
        if character == "(":
            round_depth += 1
        elif character == ")":
            round_depth -= 1
        elif character == "[":
            square_depth += 1
        elif character == "]":
            square_depth -= 1
        elif character == "<":
            angle_depth += 1
        elif (
            character == ">"
            and angle_depth
            and (index == 0 or source[index - 1] not in "-=")
        ):
            angle_depth -= 1
        elif character == "{" and (round_depth or square_depth or angle_depth):
            closing = matching_delimiter(source, [True] * len(source), index, "{", "}")
            if closing is None:
                return None
            expression_brace_end = closing
            continue
        elif (
            character == "{"
            and round_depth == 0
            and square_depth == 0
            and angle_depth == 0
        ):
            closing = matching_delimiter(source, [True] * len(source), index, "{", "}")
            if closing is None:
                return None
            if semicolon_terminated:
                expression_brace_end = closing
                continue
            end = closing + 1
            while end < len(source) and source[end].isspace():
                end += 1
            return end + 1 if end < len(source) and source[end] in ";," else closing + 1
        elif (
            character in ";,"
            and round_depth == 0
            and square_depth == 0
            and angle_depth == 0
        ):
            return index + 1
        if round_depth < 0 or square_depth < 0 or angle_depth < 0:
            return None
    return None


def rust_impl_item_end(source: str, start: int) -> int | None:
    """Return one impl extent without treating where-clause commas as terminators."""
    cursor = start
    while True:
        cursor = skip_non_code_space(source, [True] * len(source), cursor)
        if cursor >= len(source) or source[cursor] != "#":
            break
        attribute = rust_attribute_end(source, cursor)
        if attribute is None:
            return None
        cursor = attribute[0]
    header = re.match(r"(?:(?:unsafe|default)\s+)?impl\b", source[cursor:])
    if header is None:
        return None

    round_depth = 0
    square_depth = 0
    angle_depth = 0
    expression_brace_end = -1
    for index in range(cursor + header.end(), len(source)):
        if index <= expression_brace_end:
            continue
        character = source[index]
        if character == "(":
            round_depth += 1
        elif character == ")":
            round_depth -= 1
        elif character == "[":
            square_depth += 1
        elif character == "]":
            square_depth -= 1
        elif character == "<":
            angle_depth += 1
        elif (
            character == ">"
            and angle_depth
            and (index == 0 or source[index - 1] not in "-=")
        ):
            angle_depth -= 1
        elif character == "{" and (round_depth or square_depth or angle_depth):
            closing = matching_delimiter(source, [True] * len(source), index, "{", "}")
            if closing is None:
                return None
            expression_brace_end = closing
            continue
        elif (
            character == "{"
            and round_depth == 0
            and square_depth == 0
            and angle_depth == 0
        ):
            closing = matching_delimiter(source, [True] * len(source), index, "{", "}")
            if closing is None:
                return None
            return closing + 1
        elif (
            character == ";"
            and round_depth == 0
            and square_depth == 0
            and angle_depth == 0
        ):
            return None
        if round_depth < 0 or square_depth < 0 or angle_depth < 0:
            return None
    return None


def rust_projection_delimiter_problem(source: str) -> str | None:
    stack: list[str] = []
    pairs = {")": "(", "]": "[", "}": "{"}
    for character in source:
        if character in "([{":
            stack.append(character)
        elif character in pairs:
            if not stack or stack.pop() != pairs[character]:
                return f"unbalanced projected delimiter {character}"
    if stack:
        return f"unclosed projected delimiters: {''.join(stack)!r}"
    return None


def require_balanced_rust_projection(source: str) -> str:
    if problem := rust_projection_delimiter_problem(source):
        fail(problem)
    return source


def unconditional_rust(source: str) -> str:
    """Project code and mask every cfg/cfg_attr-gated item conservatively."""
    projected = rust_code_projection(source)
    if re.search(r"#\s*!\s*\[\s*cfg(?:_attr)?\s*\(", projected):
        fail("production owner source contains an inner cfg/cfg_attr gate")
    ranges: list[tuple[int, int]] = []
    for match in re.finditer(r"#\s*\[", projected):
        attribute = rust_attribute_end(projected, match.start())
        if attribute is None:
            continue
        end, normalized = attribute
        if not (normalized.startswith("cfg(") or normalized.startswith("cfg_attr(")):
            continue
        item_end = rust_attributed_item_end(projected, end)
        if item_end is None:
            fail("cannot isolate a cfg-gated Rust item")
        ranges.append((match.start(), item_end))
    output = list(projected)
    for start, end in ranges:
        for index in range(start, end):
            if output[index] != "\n":
                output[index] = " "
    return require_balanced_rust_projection("".join(output))


