S20_530_RECOVERY_ANCESTRY_HOOK_SHA256 = (
    "2b9acf0831d86940b53ad28287496656472f6b57846fbd5d94a40d90f7996cc8"
)


def rust_function_context(
    source: str,
    projected: str,
    position: int,
) -> tuple[str, str]:
    owner_ranges = rust_owner_ranges(source, projected)
    candidates: list[tuple[int, str, str]] = []
    for match in re.finditer(rf"\bfn\s+(?P<name>{RUST_IDENTIFIER})\b", projected):
        opening = public_function_signature_end(projected, match.start())
        if opening is None or projected[opening] != "{":
            continue
        closing = matching_delimiter(
            projected,
            [True] * len(projected),
            opening,
            "{",
            "}",
        )
        if closing is None or not opening < position < closing:
            continue
        candidates.append(
            (
                closing - opening,
                rust_owner_chain(owner_ranges, match.start()),
                semantic_rust_identifier(match["name"]),
            )
        )
    if not candidates:
        return "<crate>", "<module>"
    _span, owner, function = min(candidates)
    return owner, function


def recovery_ancestry_hook_gate_record(
    sources: dict[str, str],
) -> tuple[RecoveryAncestryHookGateSpec, ...]:
    records: list[RecoveryAncestryHookGateSpec] = []
    for relative, source in sources.items():
        projected = rust_code_projection(source)
        for match in re.finditer(r"#\s*\[", projected):
            attribute = rust_attribute_end(projected, match.start())
            raw_attribute = rust_attribute_end(source, match.start())
            if attribute is None or raw_attribute is None:
                continue
            feature_gate = (
                "s20-530-test-hooks" in source[match.start() : raw_attribute[0]]
            )
            if not feature_gate and raw_attribute[1] != "cfg(test)":
                continue
            owner, function = rust_function_context(
                source,
                projected,
                match.start(),
            )
            protected = (
                relative,
                owner,
                function,
            ) in S20_530_RECOVERY_ANCESTRY_PROTECTED_FUNCTIONS
            if not protected and not feature_gate:
                continue
            item_end = rust_attributed_item_end(projected, attribute[0])
            if item_end is None:
                fail("cannot isolate a recovery-ancestry hook gate")
            records.append(
                RecoveryAncestryHookGateSpec(
                    relative,
                    owner,
                    function,
                    raw_attribute[1],
                    normalize_rust_tokens(source[match.start() : item_end]),
                )
            )
    return tuple(
        sorted(
            records,
            key=lambda record: tuple(record),
        )
    )


def recovery_ancestry_hook_gate_problem(sources: dict[str, str]) -> str | None:
    expected = tuple(
        sorted(
            (
                spec._replace(item=normalize_rust_tokens(spec.item))
                for spec in S20_530_RECOVERY_ANCESTRY_HOOK_GATES
            ),
            key=lambda record: tuple(record),
        )
    )
    actual = recovery_ancestry_hook_gate_record(sources)
    if actual != expected:
        return f"15-site raw gate inventory differs: expected {expected!r}, found {actual!r}"
    return None


def recovery_ancestry_test_hook_authority_problem() -> str | None:
    hook_path = ROOT / "crates/sley-txn/src/recovery_ancestry_test_hook.rs"
    try:
        hook_payload = hook_path.read_bytes()
    except OSError as error:
        return f"cannot read frozen hook module: {error}"
    if hashlib.sha256(hook_payload).hexdigest() != (
        S20_530_RECOVERY_ANCESTRY_HOOK_SHA256
    ):
        return "frozen hook module digest differs"
    paths = {
        "crates/sley-txn/src/lib.rs",
        "crates/sley-txn/src/repository.rs",
        "crates/sley-repo/src/refs.rs",
    }
    sources = {
        relative: (ROOT / relative).read_text(encoding="utf-8") for relative in paths
    }
    return recovery_ancestry_hook_gate_problem(sources)


def normal_build_fault_authority_problem(source: str) -> str | None:
    production = normal_build_rust(source)
    for raw_identifier in re.findall(RUST_IDENTIFIER, production):
        identifier = semantic_rust_identifier(raw_identifier)
        snake_segments = identifier.lower().split("_")
        if "Fault" in identifier or "fault" in snake_segments:
            return f"fault authority survives normal build: {identifier}"
    return None


def exact_cfg_test_item(
    source: str, kind: str, name: str, owner: str
) -> tuple[str, str] | None:
    projected = rust_code_projection(source)
    mask = rust_code_mask(source)
    owner_ranges = rust_owner_ranges(source, projected)
    pattern = re.compile(
        rf"#\s*\[\s*cfg\s*\(\s*test\s*\)\s*\]\s*"
        rf"(?P<kind>{re.escape(kind)})\s+{re.escape(name)}\b"
    )
    matches = tuple(pattern.finditer(projected))
    definitions = tuple(
        re.finditer(rf"\b{re.escape(kind)}\s+{re.escape(name)}\b", projected)
    )
    if len(matches) != 1 or len(definitions) != 1:
        return None
    match = matches[0]
    kind_start = match.start("kind")
    if (
        has_preceding_code_attribute(source, mask, match.start())
        or rust_owner_chain(owner_ranges, kind_start) != owner
    ):
        return None
    if kind == "fn":
        opening = public_function_signature_end(projected, kind_start)
        if opening is None or projected[opening] != "{":
            return None
    elif kind == "enum":
        opening = projected.find("{", definitions[0].end())
        if opening < 0:
            return None
    else:
        fail(f"unknown exact cfg(test) item kind: {kind}")
    closing = matching_delimiter(projected, [True] * len(projected), opening, "{", "}")
    if closing is None:
        return None
    return source[kind_start:opening], source[opening + 1 : closing]


def durability_cut_row_authority() -> dict[str, tuple[str, str, str, str, str]]:
    rows: dict[str, tuple[str, str, str, str, str]] = {}
    for relative, definition in TEST_ONLY_DURABILITY_CUT_AUTHORITY.items():
        enum_name = definition["enum"]
        helpers_by_row = {
            row_id: (owner, helper)
            for owner, helper, helper_rows in definition["helpers"]
            for row_id in helper_rows
        }
        for variant, _payload, row_id in definition["variants"]:
            owner, helper = helpers_by_row[row_id]
            rows[row_id] = relative, enum_name, variant, owner, helper
    return rows


def expected_private_enum_body(
    variants: tuple[tuple[str, tuple[str, str] | None, str], ...],
) -> str:
    pieces: list[str] = []
    for name, payload, _row_id in variants:
        if payload is None:
            pieces.append(f"{name},")
        else:
            field, field_type = payload
            pieces.append(f"{name}{{{field}:{field_type},}},")
    return "".join(pieces)


def mapped_row_test_name(row_id: str, entry: object) -> str | None:
    if not isinstance(entry, dict):
        return None
    if row_id in EVIDENCE_FAMILIES:
        subcases = entry.get("subcases")
        if not isinstance(subcases, dict) or len(subcases) != 1:
            return None
        entry = next(iter(subcases.values()))
        if not isinstance(entry, dict):
            return None
    tests = entry.get("tests")
    if not isinstance(tests, list) or len(tests) != 1 or not isinstance(tests[0], str):
        return None
    return tests[0]


def named_call_argument_ranges(source: str, name: str) -> tuple[tuple[int, int], ...]:
    projected = rust_code_projection(source)
    ranges: list[tuple[int, int]] = []
    for match in re.finditer(rf"\b{re.escape(name)}\s*\(", projected):
        opening = projected.find("(", match.start(), match.end())
        closing = matching_delimiter(
            projected, [True] * len(projected), opening, "(", ")"
        )
        if closing is not None:
            ranges.append((opening + 1, closing))
    return tuple(ranges)


def split_rust_call_arguments(value: str) -> tuple[str, ...] | None:
    projected = rust_code_projection(value)
    mask = rust_code_mask(value)
    parts: list[str] = []
    start = 0
    round_depth = square_depth = brace_depth = angle_depth = 0
    for index, character in enumerate(projected):
        if not mask[index]:
            continue
        if character == "(":
            round_depth += 1
        elif character == ")":
            round_depth -= 1
        elif character == "[":
            square_depth += 1
        elif character == "]":
            square_depth -= 1
        elif character == "{":
            brace_depth += 1
        elif character == "}":
            brace_depth -= 1
        elif character == "<":
            angle_depth += 1
        elif (
            character == ">"
            and angle_depth
            and (index == 0 or projected[index - 1] not in "-=")
        ):
            angle_depth -= 1
        elif character == "," and not any(
            (round_depth, square_depth, brace_depth, angle_depth)
        ):
            part = value[start:index].strip()
            if part:
                parts.append(part)
            start = index + 1
        if min(round_depth, square_depth, brace_depth, angle_depth) < 0:
            return None
    if any((round_depth, square_depth, brace_depth, angle_depth)):
        return None
    tail = value[start:].strip()
    if tail:
        parts.append(tail)
    return tuple(parts)


def exact_bound_method_call_arguments(
    statement: str,
    identifier: str,
    receiver: str,
    method: str,
) -> tuple[str, ...] | None:
    projected = rust_code_projection(statement)
    match = re.match(
        rf"^\s*let\s+{re.escape(identifier)}\s*=\s*"
        rf"{re.escape(receiver)}\s*\.\s*{re.escape(method)}\s*\(",
        projected,
    )
    if match is None:
        return None
    opening = projected.rfind("(", 0, match.end())
    closing = matching_delimiter(
        projected,
        [True] * len(projected),
        opening,
        "(",
        ")",
    )
    if closing is None or projected[closing + 1 :].strip() != ";":
        return None
    return split_rust_call_arguments(statement[opening + 1 : closing])


def durability_cut_constructor_expression(
    body: str,
    match: re.Match[str],
    payload: tuple[str, str] | None,
) -> tuple[int, int, str, str | None] | None:
    projected = rust_code_projection(body)
    start = match.start()
    cursor = match.end()
    while cursor < len(projected) and projected[cursor].isspace():
        cursor += 1
    if payload is None:
        if cursor < len(projected) and projected[cursor] in "{(":
            return None
        return start, match.end(), body[start : match.end()], None
    if cursor >= len(projected) or projected[cursor] != "{":
        return None
    closing = matching_delimiter(projected, [True] * len(projected), cursor, "{", "}")
    if closing is None:
        return None
    parts = split_top_level_rust_commas(body[cursor + 1 : closing])
    if len(parts) != 1 or ":" not in parts[0]:
        return None
    field, value = parts[0].split(":", 1)
    if normalize_rust_tokens(field) != payload[0] or not code_only_normalized(value):
        return None
    return start, closing + 1, body[start : closing + 1], code_only_normalized(value)


def durability_cut_test_binding_problem(
    body: str,
    row_id: str,
    enum_name: str,
    variant: str,
    payload: tuple[str, str] | None,
    helper: str,
    all_helpers: tuple[str, ...],
    all_variants: tuple[tuple[str, str], ...],
) -> str | None:
    expected_calls = durability_cut_call_count(row_id)
    call_ranges = named_call_argument_ranges(body, helper)
    if len(call_ranges) != expected_calls:
        return f"does not call {helper} exactly {expected_calls} time(s)"
    helper_calls = tuple(
        found for found in all_helpers if named_call_argument_ranges(body, found)
    )
    if helper_calls != (helper,):
        return "calls an extra or wrong durability-cut helper"
    projected_body = rust_code_projection(body)
    constructors: list[tuple[str, str, tuple[int, int, str, str | None] | None]] = []
    for found_enum, found_variant in all_variants:
        for match in re.finditer(
            rf"\b{re.escape(found_enum)}\s*::\s*{re.escape(found_variant)}\b",
            projected_body,
        ):
            found_payload = (
                payload
                if (found_enum, found_variant)
                == (
                    enum_name,
                    variant,
                )
                else None
            )
            constructors.append(
                (
                    found_enum,
                    found_variant,
                    durability_cut_constructor_expression(
                        body,
                        match,
                        found_payload,
                    ),
                )
            )
    constructors.sort(key=lambda item: len(body) if item[2] is None else item[2][0])
    if len(constructors) != expected_calls or any(
        constructor[:2] != (enum_name, variant) for constructor in constructors
    ):
        return "constructs an extra or wrong durability cut"
    if any(constructor[2] is None for constructor in constructors):
        return "constructs the expected durability cut with the wrong shape"
    parsed = tuple(constructor[2] for constructor in constructors)
    assert all(item is not None for item in parsed)
    expressions = tuple(item for item in parsed if item is not None)
    for call_range in call_ranges:
        inside = tuple(
            expression
            for expression in expressions
            if call_range[0] <= expression[0] and expression[1] <= call_range[1]
        )
        if len(inside) != 1:
            return "does not pass exactly one expected cut to every helper call"
    if payload is not None and len({expression[3] for expression in expressions}) != 1:
        return "repeated durability-cut payload identity differs"
    for found_enum in {
        candidate_enum for candidate_enum, _candidate_variant in all_variants
    }:
        if found_enum != enum_name and re.search(
            rf"\b{re.escape(found_enum)}\b", projected_body
        ):
            return "references a foreign durability-cut enum"
    return None


def require_test_only_durability_cut_authority(
    sources: dict[str, str], row_map: dict[str, object]
) -> None:
    if problem := durability_cut_metadata_problem(TEST_ONLY_DURABILITY_CUT_AUTHORITY):
        fail(f"test-only durability-cut metadata differs: {problem}")
    row_authority = durability_cut_row_authority()
    all_variants = tuple(
        (definition["enum"], variant)
        for definition in TEST_ONLY_DURABILITY_CUT_AUTHORITY.values()
        for variant, _payload, _row_id in definition["variants"]
    )
    all_helpers = tuple(
        helper
        for definition in TEST_ONLY_DURABILITY_CUT_AUTHORITY.values()
        for _owner, helper, _rows in definition["helpers"]
    )
    for relative, definition in TEST_ONLY_DURABILITY_CUT_AUTHORITY.items():
        source = sources[relative]
        projected = rust_code_projection(source)
        for match in re.finditer(r"#\s*\[", projected):
            attribute = rust_attribute_end(projected, match.start())
            if attribute is not None and attribute[1] in {
                "cfg(any(test))",
                "cfg(all(test))",
            }:
                fail(f"{relative} uses a non-exact test cfg gate")
        expected_enums = {definition["enum"]}
        found_enums = {
            semantic_rust_identifier(match["name"])
            for match in re.finditer(
                rf"\benum\s+(?P<name>{RUST_IDENTIFIER}DurabilityCut)\b",
                projected,
            )
        }
        if found_enums != expected_enums:
            fail(f"{relative} durability-cut enum authority differs")
        expected_helpers = {helper for _owner, helper, _rows in definition["helpers"]}
        found_helpers = {
            semantic_rust_identifier(match["name"])
            for match in re.finditer(
                rf"\bfn\s+(?P<name>{RUST_IDENTIFIER}durability_cut)\b",
                projected,
            )
        }
        if found_helpers != expected_helpers:
            fail(f"{relative} durability-cut helper authority differs")
        enum_name = definition["enum"]
        enum_item = exact_cfg_test_item(source, "enum", enum_name, "<crate>")
        if enum_item is None:
            fail(f"{relative} lacks one direct exact #[cfg(test)] {enum_name}")
        expected_body = expected_private_enum_body(definition["variants"])
        if normalize_rust_tokens(enum_item[1]) != normalize_rust_tokens(expected_body):
            fail(f"{relative} {enum_name} variants or payloads differ")
        for owner, helper, _rows in definition["helpers"]:
            item = exact_cfg_test_item(source, "fn", helper, owner)
            if item is None:
                fail(f"{relative} lacks direct exact #[cfg(test)] helper {helper}")
            signature = normalize_rust_tokens(item[0])
            if (
                len(
                    re.findall(
                        rf"(?:\(|,)cut:{re.escape(enum_name)}(?:,|\))", signature
                    )
                )
                != 1
                or "Option<" in signature
                or not code_contains_token(item[1], "cut")
            ):
                fail(f"{relative} helper {helper} lacks one exact cut parameter/use")
        production = normal_build_rust(source)
        for identifier in (
            enum_name,
            *(variant for variant, _payload, _row_id in definition["variants"]),
            *expected_helpers,
        ):
            if re.search(rf"\b{re.escape(identifier)}\b", production):
                fail(f"{relative} test selector survives normal build: {identifier}")

    for row_id, (relative, enum_name, variant, _owner, helper) in row_authority.items():
        test = mapped_row_test_name(row_id, row_map.get(row_id))
        if test is None:
            fail(f"{row_id} lacks one exact durability-cut test")
        definitions = [
            (source_relative, definition)
            for source_relative, source in sources.items()
            if (definition := exact_test_definition(source, test)) is not None
        ]
        if len(definitions) != 1 or definitions[0][0] != relative:
            fail(f"{row_id} durability-cut test owner differs")
        body = definitions[0][1][0]
        if problem := durability_cut_test_binding_problem(
            body,
            row_id,
            enum_name,
            variant,
            DURABILITY_CUT_PAYLOADS.get(row_id),
            helper,
            all_helpers,
            all_variants,
        ):
            fail(f"{row_id} {problem}")


def durability_cut_statement_problem(
    statement: str,
    enum_name: str,
    variant: str,
    payload: tuple[str, str] | None,
    helper: str,
) -> str | None:
    if len(named_call_argument_ranges(statement, helper)) != 1:
        return f"does not invoke {helper} exactly once"
    projected = rust_code_projection(statement)
    matches = tuple(
        re.finditer(
            rf"\b{re.escape(enum_name)}\s*::\s*{re.escape(variant)}\b",
            projected,
        )
    )
    if len(matches) != 1:
        return "does not construct its exact durability selector once"
    constructor = durability_cut_constructor_expression(
        statement,
        matches[0],
        payload,
    )
    if constructor is None:
        return "constructs its durability selector with the wrong shape"
    call = named_call_argument_ranges(statement, helper)[0]
    if not (call[0] <= constructor[0] and constructor[1] <= call[1]):
        return "does not pass its durability selector to the fault helper"
    return None


def exact_recorded_let_range(
    body: str,
    identifier: str,
    statement: object,
) -> tuple[int, int] | None:
    if not isinstance(statement, str):
        return None
    bindings = top_level_let_statement_ranges(body, identifier)
    if len(bindings) != 1 or normalize_rust_tokens(bindings[0][2]) != (
        normalize_rust_tokens(statement)
    ):
        return None
    if not exact_direct_statement_present(body, statement):
        return None
    return bindings[0][0], bindings[0][1]


def durability_snapshot_phases(row_id: str) -> tuple[str, ...]:
    return (
        "before_fault",
        *(f"after_{operation}" for operation in durability_operation_keys(row_id)),
    )


def durability_owner_receiver(relative: str) -> str:
    try:
        return {
            "crates/sley-store/src/lib.rs": "store",
            "crates/sley-txn/src/repository.rs": "repository",
            "crates/sley-repo/src/refs.rs": "branch_repository",
        }[relative]
    except KeyError:
        fail(f"{relative} lacks a non-GC durability receiver")


def durability_fault_target_arguments(
    statement: str,
    identifier: str,
    receiver: str,
    helper: str,
    enum_name: str,
    variant: str,
    payload: tuple[str, str] | None,
) -> tuple[str, ...] | None:
    arguments = exact_bound_method_call_arguments(
        statement,
        identifier,
        receiver,
        helper,
    )
    if arguments is None or not arguments:
        return None
    projected = rust_code_projection(statement)
    matches = tuple(
        re.finditer(
            rf"\b{re.escape(enum_name)}\s*::\s*{re.escape(variant)}\b",
            projected,
        )
    )
    if len(matches) != 1:
        return None
    constructor = durability_cut_constructor_expression(
        statement,
        matches[0],
        payload,
    )
    if constructor is None or normalize_rust_tokens(arguments[-1]) != (
        normalize_rust_tokens(constructor[2])
    ):
        return None
    return tuple(normalize_rust_tokens(argument) for argument in arguments[:-1])


def durability_witness_path_binding_problem(
    statement: str,
    identifier: str,
) -> str | None:
    projected = rust_code_projection(statement)
    match = re.match(
        rf"^\s*let\s+{re.escape(identifier)}\s*=\s*owner_root\s*\.\s*join\s*\(",
        projected,
    )
    if match is None:
        return f"{identifier} is not a direct owner-root join chain"
    cursor = projected.rfind("(", 0, match.end())
    joins = 0
    while True:
        closing = matching_delimiter(
            projected,
            [True] * len(projected),
            cursor,
            "(",
            ")",
        )
        if closing is None or not statement[cursor + 1 : closing].strip():
            return f"{identifier} contains an empty or unbalanced join"
        joins += 1
        tail = projected[closing + 1 :]
        next_join = re.match(r"\s*\.\s*join\s*\(", tail)
        if next_join is None:
            if tail.strip() != ";":
                return f"{identifier} contains non-join path authority"
            break
        cursor = closing + 1 + tail.find("(", 0, next_join.end())
    if joins < 1:
        return f"{identifier} lacks one owner-root-relative component"
    return None


def durability_snapshot_binding_problem(
    body: str,
    relative: str,
    row_id: str,
    operation_ranges: dict[str, tuple[int, int]],
    tree_assertions: object,
    path_assertions: object,
) -> str | None:
    root_expressions = {
        "crates/sley-store/src/lib.rs": "store.root()",
        "crates/sley-txn/src/repository.rs": "repository.root()",
        "crates/sley-repo/src/refs.rs": "branch_repository.root()",
    }
    try:
        root_expression = root_expressions[relative]
    except KeyError:
        return "has no durability snapshot owner-root authority"
    owner_root = exact_snapshot_binding_range(
        body,
        "owner_root",
        f"let owner_root = {root_expression};",
    )
    if owner_root is None:
        return "owner root is not bound to the fault-helper receiver"

    path_ranges: dict[str, tuple[int, int]] = {}
    for name in ("primary_path", "secondary_path"):
        bindings = top_level_let_statement_ranges(body, name)
        if len(bindings) != 1:
            return f"{name} is not bound exactly once"
        start, end, statement = bindings[0]
        if problem := durability_witness_path_binding_problem(statement, name):
            return problem
        path_ranges[name] = (start, end)
    if owner_root[1] > min(start for start, _end in path_ranges.values()):
        return "witness paths are bound before the owner root"

    tree_helper = snapshot_helper_path(relative, "exact_tree_snapshot")
    optional_helper = snapshot_helper_path(
        relative,
        "exact_optional_path_snapshot",
    )
    phases = durability_snapshot_phases(row_id)
    snapshot_ranges: dict[str, tuple[int, int]] = {}
    for phase in phases:
        expected = {
            f"{phase}_owner_tree_snapshot": (
                f"let {phase}_owner_tree_snapshot = {tree_helper}(owner_root);"
            ),
            f"{phase}_primary_path_snapshot": (
                f"let {phase}_primary_path_snapshot = {optional_helper}(&primary_path);"
            ),
            f"{phase}_secondary_path_snapshot": (
                f"let {phase}_secondary_path_snapshot = "
                f"{optional_helper}(&secondary_path);"
            ),
        }
        local: list[tuple[int, int]] = []
        for identifier, statement in expected.items():
            found = exact_snapshot_binding_range(body, identifier, statement)
            if found is None:
                return f"{identifier} does not use the frozen snapshot helper"
            snapshot_ranges[identifier] = found
            local.append(found)
        if len({start for start, _end in local}) != 3:
            return f"{phase} snapshot bindings are not distinct"

    before_ends = tuple(
        end
        for identifier, (_start, end) in snapshot_ranges.items()
        if identifier.startswith("before_fault_")
    )
    first_operation = operation_ranges[durability_operation_keys(row_id)[0]]
    if max((*path_ranges.values(), owner_root), key=lambda item: item[1])[1] > min(
        start
        for identifier, (start, _end) in snapshot_ranges.items()
        if identifier.startswith("before_fault_")
    ):
        return "before-fault snapshots precede root or witness-path binding"
    if max(before_ends) > first_operation[0]:
        return "before-fault snapshots do not precede the first fault"

    operation_keys = durability_operation_keys(row_id)
    for index, operation in enumerate(operation_keys):
        phase = f"after_{operation}_"
        local = tuple(
            bounds
            for identifier, bounds in snapshot_ranges.items()
            if identifier.startswith(phase)
        )
        if (
            len(local) != 3
            or min(start for start, _end in local) < (operation_ranges[operation][1])
        ):
            return f"after-{operation} snapshots do not follow its operation"
        if index + 1 < len(operation_keys):
            next_start = operation_ranges[operation_keys[index + 1]][0]
            if max(end for _start, end in local) > next_start:
                return f"after-{operation} snapshots do not precede the next operation"

    expected_pairs = {
        "tree": tuple(
            (
                f"{left}_owner_tree_snapshot",
                f"{right}_owner_tree_snapshot",
            )
            for left, right in zip(phases, phases[1:])
        ),
        "path": tuple(
            (
                f"{left}_{path}_path_snapshot",
                f"{right}_{path}_path_snapshot",
            )
            for path in ("primary", "secondary")
            for left, right in zip(phases, phases[1:])
        ),
    }
    for kind, values in {
        "tree": tree_assertions,
        "path": path_assertions,
    }.items():
        pairs = expected_pairs[kind]
        if (
            not isinstance(values, list)
            or len(values) != len(pairs)
            or any(not isinstance(value, str) for value in values)
        ):
            return f"{kind} assertions do not cover exact consecutive phases"
        for assertion, expected_pair in zip(values, pairs):
            if not exact_direct_statement_present(body, assertion):
                return f"{kind} assertion is not one direct mapped-test statement"
            parsed = exact_comparison_assertion(assertion)
            if parsed is None:
                return f"{kind} evidence is not an exact equality or inequality"
            _macro, operands = parsed
            normalized_operands = tuple(
                code_only_normalized(value) for value in operands
            )
            if set(normalized_operands) != set(expected_pair):
                return (
                    f"{kind} assertion does not compare its exact consecutive snapshots"
                )
    return None


def durability_evidence_problem(
    row_id: str,
    entry: object,
    relative: str,
    body: str,
) -> str | None:
    if not isinstance(entry, dict) or tuple(entry) != DURABILITY_EVIDENCE_FIELDS:
        return "evidence fields/order differ"
    if entry.get("result") != "PASS" or entry.get("fresh_fixture") is not True:
        return "result or fresh-fixture claim differs"
    protocol = durability_retry_protocol(row_id)
    expected_code = DURABILITY_RESULT_CODES[row_id]
    if entry.get("protocol") != protocol:
        return "retry protocol differs"
    if entry.get("expected_result") != expected_code:
        return "injected result code differs"

    operation_bindings = entry.get("operation_bindings")
    operation_keys = durability_operation_keys(row_id)
    if not isinstance(operation_bindings, dict) or tuple(operation_bindings) != (
        operation_keys
    ):
        return "operation-binding vocabulary/order differs"
    authority = durability_cut_row_authority()[row_id]
    _source, enum_name, variant, _owner, helper = authority
    receiver = durability_owner_receiver(relative)
    operation_ranges: dict[str, tuple[int, int]] = {}
    fault_target_arguments: tuple[str, ...] | None = None
    expected_method_calls: dict[str, int] = {}
    for operation, statement in operation_bindings.items():
        identifier = f"{operation}_result"
        found = exact_recorded_let_range(body, identifier, statement)
        if found is None:
            return f"{operation} result is not one exact recorded let statement"
        operation_ranges[operation] = found
        assert isinstance(statement, str)
        if operation in {"first_fault", "second_fault"}:
            if problem := durability_cut_statement_problem(
                statement,
                enum_name,
                variant,
                DURABILITY_CUT_PAYLOADS.get(row_id),
                helper,
            ):
                return f"{operation} {problem}"
            target_arguments = durability_fault_target_arguments(
                statement,
                identifier,
                receiver,
                helper,
                enum_name,
                variant,
                DURABILITY_CUT_PAYLOADS.get(row_id),
            )
            if target_arguments is None:
                return f"{operation} does not use the exact owner receiver and final selector"
            if fault_target_arguments is None:
                fault_target_arguments = target_arguments
            elif target_arguments != fault_target_arguments:
                return "repeated fault helper target arguments differ"
            expected_method_calls[helper] = expected_method_calls.get(helper, 0) + 1
        elif operation in {"first_recovery", "second_recovery"}:
            expected_call = durability_recovery_call(row_id)
            arguments = exact_bound_method_call_arguments(
                statement,
                identifier,
                receiver,
                expected_call,
            )
            if arguments is None:
                return f"{operation} does not invoke exact owner {expected_call} once"
            if named_call_argument_ranges(statement, helper):
                return f"{operation} reuses test-only fault authority"
            expected_method_calls[expected_call] = (
                expected_method_calls.get(expected_call, 0) + 1
            )
        elif operation == "ordinary_retry":
            expected_call = DURABILITY_ORDINARY_CALLS[row_id]
            arguments = exact_bound_method_call_arguments(
                statement,
                identifier,
                receiver,
                expected_call,
            )
            if arguments is None:
                return (
                    f"ordinary retry does not invoke exact owner {expected_call} once"
                )
            if named_call_argument_ranges(statement, helper):
                return "ordinary retry reuses test-only fault authority"
            normalized_arguments = tuple(
                normalize_rust_tokens(argument) for argument in arguments
            )
            if (
                fault_target_arguments is None
                or normalized_arguments != fault_target_arguments
            ):
                return "ordinary retry target arguments differ from the fault helper"
            expected_method_calls[expected_call] = (
                expected_method_calls.get(expected_call, 0) + 1
            )
        else:
            return f"unknown durability operation binding {operation}"
    for method, expected_count in expected_method_calls.items():
        if len(named_call_argument_ranges(body, method)) != expected_count:
            return f"mapped test contains an unbound {method} invocation"
    ordered_ranges = tuple(operation_ranges[key] for key in operation_keys)
    if any(
        left[1] > right[0] for left, right in zip(ordered_ranges, ordered_ranges[1:])
    ):
        return "fault, recovery, and ordinary retry operations are misordered"

    fault_keys = tuple(
        operation
        for operation in operation_keys
        if operation in {"first_fault", "second_fault"}
    )
    result_bindings = entry.get("result_bindings")
    expected_result_binding_keys = tuple(f"{key}_error" for key in fault_keys)
    if not isinstance(result_bindings, dict) or tuple(result_bindings) != (
        expected_result_binding_keys
    ):
        return "fault-error binding vocabulary/order differs"
    error_ranges: dict[str, tuple[int, int]] = {}
    for key, statement in result_bindings.items():
        fault = key.removesuffix("_error")
        expected = (
            f"let {key} = {fault}_result.expect_err("
            f'"expected {fault.replace("_", " ")} durability error");'
        )
        if not isinstance(statement, str) or normalize_rust_tokens(statement) != (
            normalize_rust_tokens(expected)
        ):
            return f"{key} extraction statement differs"
        found = exact_recorded_let_range(body, key, statement)
        if found is None:
            return f"{key} is not extracted exactly once"
        if found[0] < operation_ranges[fault][1]:
            return f"{key} extraction precedes its fault result"
        error_ranges[key] = found

    result_assertions = entry.get("result_assertions")
    result_assertion_keys = (
        *(f"{fault}_code" for fault in fault_keys),
        *(
            f"{operation}_success"
            for operation in operation_keys
            if operation not in fault_keys
        ),
    )
    if not isinstance(result_assertions, dict) or tuple(result_assertions) != (
        result_assertion_keys
    ):
        return "result-assertion vocabulary/order differs"
    assertions = entry.get("assertions")
    if not isinstance(assertions, list):
        return "assertions are not one list"
    assertion_ranges: dict[str, tuple[int, int]] = {}
    for key, assertion in result_assertions.items():
        if not isinstance(assertion, str) or assertion not in assertions:
            return f"{key} result assertion is absent from mapped assertions"
        if key.endswith("_code"):
            fault = key.removesuffix("_code")
            error = f"{fault}_error"
            expected = (
                f"::core::assert_eq!("
                f"{durability_result_projection(row_id, error)}, "
                f"{json.dumps(expected_code)});"
            )
            lower_bound = error_ranges[error][1]
        else:
            operation = key.removesuffix("_success")
            expected = f"::core::assert!({operation}_result.is_ok());"
            lower_bound = operation_ranges[operation][1]
        if normalize_rust_tokens(assertion) != normalize_rust_tokens(expected):
            return f"{key} does not assert the exact bound result"
        starts = exact_direct_statement_starts(body, assertion)
        if len(starts) != 1 or starts[0] < lower_bound:
            return f"{key} assertion is absent, duplicated, or misordered"
        assertion_ranges[key] = (starts[0], starts[0] + len(assertion))

    if problem := durability_snapshot_binding_problem(
        body,
        relative,
        row_id,
        operation_ranges,
        entry.get("tree_assertions"),
        entry.get("path_assertions"),
    ):
        return problem

    tree_helper = snapshot_helper_path(relative, "exact_tree_snapshot")
    optional_helper = snapshot_helper_path(
        relative,
        "exact_optional_path_snapshot",
    )
    snapshot_ranges: dict[str, tuple[tuple[int, int], ...]] = {}
    for phase in durability_snapshot_phases(row_id):
        local: list[tuple[int, int]] = []
        for identifier, statement in (
            (
                f"{phase}_owner_tree_snapshot",
                f"let {phase}_owner_tree_snapshot = {tree_helper}(owner_root);",
            ),
            (
                f"{phase}_primary_path_snapshot",
                f"let {phase}_primary_path_snapshot = "
                f"{optional_helper}(&primary_path);",
            ),
            (
                f"{phase}_secondary_path_snapshot",
                f"let {phase}_secondary_path_snapshot = "
                f"{optional_helper}(&secondary_path);",
            ),
        ):
            found = exact_snapshot_binding_range(body, identifier, statement)
            if found is None:
                return f"{identifier} does not use the frozen snapshot helper"
            local.append(found)
        snapshot_ranges[phase] = tuple(local)
    critical_ranges: list[tuple[int, int]] = [*snapshot_ranges["before_fault"]]
    for operation in operation_keys:
        critical_ranges.append(operation_ranges[operation])
        if operation in fault_keys:
            critical_ranges.append(error_ranges[f"{operation}_error"])
        critical_ranges.append(
            assertion_ranges[
                f"{operation}_{'code' if operation in fault_keys else 'success'}"
            ]
        )
        critical_ranges.extend(snapshot_ranges[f"after_{operation}"])
    if problem := contiguous_code_ranges_problem(
        body,
        tuple(critical_ranges),
        "durability protocol critical window",
    ):
        return problem

    for field in ("tree_assertions", "path_assertions"):
        values = entry.get(field)
        assert isinstance(values, list)
        if any(value not in assertions for value in values):
            return f"{field} contains an assertion absent from mapped assertions"

    report_assertions = entry.get("report_assertions")
    non_fault_keys = tuple(key for key in operation_keys if key not in fault_keys)
    if (
        not isinstance(report_assertions, list)
        or not report_assertions
        or any(not isinstance(value, str) for value in report_assertions)
    ):
        return "report assertions are not one nonempty assertion list"
    covered_reports: set[str] = set()
    for assertion in report_assertions:
        if assertion not in assertions or not exact_direct_statement_present(
            body, assertion
        ):
            return "report assertion is absent from the exact mapped test"
        local = {
            operation
            for operation in non_fault_keys
            if code_contains_token(assertion, f"{operation}_result")
        }
        if len(local) != 1:
            return "report assertion is not bound to one successful protocol result"
        operands = exact_assert_eq_operands(assertion)
        if operands is None:
            return "report assertion is not one exact value comparison"
        operation = next(iter(local))
        result_name = f"{operation}_result"
        normalized_operands = tuple(code_only_normalized(value) for value in operands)
        projections = tuple(
            value
            for value in normalized_operands
            if value.startswith(f"{result_name}.")
        )
        if len(projections) != 1:
            return "report assertion does not directly project its bound result"
        if re.search(
            r"(?:&&|\|\||\btrue\b|\bfalse\b)", rust_code_projection(assertion)
        ):
            return "report assertion contains a self-certified boolean"
        if normalized_operands[0] == normalized_operands[1]:
            return "report assertion is reflexive"
        covered_reports.update(local)
    if covered_reports != set(non_fault_keys):
        return "report assertions do not cover every recovery or ordinary retry"
    return None


def require_durability_result_evidence(
    row_id: str,
    entry: dict[str, object],
    relative: str,
    source: str,
) -> None:
    tests = entry.get("tests")
    if not isinstance(tests, list) or len(tests) != 1 or not isinstance(tests[0], str):
        fail(f"{row_id} lacks one exact durability evidence test")
    definition = exact_test_definition(source, tests[0])
    if definition is None:
        fail(f"{row_id} cannot isolate its durability evidence test")
    if problem := durability_evidence_problem(
        row_id,
        entry,
        relative,
        definition[0],
    ):
        fail(f"{row_id} durability evidence differs: {problem}")


def production_rust(path: Path) -> str:
    return unconditional_rust(path.read_text(encoding="utf-8"))


def direct_code_matches(source: str, pattern: str) -> list[re.Match[str]]:
    mask = [True] * len(source)
    return [
        match
        for match in re.finditer(pattern, source, re.DOTALL)
        if brace_depth_at(source, mask, match.start()) == 0
    ]


def require_rust_pattern(source: str, pattern: str, label: str) -> None:
    if re.search(pattern, source, re.DOTALL) is None:
        fail(f"production Rust source lacks {label}")


def require_top_level_rust_pattern(source: str, pattern: str, label: str) -> None:
    if not direct_code_matches(source, pattern):
        fail(f"production Rust source lacks top-level {label}")


def rust_impl_bodies(source: str, type_name: str) -> tuple[str, ...]:
    bodies: list[str] = []
    pattern = rf"\bimpl\s+{re.escape(type_name)}\s*\{{"
    for match in direct_code_matches(source, pattern):
        opening = source.find("{", match.start(), match.end())
        closing = matching_delimiter(source, [True] * len(source), opening, "{", "}")
        if closing is None:
            fail(f"production impl {type_name} has no closing brace")
        bodies.append(source[opening + 1 : closing])
    return tuple(bodies)


def rust_direct_function_signature(
    body: str, function_name: str, visibility: str
) -> tuple[str, ...]:
    if visibility == "public":
        prefix = r"pub[ \t]+fn"
    elif visibility == "private":
        prefix = r"fn"
    else:
        fail(f"unknown Rust method visibility {visibility!r}")
    matches = direct_code_matches(
        body,
        rf"(?m)^[ \t]*{prefix}[ \t]+{re.escape(function_name)}"
        r"(?:\s*<[^>{};]*>)?\s*\(",
    )
    signatures: list[str] = []
    for match in matches:
        round_depth = 0
        square_depth = 0
        for index in range(match.start(), len(body)):
            character = body[index]
            if character == "(":
                round_depth += 1
            elif character == ")":
                round_depth -= 1
            elif character == "[":
                square_depth += 1
            elif character == "]":
                square_depth -= 1
            elif character in "{;" and round_depth == 0 and square_depth == 0:
                signatures.append(body[match.start() : index].strip())
                break
    return tuple(signatures)


def require_impl_method(
    source: str,
    type_name: str,
    function_name: str,
    pattern: str,
    label: str,
    *,
    visibility: str = "public",
) -> None:
    signatures = tuple(
        signature
        for body in rust_impl_bodies(source, type_name)
        for signature in rust_direct_function_signature(body, function_name, visibility)
    )
    matches = [
        signature
        for signature in signatures
        if re.fullmatch(pattern, signature, re.DOTALL) is not None
    ]
    if len(signatures) != 1 or len(matches) != 1:
        fail(
            f"production {type_name} lacks one exact direct {label}: "
            f"found {signatures!r}"
        )


def require_struct_field(source: str, struct_name: str, field_pattern: str) -> None:
    body = rust_item_body(source, "struct", struct_name)
    if re.search(field_pattern, body) is None:
        fail(f"production {struct_name} lacks the exact public ancestry-count field")


def rust_item_body(source: str, kind: str, name: str) -> str:
    mask = [True] * len(source)
    matches = direct_code_matches(source, rf"\bpub\s+{kind}\s+{re.escape(name)}\b")
    if len(matches) != 1:
        fail(f"production Rust source lacks public {kind} {name}")
    opening = next(
        (
            index
            for index in range(matches[0].end(), len(source))
            if mask[index] and source[index] == "{"
        ),
        None,
    )
    if opening is None:
        fail(f"public {kind} {name} has no opening brace")
    closing = matching_delimiter(source, mask, opening, "{", "}")
    if closing is None:
        fail(f"public {kind} {name} has no closing brace")
    return source[opening + 1 : closing]


def normalize_rust_body(body: str) -> str:
    body = re.sub(r"^\s*///[^\n]*$", "", body, flags=re.MULTILINE)
    body = re.sub(r"^\s*#\[[^\]]+\]\s*$", "", body, flags=re.MULTILINE)
    return re.sub(r"\s+", "", body)


def private_struct_fields(source: str, name: str) -> tuple[tuple[str, str], ...] | None:
    body = rust_item_body(source, "struct", name)
    if re.search(r"\bpub(?:\([^)]*\))?\s+", body):
        return None
    found = tuple(
        (field, re.sub(r"\s+", "", field_type))
        for field, field_type in re.findall(
            r"^\s*(\w+)\s*:\s*([^,\n]+)\s*,\s*$",
            body,
            flags=re.MULTILINE,
        )
    )
    residue = re.sub(
        r"^\s*(?:///[^\n]*|#\[[^\]]+\]|\w+\s*:\s*[^,\n]+,)\s*$",
        "",
        body,
        flags=re.MULTILINE,
    )
    return None if residue.strip() else found


def require_exact_private_struct_fields(
    source: str,
    name: str,
    expected: tuple[tuple[str, str], ...],
) -> None:
    found = private_struct_fields(source, name)
    normalized_expected = tuple(
        (field, re.sub(r"\s+", "", field_type)) for field, field_type in expected
    )
    if found != normalized_expected:
        fail(f"public {name} private fields/order differ: {found!r}")


def require_exact_public_struct_fields(
    source: str,
    name: str,
    expected: tuple[tuple[str, str], ...],
) -> None:
    body = rust_item_body(source, "struct", name)
    found = tuple(
        (field, re.sub(r"\s+", "", field_type))
        for field, field_type in re.findall(
            r"^\s*pub\s+(\w+)\s*:\s*([^,\n]+)\s*,\s*$",
            body,
            flags=re.MULTILINE,
        )
    )
    normalized_expected = tuple(
        (field, re.sub(r"\s+", "", field_type)) for field, field_type in expected
    )
    if found != normalized_expected:
        fail(f"public {name} fields/order differ: {found!r}")
    residue = re.sub(
        r"^\s*(?:///[^\n]*|#\[[^\]]+\]|pub\s+\w+\s*:\s*[^,\n]+,)\s*$",
        "",
        body,
        flags=re.MULTILINE,
    )
    if residue.strip():
        fail(f"public {name} contains an extra field or token")


def require_exact_enum_body(source: str, name: str, expected: str) -> None:
    found = normalize_rust_body(rust_item_body(source, "enum", name))
    if found != expected:
        fail(f"public enum {name} variants/order differ: {found!r}")


def public_recovery_surface(source: str) -> tuple[tuple[str, str], ...]:
    projected = rust_code_projection(source)
    surface: set[tuple[str, str]] = set()
    for match in re.finditer(
        r"\bpub(?:\([^)]*\))?\s+"
        r"(?:(?:unsafe\s+)?trait|struct|enum|union|type)\s+"
        rf"(?P<name>{RUST_IDENTIFIER})",
        projected,
    ):
        name = semantic_rust_identifier(match["name"])
        lowered = name.lower()
        if (
            "recovery" in lowered
            or "maintenance" in lowered
            or "gcwitness" in lowered
            or lowered.endswith(("fault", "faults", "limit", "limits"))
        ):
            surface.add(("type", name))
    for match in re.finditer(
        r"\bpub(?:\([^)]*\))?\s+"
        r"(?:(?:const|async|safe|unsafe)\s+)*(?:extern(?:\s+\"[^\"]+\")?\s+)?"
        rf"fn\s+(?P<name>{RUST_IDENTIFIER})",
        projected,
    ):
        name = semantic_rust_identifier(match["name"])
        lowered = name.lower()
        if any(
            marker in lowered
            for marker in ("recover", "maintenance", "ancestry", "bounded_object_len")
        ):
            surface.add(("function", name))
    return tuple(sorted(surface))


def semantic_rust_identifier(value: str) -> str:
    return value[2:] if value.startswith("r#") else value


def normalize_rust_tokens(value: str) -> str:
    mask = rust_code_mask(value)
    normalized: list[str] = []
    cursor = 0
    while cursor < len(value):
        code = mask[cursor]
        end = cursor + 1
        while end < len(value) and mask[end] == code:
            end += 1
        segment = value[cursor:end]
        if code:
            segment = re.sub(
                r"(?<![A-Za-z0-9_])r#(?=[A-Za-z_])",
                "",
                segment,
            )
            normalized.append(re.sub(r"\s+", "", segment))
        else:
            encoded = segment.encode("utf-8").hex()
            normalized.append(f"\x00{len(encoded)}:{encoded}\x00")
        cursor = end
    return "".join(normalized)


def public_function_signature_end(source: str, start: int) -> int | None:
    round_depth = 0
    square_depth = 0
    angle_depth = 0
    nested_brace_end = -1
    for index in range(start, len(source)):
        if index <= nested_brace_end:
            continue
        character = source[index]
        if character == "(":
            round_depth += 1
        elif character == ")":
            round_depth -= 1
        elif character == "[":
            square_depth += 1
        elif character == "]":
            square_depth -= 1
        elif character == "<":
            angle_depth += 1
        elif (
            character == ">"
            and angle_depth
            and (index == 0 or source[index - 1] not in "-=")
        ):
            angle_depth -= 1
        elif character == "{" and (round_depth or square_depth or angle_depth):
            closing = matching_delimiter(source, [True] * len(source), index, "{", "}")
            if closing is None:
                return None
            nested_brace_end = closing
        elif character in "{;" and not (round_depth or square_depth or angle_depth):
            return index
        if round_depth < 0 or square_depth < 0:
            return None
    return None


def rust_item_matches(projected: str, pattern: str) -> tuple[re.Match[str], ...]:
    matches: list[re.Match[str]] = []
    for match in re.finditer(pattern, projected):
        cursor = match.start() - 1
        while cursor >= 0 and projected[cursor].isspace():
            cursor -= 1
        if cursor >= 0 and projected[cursor] not in "{;}]":
            continue
        matches.append(match)
    return tuple(matches)


def rust_function_body_ranges(projected: str) -> tuple[tuple[int, int], ...]:
    ranges: list[tuple[int, int]] = []
    for match in re.finditer(rf"\bfn\s+{RUST_IDENTIFIER}\b", projected):
        end = public_function_signature_end(projected, match.start())
        if end is None or projected[end] != "{":
            continue
        closing = matching_delimiter(projected, [True] * len(projected), end, "{", "}")
        if closing is not None:
            ranges.append((end, closing + 1))
    return tuple(ranges)


def rust_owner_ranges(source: str, projected: str) -> tuple[tuple[int, int, str], ...]:
    ranges: list[tuple[int, int, str]] = []
    for match in rust_item_matches(
        projected,
        rf"(?:pub(?:\([^)]*\))?\s+)?mod\s+"
        rf"(?P<name>{RUST_IDENTIFIER})\s*\{{",
    ):
        opening = projected.find("{", match.start(), match.end())
        closing = matching_delimiter(
            projected, [True] * len(projected), opening, "{", "}"
        )
        if closing is not None:
            ranges.append(
                (
                    opening,
                    closing,
                    f"mod:{semantic_rust_identifier(match['name'])}",
                )
            )
    for match in rust_item_matches(
        projected,
        rf"(?:pub(?:\([^)]*\))?\s+)?(?:unsafe\s+)?(?:auto\s+)?trait\s+"
        rf"(?P<name>{RUST_IDENTIFIER})\b",
    ):
        opening = public_function_signature_end(projected, match.start())
        if opening is None or projected[opening] != "{":
            fail("cannot isolate a Rust trait owner")
        closing = matching_delimiter(
            projected, [True] * len(projected), opening, "{", "}"
        )
        if closing is None:
            fail("Rust trait owner has no closing brace")
        ranges.append(
            (
                opening,
                closing,
                f"trait:{semantic_rust_identifier(match['name'])}",
            )
        )
    for match in rust_item_matches(projected, r"(?:(?:unsafe|default)\s+)?impl\b"):
        extent = rust_impl_item_end(projected, match.start())
        if extent is None:
            fail("cannot isolate a Rust impl owner")
        opening = projected.find("{", match.start(), extent)
        if opening < 0:
            fail("Rust impl owner has no body")
        closing = matching_delimiter(
            projected, [True] * len(projected), opening, "{", "}"
        )
        if closing is None:
            fail("Rust impl owner has no closing brace")
        ranges.append(
            (
                opening,
                closing,
                normalize_rust_tokens(source[match.start() : opening]),
            )
        )
    return tuple(ranges)


def rust_owner_chain(
    owner_ranges: tuple[tuple[int, int, str], ...], position: int
) -> str:
    owners = sorted(
        (
            (closing - opening, opening, owner)
            for opening, closing, owner in owner_ranges
            if opening < position < closing
        ),
        reverse=True,
    )
    return "/".join(owner for _span, _opening, owner in owners) or "<crate>"


def rust_named_function_body(source: str, name: str, owner: str) -> str | None:
    projected = rust_code_projection(source)
    owner_ranges = rust_owner_ranges(source, projected)
    bodies: list[str] = []
    for match in re.finditer(rf"\bfn\s+(?:r#)?{re.escape(name)}\b", projected):
        if (
            semantic_rust_identifier(
                re.search(rf"(?:r#)?{re.escape(name)}", match.group())[0]
            )
            != name
        ):
            continue
        end = public_function_signature_end(projected, match.start())
        if end is None or projected[end] != "{":
            continue
        if rust_owner_chain(owner_ranges, match.start()) != owner:
            continue
        closing = matching_delimiter(projected, [True] * len(projected), end, "{", "}")
        if closing is None:
            return None
        bodies.append(projected[end + 1 : closing])
    return bodies[0] if len(bodies) == 1 else None


def rust_named_function_raw_body(source: str, name: str, owner: str) -> str | None:
    projected = rust_code_projection(source)
    owner_ranges = rust_owner_ranges(source, projected)
    bodies: list[str] = []
    for match in re.finditer(rf"\bfn\s+(?:r#)?{re.escape(name)}\b", projected):
        if (
            semantic_rust_identifier(
                re.search(rf"(?:r#)?{re.escape(name)}", match.group())[0]
            )
            != name
        ):
            continue
        end = public_function_signature_end(projected, match.start())
        if end is None or projected[end] != "{":
            continue
        if rust_owner_chain(owner_ranges, match.start()) != owner:
            continue
        closing = matching_delimiter(projected, [True] * len(projected), end, "{", "}")
        if closing is None:
            return None
        bodies.append(source[end + 1 : closing])
    return bodies[0] if len(bodies) == 1 else None


