def trait_impl_surface(
    source: str,
    projected: str,
    owner_ranges: tuple[tuple[int, int, str], ...],
) -> tuple[str, ...]:
    tokens: list[str] = []
    for match in rust_item_matches(projected, r"(?:(?:unsafe|default)\s+)?impl\b"):
        impl_start = projected.find("impl", match.start(), match.end())
        if impl_start < 0:
            fail("cannot isolate a Rust trait impl")
        extent = rust_impl_item_end(projected, match.start())
        if extent is None:
            fail("cannot isolate a Rust trait impl")
        opening = projected.find("{", match.start(), extent)
        if opening < 0:
            fail("Rust trait impl has no body")
        closing = matching_delimiter(
            projected, [True] * len(projected), opening, "{", "}"
        )
        if closing is None:
            fail("Rust trait impl has no closing brace")
        header_projection = projected[match.start() : opening]
        if re.search(r"\bfor\b", header_projection) is None:
            continue
        header = normalize_rust_tokens(source[match.start() : opening])
        owner = rust_owner_chain(owner_ranges, match.start())
        tokens.append(f"trait-impl:{owner}:{header}")
        body_source = source[opening + 1 : closing]
        body_projection = projected[opening + 1 : closing]
        member_tokens: list[str] = []
        for function in rust_item_matches(
            body_projection,
            rf"(?:(?:default|const|async|unsafe)\s+)*"
            rf"(?:extern(?:\s+\"[^\"]+\")?\s+)?fn\s+{RUST_IDENTIFIER}\b",
        ):
            if (
                brace_depth_at(
                    body_projection, [True] * len(body_projection), function.start()
                )
                != 0
            ):
                continue
            end = public_function_signature_end(body_projection, function.start())
            if end is None:
                fail("cannot isolate a trait-impl member signature")
            member_tokens.append(
                "fn:" + normalize_rust_tokens(body_source[function.start() : end])
            )
        for associated in rust_item_matches(
            body_projection,
            rf"(?:default\s+)?(?P<kind>type|const)\s+"
            rf"(?P<name>{RUST_IDENTIFIER})\b",
        ):
            if (
                brace_depth_at(
                    body_projection, [True] * len(body_projection), associated.start()
                )
                != 0
            ):
                continue
            end = rust_attributed_item_end(body_projection, associated.start())
            if end is None:
                fail("cannot isolate a trait-impl associated item")
            member_tokens.append(
                f"{associated['kind']}:"
                + normalize_rust_tokens(body_source[associated.start() : end])
            )
        tokens.extend(
            f"trait-impl-member:{owner}:{header}:{member}"
            for member in sorted(member_tokens)
        )
    return tuple(tokens)


def rust_attribute_chain_target(projected: str, end: int) -> int:
    cursor = end
    while True:
        while cursor < len(projected) and projected[cursor].isspace():
            cursor += 1
        if cursor >= len(projected) or projected[cursor] != "#":
            return cursor
        following = rust_attribute_end(projected, cursor)
        if following is None:
            return cursor
        cursor = following[0]


def rust_enclosing_brace_openings(
    projected: str, position: int
) -> tuple[int, ...] | None:
    stack: list[int] = []
    for index, character in enumerate(projected[:position]):
        if character == "{":
            stack.append(index)
        elif character == "}":
            if not stack:
                return None
            stack.pop()
    return tuple(stack)


def rust_valid_authority_owner_openings(projected: str) -> dict[int, str]:
    candidates: dict[int, str] = {}
    for match in rust_item_matches(
        projected,
        rf"(?:pub(?:\([^)]*\))?\s+)?mod\s+{RUST_IDENTIFIER}\s*\{{",
    ):
        opening = projected.find("{", match.start(), match.end())
        if opening >= 0:
            candidates[opening] = "module"
    for match in rust_item_matches(projected, r"(?:(?:unsafe|default)\s+)?impl\b"):
        extent = rust_impl_item_end(projected, match.start())
        if extent is None:
            continue
        opening = projected.find("{", match.start(), extent)
        if opening >= 0:
            candidates[opening] = "impl"
    for match in rust_item_matches(
        projected,
        r"(?:unsafe\s+)?extern(?:\s+\"[^\"]+\")?\s*\{",
    ):
        opening = projected.find("{", match.start(), match.end())
        if opening >= 0:
            candidates[opening] = "foreign"

    valid: dict[int, str] = {}
    for opening in sorted(candidates):
        parents = rust_enclosing_brace_openings(projected, opening)
        if parents is not None and all(
            valid.get(parent) == "module" for parent in parents
        ):
            valid[opening] = candidates[opening]
    return valid


def nested_public_declaration_problem(projected: str) -> str | None:
    valid_owners = rust_valid_authority_owner_openings(projected)
    declaration = re.compile(
        r"\bpub(?:\([^)]*\))?\s+"
        r"(?:"
        r"(?:(?:const|async|safe|unsafe)\s+)*"
        r"(?:extern(?:\s+\"[^\"]+\")?\s+)?fn\s+"
        rf"{RUST_IDENTIFIER}\b"
        r"|(?:(?:safe|unsafe)\s+)?static\s+(?:mut\s+)?"
        rf"{RUST_IDENTIFIER}\b"
        r"|(?:unsafe\s+)?(?:struct|enum|trait|union|type|const|mod)\s+"
        rf"{RUST_IDENTIFIER}\b"
        r"|use\b"
        r"|extern\s+crate\b"
        r")"
    )
    for match in declaration.finditer(projected):
        parents = rust_enclosing_brace_openings(projected, match.start())
        if parents is None:
            return "unbalanced Rust authority nesting"
        if all(valid_owners.get(parent) == "module" for parent in parents):
            continue
        if (
            parents
            and all(valid_owners.get(parent) == "module" for parent in parents[:-1])
            and valid_owners.get(parents[-1]) in {"impl", "foreign"}
        ):
            continue
        return "nested public declaration authority"
    return None


def generated_api_authority_problem(source: str) -> str | None:
    projected = rust_code_projection(source)
    if any(ord(character) > 127 for character in projected):
        return "non-ASCII Rust code authority is forbidden"
    if problem := nested_public_declaration_problem(projected):
        return problem
    attribute_ranges: list[tuple[int, int]] = []
    allowed_attributes = {
        "cold",
        "inline",
        "inline(always)",
        "inline(never)",
        "must_use",
        "track_caller",
    }
    for match in re.finditer(r"#\s*!?\s*\[", projected):
        attribute = rust_attribute_end(projected, match.start())
        if attribute is None:
            return "unterminated Rust attribute"
        end, normalized = attribute
        attribute_ranges.append((match.start(), end))
        target = rust_attribute_chain_target(projected, end)
        if re.match(r"(?:(?:unsafe|default)\s+)?impl\b", projected[target:]):
            return "attribute-controlled Rust impl authority"
        if normalized.startswith("derive(") and normalized.endswith(")"):
            derives = tuple(
                item for item in normalized[len("derive(") : -1].split(",") if item
            )
            if not derives or any(item not in BUILTIN_DERIVES for item in derives):
                return f"non-builtin derive authority: {normalized}"
            continue
        if normalized in allowed_attributes:
            continue
        if re.fullmatch(r"(?:allow|deny|forbid|warn)\([A-Za-z0-9_:,]+\)", normalized):
            continue
        if re.fullmatch(r"repr\([A-Za-z0-9_,()]+\)", normalized):
            continue
        if normalized.startswith("doc="):
            continue
        return f"procedural or unbound Rust attribute authority: {normalized}"

    function_ranges = rust_function_body_ranges(projected)
    for implementation in rust_item_matches(
        projected, r"(?:(?:unsafe|default)\s+)?impl\b"
    ):
        if any(start <= implementation.start() < end for start, end in function_ranges):
            return "nested trait or inherent impl authority"
    for trait in re.finditer(r"\btrait\s+", projected):
        if any(start <= trait.start() < end for start, end in function_ranges):
            return "nested trait-definition authority"
    allowed_expression_macros = {
        "assert",
        "assert_eq",
        "assert_ne",
        "debug_assert",
        "debug_assert_eq",
        "debug_assert_ne",
        "format",
        "matches",
        "println",
        "unreachable",
        "vec",
        "write",
        "writeln",
    }
    for use in re.finditer(r"\buse\s+(?P<body>.*?);", projected, re.DOTALL):
        imported = set(re.findall(RUST_IDENTIFIER, use["body"]))
        if imported.intersection(allowed_expression_macros):
            return "expression-macro name is imported or shadowable"
    if re.search(r"\bmacro_rules\s*!", projected):
        return "macro_rules! authority is forbidden at every depth"
    for match in re.finditer(
        rf"(?P<path>(?:::)?{RUST_IDENTIFIER}(?:::{RUST_IDENTIFIER})*)"
        r"\s*!\s*(?=[({\[])",
        projected,
    ):
        path = match["path"]
        if any(start <= match.start() < end for start, end in function_ranges):
            if path not in allowed_expression_macros:
                return f"unbound expression-macro authority: {path}!"
            continue
        if any(start <= match.start() < end for start, end in attribute_ranges):
            continue
        return f"item-position macro authority: {match['path']}!"
    return None


def exact_module_declarations(source: str) -> tuple[str, ...] | None:
    projected = rust_code_projection(source)
    found: list[str] = []
    for match in rust_item_matches(
        projected,
        rf"(?P<visibility>pub(?:\([^)]*\))?\s+)?"
        rf"mod\s+(?P<name>{RUST_IDENTIFIER})\s*(?P<tail>;|\{{)",
    ):
        mod_start = projected.find("mod", match.start(), match.end())
        if (
            mod_start < 0
            or brace_depth_at(projected, [True] * len(projected), mod_start) != 0
        ):
            continue
        if match["visibility"] is not None or match["tail"] != ";":
            return None
        if has_preceding_code_attribute(
            projected, [True] * len(projected), match.start()
        ):
            return None
        found.append(semantic_rust_identifier(match["name"]))
    return tuple(found)


def public_semantic_attribute_surface(
    source: str,
    projected: str,
    owner_ranges: tuple[tuple[int, int, str], ...],
) -> tuple[str, ...]:
    tokens: list[str] = []
    for match in re.finditer(r"#\s*\[", projected):
        attribute = rust_attribute_end(projected, match.start())
        if attribute is None:
            fail("cannot isolate a public semantic Rust attribute")
        end, _normalized_projection = attribute
        cursor = rust_attribute_chain_target(projected, end)
        tail = projected[cursor:]
        label: str | None = None
        owner = rust_owner_chain(owner_ranges, cursor)
        function = re.match(
            r"pub(?:\([^)]*\))?\s+"
            r"(?:(?:const|async|safe|unsafe)\s+)*(?:extern(?:\s+\"[^\"]+\")?\s+)?"
            rf"fn\s+(?P<name>{RUST_IDENTIFIER})",
            tail,
        )
        item = re.match(
            r"pub(?:\([^)]*\))?\s+"
            r"(?:(?P<safety>safe|unsafe)\s+)?"
            rf"(?P<kind>struct|enum|trait|union|type|const|static|mod)\s+"
            r"(?:mut\s+)?"
            rf"(?P<name>{RUST_IDENTIFIER})",
            tail,
        )
        extern_crate = re.match(
            r"pub(?:\([^)]*\))?\s+extern\s+crate\s+"
            rf"(?P<name>{RUST_IDENTIFIER})",
            tail,
        )
        if function is not None:
            label = f"function:{owner}:{semantic_rust_identifier(function['name'])}"
        elif item is not None:
            label = (
                f"item:{owner}:{item['kind']}:{semantic_rust_identifier(item['name'])}"
            )
        elif extern_crate is not None:
            label = (
                f"extern-crate:{owner}:{semantic_rust_identifier(extern_crate['name'])}"
            )
        elif re.match(r"(?:(?:unsafe|default)\s+)?impl\b", tail):
            opening = projected.find("{", cursor)
            if opening >= 0:
                label = f"impl:{owner}:" + normalize_rust_tokens(source[cursor:opening])
        if label is None:
            continue
        normalized = normalize_rust_tokens(source[match.start() : end])
        digest = hashlib.sha256(normalized.encode("utf-8")).hexdigest()
        tokens.append(f"attribute:{label}:{digest}")
    return tuple(tokens)


def complete_public_surface(
    source: str, *, body_exclusions: frozenset[str] = frozenset()
) -> tuple[str, ...]:
    projected = rust_code_projection(source)
    owner_ranges = rust_owner_ranges(source, projected)
    tokens: list[str] = []
    for match in re.finditer(
        r"\bpub(?:\([^)]*\))?\s+"
        r"(?:(?:const|async|safe|unsafe)\s+)*(?:extern(?:\s+\"[^\"]+\")?\s+)?"
        rf"fn\s+{RUST_IDENTIFIER}\b",
        projected,
    ):
        end = public_function_signature_end(projected, match.start())
        if end is None:
            fail("cannot isolate a public Rust function signature")
        signature = normalize_rust_tokens(source[match.start() : end])
        owner = rust_owner_chain(owner_ranges, match.start())
        tokens.append(f"function:{owner}:{signature}")
    item_ranges: list[tuple[int, int, str]] = []
    for match in re.finditer(
        r"\bpub(?:\([^)]*\))?\s+"
        rf"(?:(?:unsafe\s+)?(?P<kind>struct|enum|trait|union|type|mod)\s+|"
        rf"(?P<const>const)\s+(?!fn\b)|"
        rf"(?:(?:safe|unsafe)\s+)?(?P<static>static)\s+(?:mut\s+)?)"
        rf"(?P<name>{RUST_IDENTIFIER})",
        projected,
    ):
        kind = match["kind"] or match["const"] or match["static"]
        name = semantic_rust_identifier(match["name"])
        owner = rust_owner_chain(owner_ranges, match.start())
        tokens.append(f"item:{owner}:{kind}:{name}")
        extent = rust_attributed_item_end(projected, match.start())
        if extent is None:
            fail(f"cannot isolate public {kind} {name}")
        opening = projected.find("{", match.end(), extent)
        if opening >= 0:
            closing = matching_delimiter(
                projected, [True] * len(projected), opening, "{", "}"
            )
            if closing is None or closing >= extent:
                fail(f"cannot close public {kind} {name}")
            if kind in {"struct", "enum", "trait", "union"}:
                item_ranges.append((opening, closing, name))
        if name not in body_exclusions:
            declaration = normalize_rust_tokens(source[match.start() : extent])
            declaration_digest = hashlib.sha256(declaration.encode("utf-8")).hexdigest()
            tokens.append(
                f"item-declaration:{owner}:{kind}:{name}:{declaration_digest}"
            )
        if (
            opening >= 0
            and kind in {"struct", "enum", "trait", "union"}
            and name not in body_exclusions
        ):
            header = normalize_rust_tokens(source[match.start() : opening])
            body = normalize_rust_tokens(source[opening + 1 : closing])
            tokens.append(f"item-header:{owner}:{kind}:{name}:{header}")
            tokens.append(
                f"item-body:{owner}:{kind}:{name}:"
                f"{hashlib.sha256(body.encode('utf-8')).hexdigest()}"
            )
    for match in re.finditer(
        r"(?m)^[ \t]*pub(?:\([^)]*\))?\s+"
        rf"(?P<name>{RUST_IDENTIFIER})\s*:\s*(?P<type>[^,\n]+),",
        projected,
    ):
        parents = [
            (closing - opening, parent)
            for opening, closing, parent in item_ranges
            if opening < match.start() < closing
        ]
        parent = min(parents)[1] if parents else "<unowned>"
        owner = rust_owner_chain(owner_ranges, match.start())
        field_type = normalize_rust_tokens(match["type"])
        tokens.append(
            f"field:{owner}:{parent}:"
            f"{semantic_rust_identifier(match['name'])}:{field_type}"
        )
    for match in re.finditer(
        r"\bpub(?:\([^)]*\))?\s+use\s+(?P<body>.*?);",
        projected,
        re.DOTALL,
    ):
        normalized = normalize_rust_tokens(match["body"])
        owner = rust_owner_chain(owner_ranges, match.start())
        if normalized.startswith("repository::{"):
            tokens.append(f"use:{owner}:<txn-repository-reexports-checked-separately>")
        else:
            tokens.append(f"use:{owner}:{normalized}")
    for match in re.finditer(
        r"\bpub(?:\([^)]*\))?\s+extern\s+crate\s+"
        rf"(?P<name>{RUST_IDENTIFIER})"
        rf"(?:\s+as\s+(?P<alias>{RUST_IDENTIFIER}))?\s*;",
        projected,
    ):
        owner = rust_owner_chain(owner_ranges, match.start())
        declaration = normalize_rust_tokens(source[match.start() : match.end()])
        tokens.append(f"extern-crate:{owner}:{declaration}")
    for match in rust_item_matches(
        projected,
        r"(?:(?:unsafe)\s+)?extern(?:\s+\"[^\"]+\")?\s*\{",
    ):
        opening = projected.find("{", match.start(), match.end())
        closing = matching_delimiter(
            projected, [True] * len(projected), opening, "{", "}"
        )
        if opening < 0 or closing is None:
            fail("cannot isolate a Rust foreign block")
        owner = rust_owner_chain(owner_ranges, match.start())
        declaration = normalize_rust_tokens(source[match.start() : closing + 1])
        digest = hashlib.sha256(declaration.encode("utf-8")).hexdigest()
        tokens.append(f"foreign-block:{owner}:{digest}")
    tokens.extend(trait_impl_surface(source, projected, owner_ranges))
    tokens.extend(public_semantic_attribute_surface(source, projected, owner_ranges))
    return tuple(sorted(tokens))


def public_api_source_paths() -> tuple[str, ...]:
    roots = (
        ROOT / "crates/sley-store/src",
        ROOT / "crates/sley-txn/src",
        ROOT / "crates/sley-repo/src",
    )
    return tuple(
        sorted(
            str(path.relative_to(ROOT))
            for root in roots
            for path in sorted(root.rglob("*.rs"))
            if path.is_file()
        )
    )


def frozen_test_authority_record_problem(record: object) -> str | None:
    if not isinstance(record, dict):
        return "frozen test-authority record is not an object"
    if len(record) != FROZEN_TEST_AUTHORITY_FILE_COUNT:
        return "frozen test-authority file count differs"
    for relative, digest in record.items():
        if (
            not isinstance(relative, str)
            or not isinstance(digest, str)
            or re.fullmatch(r"[0-9a-f]{64}", digest) is None
        ):
            return "frozen test-authority path or digest is malformed"
    if canonical_json_sha256(record) != FROZEN_TEST_AUTHORITY_SET_SHA256:
        return "frozen test-authority path/byte set differs"
    return None


def owner_package_non_source_record_problem(record: object) -> str | None:
    if not isinstance(record, dict):
        return "owner package non-source record is not an object"
    if tuple(record) != OWNER_PACKAGE_NON_SOURCE_PATHS:
        return "owner package non-source path inventory differs"
    for relative, digest in record.items():
        if (
            not isinstance(relative, str)
            or not isinstance(digest, str)
            or re.fullmatch(r"[0-9a-f]{64}", digest) is None
        ):
            return "owner package non-source path or digest is malformed"
    return None


def owner_package_non_source_record() -> dict[str, str]:
    paths: set[Path] = set()
    for relative_root in OWNER_PACKAGE_ROOTS:
        root = ROOT / relative_root
        try:
            root_metadata = root.lstat()
        except OSError as error:
            fail(f"cannot inspect owner package root {relative_root}: {error}")
        if not stat.S_ISDIR(root_metadata.st_mode):
            fail(f"owner package root is not a real directory: {relative_root}")
        for path in root.rglob("*"):
            local = path.relative_to(root)
            if local.parts and local.parts[0] == "src" and path.suffix == ".rs":
                continue
            try:
                metadata = path.lstat()
            except OSError as error:
                fail(
                    f"cannot inspect owner package input {relative_root}/{local}: {error}"
                )
            if stat.S_ISDIR(metadata.st_mode):
                continue
            if not stat.S_ISREG(metadata.st_mode):
                fail(
                    "owner package non-source input is not a regular file: "
                    f"{relative_root}/{local}"
                )
            paths.add(path)
    record: dict[str, str] = {}
    for path in sorted(paths, key=lambda candidate: str(candidate.relative_to(ROOT))):
        relative = str(path.relative_to(ROOT))
        try:
            payload = path.read_bytes()
        except OSError as error:
            fail(f"cannot read owner package non-source input {relative}: {error}")
        record[relative] = hashlib.sha256(payload).hexdigest()
    return record


def frozen_test_authority_record() -> dict[str, str]:
    paths = {ROOT / relative for relative in FROZEN_TEST_AUTHORITY_FIXED_PATHS}
    for relative in FROZEN_TEST_AUTHORITY_ROOTS:
        root = ROOT / relative
        try:
            root_metadata = root.lstat()
        except OSError as error:
            fail(f"cannot inspect frozen test-authority root {relative}: {error}")
        if not stat.S_ISDIR(root_metadata.st_mode):
            fail(f"frozen test-authority root is not a real directory: {relative}")
        paths.update(root.rglob("*"))
    record: dict[str, str] = {}
    for path in sorted(paths, key=lambda candidate: str(candidate.relative_to(ROOT))):
        relative = str(path.relative_to(ROOT))
        try:
            metadata = path.lstat()
        except OSError as error:
            fail(f"cannot inspect frozen test-authority input {relative}: {error}")
        if stat.S_ISDIR(metadata.st_mode):
            continue
        if not stat.S_ISREG(metadata.st_mode):
            fail(f"frozen test-authority input is not a regular file: {relative}")
        try:
            payload = path.read_bytes()
        except OSError as error:
            fail(f"cannot read frozen test-authority input {relative}: {error}")
        record[relative] = hashlib.sha256(payload).hexdigest()
    return record


def require_frozen_test_authority() -> None:
    if problem := owner_package_non_source_record_problem(
        owner_package_non_source_record()
    ):
        fail(problem)
    if problem := frozen_test_authority_record_problem(frozen_test_authority_record()):
        fail(problem)


def public_api_surface_baseline_sha256(
    complete_source: str,
    relative: str,
    *,
    require_allowed_additions: bool,
) -> tuple[str | None, str | None]:
    source = normal_build_source(complete_source)
    if problem := generated_api_authority_problem(source):
        return None, problem
    surface = list(
        complete_public_surface(
            source,
            body_exclusions=PUBLIC_API_BODY_EXCLUSIONS.get(relative, frozenset()),
        )
    )
    for allowed in PUBLIC_API_ALLOWED_ADDITIONS.get(relative, ()):
        try:
            surface.remove(allowed)
        except ValueError:
            if require_allowed_additions:
                return None, f"required public API delta is absent: {allowed}"
    return canonical_json_sha256(surface), None


def public_api_baseline_anchor_problem() -> str | None:
    for relative, expected in PUBLIC_API_BASELINE_SHA256.items():
        try:
            source = git_bytes(
                "show",
                f"{PUBLIC_API_BASELINE_ANCHOR}:{relative}",
            ).decode("utf-8", errors="strict")
        except UnicodeDecodeError:
            return f"public API anchor source is not UTF-8: {relative}"
        digest, problem = public_api_surface_baseline_sha256(
            source,
            relative,
            require_allowed_additions=False,
        )
        if problem is not None:
            return f"public API anchor source differs in {relative}: {problem}"
        if digest != expected:
            return f"public API baseline is not derived from its Git anchor: {relative}"
    return None


def public_api_baseline_problem() -> str | None:
    expected_sources = tuple(
        sorted((*PUBLIC_API_SOURCE_PATHS, *PUBLIC_API_TEST_ONLY_SOURCE_PATHS))
    )
    if public_api_source_paths() != expected_sources:
        return "production Rust source-path inventory differs"
    for relative, expected in PUBLIC_API_MODULE_GRAPH.items():
        source = normal_build_source((ROOT / relative).read_text(encoding="utf-8"))
        if exact_module_declarations(source) != expected:
            return f"exact unconditional module graph differs in {relative}"
    for relative in PUBLIC_API_CRATE_MANIFESTS:
        manifest = (ROOT / relative).read_bytes()
        if problem := native_lib_harness_problem(manifest):
            return f"native library root differs in {relative}: {problem}"
        if problem := owner_manifest_build_authority_problem(manifest):
            return f"owner build authority differs in {relative}: {problem}"
    if problem := public_api_baseline_anchor_problem():
        return problem
    for relative in PUBLIC_API_SOURCE_PATHS:
        complete_source = (ROOT / relative).read_text(encoding="utf-8")
        if problem := owner_source_external_authority_problem(
            complete_source, relative
        ):
            return (
                f"production API source has external authority in {relative}: {problem}"
            )
        digest, problem = public_api_surface_baseline_sha256(
            complete_source,
            relative,
            require_allowed_additions=True,
        )
        if problem is not None:
            return f"production API source differs in {relative}: {problem}"
        if digest != PUBLIC_API_BASELINE_SHA256[relative]:
            return f"complete public API baseline differs in {relative}"
    return None


def limit_profile_problem(source: str, spec: dict[str, object]) -> str | None:
    production = normal_build_rust(source)
    constructor = spec["constructor"]
    profile_type = spec["profile_type"]
    constants = spec["constants"]
    if not isinstance(constructor, str) or not isinstance(profile_type, str):
        return "invalid checker limit-profile metadata"
    if not isinstance(constants, tuple):
        return "invalid checker limit-constant metadata"

    for field, constant, expected in constants:
        matches = direct_code_matches(
            production,
            rf"\bconst\s+{re.escape(constant)}\s*:\s*u64\s*=\s*"
            r"(?P<value>[0-9][0-9_]*)\s*;",
        )
        if len(matches) != 1:
            return f"lacks one private u64 default constant {constant}"
        if int(matches[0]["value"].replace("_", "")) != expected:
            return f"default value differs for {constant}"
        if len(re.findall(rf"\b{re.escape(constant)}\b", production)) != 2:
            return f"{constant} is not bound only to its frozen profile field"

    constructor_matches = direct_code_matches(
        production,
        rf"\bconst\s+fn\s+{re.escape(constructor)}\s*\(\s*\)\s*"
        rf"->\s*{re.escape(profile_type)}\s*\{{",
    )
    if len(constructor_matches) != 1:
        return f"lacks one exact private constructor {constructor}"
    constructor_body = rust_named_function_body(production, constructor, "<crate>")
    if constructor_body is None:
        return f"cannot isolate private constructor {constructor}"
    if normalize_rust_tokens(constructor_body) != spec["initializer"]:
        return f"frozen profile initializer differs for {constructor}"
    if len(re.findall(rf"\b{re.escape(constructor)}\b", production)) != 2:
        return f"{constructor} is not selected by exactly one production wrapper"

    wrapper = spec["wrapper"]
    wrapper_owner = spec["wrapper_owner"]
    wrapper_body_expected = spec["wrapper_body"]
    if not all(
        isinstance(value, str)
        for value in (wrapper, wrapper_owner, wrapper_body_expected)
    ):
        return "invalid checker wrapper metadata"
    wrapper_body = rust_named_function_body(production, wrapper, wrapper_owner)
    if wrapper_body is None:
        return f"cannot isolate limit-selecting wrapper {wrapper_owner}::{wrapper}"
    normalized_wrapper = normalize_rust_tokens(wrapper_body)
    if normalized_wrapper != wrapper_body_expected:
        return f"{wrapper_owner}::{wrapper} does not make its exact bound core call"

    helper = spec["helper"]
    helper_error = spec["helper_error"]
    overflow_error = spec["overflow_error"]
    helper_body_expected = spec["helper_body"]
    if not all(
        isinstance(value, str)
        for value in (
            helper,
            helper_error,
            overflow_error,
            helper_body_expected,
        )
    ):
        return "invalid checker enforcement metadata"
    if helper_error not in helper_body_expected:
        return "checker helper-error metadata is not bound to its exact body"
    if not overflow_error:
        return "checker overflow-error metadata is empty"

    helper_matches = direct_code_matches(
        production,
        rf"\bfn\s+{re.escape(helper)}\s*\(\s*value\s*:\s*u64\s*,\s*"
        r"limit\s*:\s*u64\s*,?\s*\)",
    )
    if len(helper_matches) != 1:
        return f"lacks one exact private comparison helper {helper}"
    helper_body = rust_named_function_body(production, helper, "<crate>")
    if helper_body is None:
        return f"cannot isolate private comparison helper {helper}"
    normalized_helper = normalize_rust_tokens(helper_body)
    if normalized_helper != helper_body_expected:
        return f"{helper} does not implement the exact closed comparison body"
    return None


def limit_profile_map() -> dict[str, dict[str, object]]:
    profiles: dict[str, dict[str, object]] = {}
    for spec in LIMIT_PROFILE_SPECS:
        constructor = spec.get("constructor")
        if not isinstance(constructor, str) or constructor in profiles:
            fail("checker limit-profile constructor authority differs")
        profiles[constructor] = spec
    return profiles


def limit_profile_metadata_problem(
    specs: object = LIMIT_PROFILE_SPECS,
) -> str | None:
    expected_keys = (
        "path",
        "constructor",
        "profile_type",
        "initializer",
        "constants",
        "wrapper_owner",
        "wrapper",
        "wrapper_body",
        "helper",
        "helper_error",
        "overflow_error",
        "helper_body",
    )
    expected_constructors = (
        "object_recovery_limits",
        "transaction_recovery_limits",
        "accepted_recovery_limits",
        "branch_recovery_limits",
        "ref_recovery_limits",
    )
    if not isinstance(specs, tuple) or len(specs) != 5:
        return "limit profile authority is not exactly five profiles"
    if any(not isinstance(spec, dict) for spec in specs):
        return "limit profile authority contains a non-object profile"
    if tuple(spec.get("constructor") for spec in specs) != expected_constructors:
        return "limit profile constructors/order differ"
    qualified_fields: list[str] = []
    constants: list[str] = []
    for spec in specs:
        if tuple(spec) != expected_keys:
            return f"{spec.get('constructor')} limit profile schema/order differs"
        if not all(
            isinstance(spec[key], str) and bool(spec[key])
            for key in expected_keys
            if key != "constants"
        ):
            return f"{spec['constructor']} limit profile string metadata differs"
        entries = spec["constants"]
        if not isinstance(entries, tuple) or not entries:
            return f"{spec['constructor']} limit constant inventory differs"
        for entry in entries:
            if (
                not isinstance(entry, tuple)
                or len(entry) != 3
                or not isinstance(entry[0], str)
                or not isinstance(entry[1], str)
                or not isinstance(entry[2], int)
                or isinstance(entry[2], bool)
                or entry[2] <= 0
            ):
                return f"{spec['constructor']} limit constant entry differs"
            qualified_fields.append(f"{spec['constructor']}::{entry[0]}")
            constants.append(entry[1])
    if len(qualified_fields) != 37 or len(set(qualified_fields)) != 37:
        return "limit profile fields are not exactly 37 unique fields"
    if len(constants) != 37 or len(set(constants)) != 37:
        return "limit profile constants are not exactly 37 unique constants"
    return None


def limit_qualified_fields() -> tuple[str, ...]:
    return tuple(
        f"{spec['constructor']}::{field}"
        for spec in LIMIT_PROFILE_SPECS
        for field, _constant, _value in spec["constants"]
    )


def limit_runtime_case_metadata_problem(
    specs: object = LIMIT_RUNTIME_CASE_SPECS,
    expected_digest: object = LIMIT_RUNTIME_CASE_SPECS_SHA256,
) -> str | None:
    expected_keys = tuple(
        (row_id, subcase_id)
        for row_id, subcases in LIMIT_DEFAULTS.items()
        for subcase_id in subcases
    )
    if not isinstance(specs, dict) or tuple(specs) != expected_keys:
        return "limit runtime case keys/order differ"
    if len(specs) != 37 or any(
        not isinstance(spec, LimitRuntimeCaseSpec) for spec in specs.values()
    ):
        return "limit runtime authority is not exactly 37 typed cases"
    expected_specs = build_limit_runtime_case_specs()
    if specs != expected_specs:
        return "limit runtime cases differ from the closed field/event authority"
    event_memberships = tuple(
        event_id for spec in specs.values() for event_id in spec.event_ids
    )
    if len(event_memberships) != 42:
        return "limit runtime cases do not cover exactly 42 event memberships"
    repeated = {
        spec.qualified_field: spec.event_ids
        for spec in specs.values()
        if len(spec.event_ids) > 1
    }
    if set(repeated) != {
        "ref_recovery_limits::origin_record_bytes",
        "branch_recovery_limits::per_pointer.receipt_bytes",
        "branch_recovery_limits::per_pointer.binding_visits",
        "branch_recovery_limits::per_pointer.object_verifications",
        "branch_recovery_limits::per_pointer.object_bytes",
    } or any(len(event_ids) != 2 for event_ids in repeated.values()):
        return "limit runtime dual-site cases differ"
    if set(event_memberships) != set(LIMIT_EVENT_SPECS):
        return "limit runtime cases omit or invent an event site"
    for key, spec in specs.items():
        if (spec.row_id, spec.subcase_id) != key:
            return f"{key!r} limit runtime identity differs"
        if spec.exact_cardinality != 2 or spec.plus_one_cardinality != 3:
            return f"{key!r} limit runtime N/N+1 cardinality differs"
        profile = limit_profile_map().get(spec.profile_constructor)
        comparison_helper = None if profile is None else profile.get("helper")
        if spec.helper_functions != (
            spec.setup_helper,
            *LIMIT_RUNTIME_PROBE_HELPERS,
            comparison_helper,
        ):
            return f"{key!r} limit runtime helper inventory differs"
        if spec.setup_helper != limit_runtime_setup_helper(*key):
            return f"{key!r} limit runtime setup helper differs"
        if any(
            re.fullmatch(RUST_IDENTIFIER, helper) is None
            for helper in spec.helper_functions
        ):
            return f"{key!r} limit runtime helper identifier is malformed"
        if not spec.event_ids:
            return f"{key!r} limit runtime case lacks an event site"
    if (
        not isinstance(expected_digest, str)
        or limit_runtime_case_specs_sha256(specs) != expected_digest
    ):
        return "limit runtime case authority digest differs"
    return None


def limit_event_record(
    specs: dict[str, LimitEventSpec] = LIMIT_EVENT_SPECS,
) -> tuple[tuple[object, ...], ...]:
    return tuple((event_id, *spec) for event_id, spec in specs.items())


def limit_event_specs_sha256(
    specs: dict[str, LimitEventSpec] = LIMIT_EVENT_SPECS,
) -> str:
    return canonical_json_sha256(limit_event_record(specs))


LIMIT_EVENT_SPECS_SHA256 = (
    "d136d756ff34d0c4a351a2841ce336fbb6a4e4fdaad502da43bd3b03015c4b3d"
)


def limit_event_profile(
    qualified_field: str,
) -> tuple[dict[str, object], str] | None:
    try:
        constructor, field = qualified_field.split("::", 1)
    except ValueError:
        return None
    profile = limit_profile_map().get(constructor)
    if profile is None:
        return None
    constants = profile.get("constants")
    if not isinstance(constants, tuple) or field not in {item[0] for item in constants}:
        return None
    return profile, field


def limit_event_expected_statements(spec: LimitEventSpec) -> tuple[str, ...]:
    statements = list(spec.source)
    profile_by_charge: list[tuple[dict[str, object], str]] = []
    for qualified_field, counter, next_identifier, delta in spec.charges:
        resolved = limit_event_profile(qualified_field)
        if resolved is None:
            fail(f"limit event has an unknown profile field: {qualified_field}")
        profile, field = resolved
        overflow_error = profile.get("overflow_error")
        if not isinstance(overflow_error, str):
            fail("limit event profile lacks an overflow error")
        statements.append(
            f"let {next_identifier} = {counter}.checked_add({delta})"
            f".ok_or_else(|| {overflow_error})?;"
        )
        profile_by_charge.append((profile, field))
    if spec.charges:
        first_profile = profile_by_charge[0][0]
        overflow_error = first_profile.get("overflow_error")
        if not isinstance(overflow_error, str):
            fail("limit event retain profile lacks an overflow error")
    else:
        fail("limit event has no governed charge")
    for accumulator, next_identifier, delta in spec.retains:
        statements.append(
            f"let {next_identifier} = {accumulator}.checked_add({delta})"
            f".ok_or_else(|| {overflow_error})?;"
        )
    for (qualified_field, _counter, next_identifier, _delta), (
        profile,
        field,
    ) in zip(spec.charges, profile_by_charge):
        helper = profile.get("helper")
        if not isinstance(helper, str):
            fail(f"limit event helper differs for {qualified_field}")
        statements.append(f"{helper}({next_identifier}, limits.{field})?;")
    for _qualified_field, counter, next_identifier, _delta in spec.charges:
        statements.append(f"{counter} = {next_identifier};")
    for accumulator, next_identifier, _delta in spec.retains:
        statements.append(f"{accumulator} = {next_identifier};")
    statements.extend(spec.sink)
    return tuple(statements)


def limit_event_source_problem(spec: LimitEventSpec) -> str | None:
    normalized = tuple(normalize_rust_tokens(statement) for statement in spec.source)
    if spec.source_kind == "unit":
        deltas = {delta for _field, _counter, _next, delta in spec.charges} | {
            delta for _accumulator, _next, delta in spec.retains
        }
        if (
            len(deltas) != 1
            or re.fullmatch(RUST_IDENTIFIER, next(iter(deltas))) is None
        ):
            return "unit source does not have one exact governed delta binding"
        delta = next(iter(deltas))
        if len(normalized) != 2 or normalized[-1] != f"let{delta}=1_u64;":
            return "unit source is not one exact item plus one-unit delta"
        if spec.identity == ("binding",):
            wrap_verification = spec.site[2] == "verify_recovery_ancestries_with_limits"
            expected_sink = limit_recovery_binding_sink(
                wrap_verification=wrap_verification,
            )
            if tuple(
                normalize_rust_tokens(statement) for statement in spec.sink
            ) != tuple(normalize_rust_tokens(statement) for statement in expected_sink):
                return "binding sink does not use its exact site-specific bridge"
    elif spec.source_kind == "batch_len":
        if normalized != (
            "letmutrequest_usage=0_u64;",
            "letrequest_count=u64::try_from(requests.len()).map_err(|_|RecoveryAncestryError::LimitExceeded)?;",
        ):
            return "batch source is not the checked request-slice length"
        if any(
            delta != "request_count" for _field, _counter, _next, delta in spec.charges
        ):
            return "batch source has a non-length governed delta"
    elif spec.source_kind == "metadata_file":
        is_receipt_site = spec.site[0] == TXN_LIMIT_SOURCE and spec.site[2] in {
            "verify_accepted_recovery_ancestry_with_limits",
            "verify_recovery_ancestries_with_limits",
        }
        if is_receipt_site:
            wrap_verification = spec.site[2] == "verify_recovery_ancestries_with_limits"
            expected_source = limit_recovery_receipt_metadata_source(
                wrap_verification=wrap_verification,
            )
            if normalized != tuple(
                normalize_rust_tokens(statement) for statement in expected_source
            ):
                return "receipt metadata source does not use its exact read-only bridge"
            expected_sink = limit_recovery_receipt_sink(
                wrap_verification=wrap_verification,
            )
            if tuple(
                normalize_rust_tokens(statement) for statement in spec.sink
            ) != tuple(normalize_rust_tokens(statement) for statement in expected_sink):
                return "receipt sink does not use its exact site-specific bridge"
        else:
            if len(normalized) not in {4, 5}:
                return "metadata source statement count differs"
            if "symlink_metadata" not in normalized[1]:
                return "metadata source does not stat the exact path"
            if normalized[2] != "ensure_recovery_regular_file(&metadata)?;":
                return "metadata source does not reject symlink/non-regular entries"
            if normalized[3] != "letmetadata_bytes=metadata.len();":
                return "metadata source does not charge metadata length"
            if len(normalized) == 5 and normalized[4] != "letone=1_u64;":
                return "metadata count delta is not one"
        allowed_deltas = {"metadata_bytes"}
        if len(normalized) == 5:
            allowed_deltas.add("one")
        if any(
            delta not in allowed_deltas
            for _field, _counter, _next, delta in spec.charges
        ):
            return "metadata source has an untrusted governed delta"
    elif spec.source_kind == "bounded_object":
        expected_source = limit_bounded_object_source(
            "next_object_id",
            wrap_store_error=(spec.site[2] == "verify_recovery_ancestries_with_limits"),
        )
        if normalized != tuple(
            normalize_rust_tokens(statement) for statement in expected_source
        ):
            return "bounded-object source does not use its exact site-specific bridge"
        expected_sink = (
            (
                "let object = self.object_store.read(object_id, verifier)"
                ".map_err(CommitError::from)"
                ".map_err(RecoveryAncestryError::Verification)?;"
            )
            if spec.site[2] == "verify_recovery_ancestries_with_limits"
            else "let object = self.object_store.read(object_id, verifier)?;"
        )
        if tuple(normalize_rust_tokens(statement) for statement in spec.sink) != (
            normalize_rust_tokens(expected_sink),
        ):
            return "bounded-object sink does not use its exact site-specific bridge"
        if any(
            delta not in {"one", "object_bytes"}
            for _field, _counter, _next, delta in spec.charges
        ):
            return "bounded-object source has an untrusted governed delta"
    elif spec.source_kind == "branch_ancestry":
        if normalized != (
            "lettransaction_id=pending_transaction_id;",
            "letfirst_union=!union_seen.contains(&transaction_id);",
            "letone=1_u64;",
            "letunion_delta=u64::from(first_union);",
        ):
            return "branch-ancestry source is not exact head/union admission"
        if tuple(charge[3] for charge in spec.charges) != ("one", "union_delta"):
            return "branch-ancestry source has non-head/union deltas"
    elif spec.source_kind == "cached_work":
        if normalized != tuple(
            normalize_rust_tokens(statement) for statement in limit_cached_work_source()
        ):
            return "cached-work source is not the immutable retained cache entry"
        if tuple(charge[3] for charge in spec.charges) != (
            "cached_receipt_bytes",
            "cached_binding_visits",
            "cached_object_verifications",
            "cached_object_bytes",
        ):
            return "cached-work source has forged or reordered deltas"
    else:
        return f"unknown limit-event source kind {spec.source_kind!r}"
    joined_source = "\n".join(spec.source)
    joined_sink = "\n".join(spec.sink)
    for identity in spec.identity:
        if not code_contains_token(joined_source, identity) or not code_contains_token(
            joined_sink, identity
        ):
            return f"identity {identity!r} is not shared by source and sink"
    return None


def limit_event_metadata_problem(
    specs: object = LIMIT_EVENT_SPECS,
    expected_digest: object = LIMIT_EVENT_SPECS_SHA256,
) -> str | None:
    expected_ids = (
        "object.scan_fanout",
        "object.scan_leaf",
        "object.retain_final",
        "object.retain_stage",
        "txn.receipt_scan_fanout",
        "txn.receipt_scan_leaf",
        "txn.retain_receipt",
        "txn.retain_receipt_stage",
        "txn.head_scan_entry",
        "txn.retain_head_stage",
        "ref.origin_scan_fanout",
        "ref.origin_scan_leaf",
        "ref.retain_origin",
        "ref.retain_origin_stage",
        "ref.record_scan_fanout",
        "ref.record_scan_leaf",
        "ref.retain_record_stage",
        "ref.visible_record_read",
        "ref.visible_origin_read",
        "ref.orphan_origin_read",
        "branch.request_batch",
        "accepted.ancestry_node",
        "accepted.receipt_read",
        "accepted.binding_visit",
        "accepted.object_read",
        "branch.ancestry_node",
        "branch.actual_receipt_read",
        "branch.actual_binding_visit",
        "branch.actual_object_read",
        "branch.cached_fact_use",
    )
    if not isinstance(specs, dict) or tuple(specs) != expected_ids:
        return "limit event IDs/order differ"
    if len(specs) != 30 or any(
        not isinstance(spec, LimitEventSpec) for spec in specs.values()
    ):
        return "limit event authority is not exactly 30 typed events"
    allowed_sources = {
        "unit",
        "batch_len",
        "metadata_file",
        "bounded_object",
        "branch_ancestry",
        "cached_work",
    }
    field_memberships: list[str] = []
    next_identifiers: set[tuple[tuple[str, str, str], str]] = set()
    for event_id, spec in specs.items():
        if spec.source_kind not in allowed_sources:
            return f"{event_id} source kind differs"
        if (
            len(spec.site) != 3
            or spec.site[0]
            not in {STORE_LIMIT_SOURCE, TXN_LIMIT_SOURCE, REF_LIMIT_SOURCE}
            or not spec.source
            or not spec.identity
            or not spec.charges
            or not spec.sink
            or spec.bypass_tokens != LIMIT_EVENT_BYPASS_TOKENS
        ):
            return f"{event_id} event shape differs"
        if problem := limit_event_source_problem(spec):
            return f"{event_id} source differs: {problem}"
        for qualified_field, counter, next_identifier, delta in spec.charges:
            if limit_event_profile(qualified_field) is None:
                return f"{event_id} has unknown field {qualified_field}"
            if any(
                re.fullmatch(r"[A-Za-z_][A-Za-z0-9_.]*", value) is None
                for value in (counter, next_identifier, delta)
            ):
                return f"{event_id} charge identifiers differ"
            identity = (spec.site, next_identifier)
            if identity in next_identifiers:
                return f"{event_id} reuses a next-value identifier at one site"
            next_identifiers.add(identity)
            field_memberships.append(qualified_field)
        for accumulator, next_identifier, delta in spec.retains:
            if any(
                re.fullmatch(r"[A-Za-z_][A-Za-z0-9_.]*", value) is None
                for value in (accumulator, next_identifier, delta)
            ):
                return f"{event_id} retain identifiers differ"
            identity = (spec.site, next_identifier)
            if identity in next_identifiers:
                return f"{event_id} reuses a retain next-value identifier"
            next_identifiers.add(identity)
        if len(set(spec.charges)) != len(spec.charges) or len(set(spec.retains)) != len(
            spec.retains
        ):
            return f"{event_id} repeats a charge or retention"
        if any(
            token
            in code_only_normalized("\n".join(limit_event_expected_statements(spec)))
            for token in spec.bypass_tokens
        ):
            return f"{event_id} exact window contains a bypass token"

    qualified_fields = limit_qualified_fields()
    expected_memberships = {field: 1 for field in qualified_fields}
    for repeated in (
        "ref_recovery_limits::origin_record_bytes",
        "branch_recovery_limits::per_pointer.receipt_bytes",
        "branch_recovery_limits::per_pointer.binding_visits",
        "branch_recovery_limits::per_pointer.object_verifications",
        "branch_recovery_limits::per_pointer.object_bytes",
    ):
        expected_memberships[repeated] = 2
    found_memberships = {
        field: field_memberships.count(field) for field in set(field_memberships)
    }
    if len(qualified_fields) != 37 or len(field_memberships) != 42:
        return "limit field/event cardinalities are not exactly 37/42"
    if found_memberships != expected_memberships:
        return "limit field-event membership counter differs"
    if tuple(LIMIT_FIELD_RUNTIME_OBSERVATIONS) != tuple(
        dict.fromkeys(field_memberships)
    ):
        return "limit field runtime-observation order or coverage differs"
    for qualified_field, observation in LIMIT_FIELD_RUNTIME_OBSERVATIONS.items():
        if (
            not isinstance(observation, tuple)
            or len(observation) != 2
            or observation[0] not in LIMIT_DEFAULTS
            or observation[1] not in LIMIT_DEFAULTS[observation[0]]
        ):
            return f"{qualified_field} runtime observation is malformed"
        profile = limit_event_profile(qualified_field)
        if profile is None:
            return f"{qualified_field} runtime observation is unbound"
        owner = profile[0].get("path")
        expected_owner = LIMIT_DEFAULTS[observation[0]][observation[1]][0]
        if owner != expected_owner:
            return f"{qualified_field} runtime observation owner differs"

    multi_charge_counts = {
        event_id: len(specs[event_id].charges)
        for event_id in (
            "ref.visible_record_read",
            "ref.orphan_origin_read",
            "accepted.object_read",
            "branch.ancestry_node",
            "branch.actual_receipt_read",
            "branch.actual_binding_visit",
            "branch.actual_object_read",
            "branch.cached_fact_use",
        )
    }
    if multi_charge_counts != {
        "ref.visible_record_read": 2,
        "ref.orphan_origin_read": 2,
        "accepted.object_read": 2,
        "branch.ancestry_node": 2,
        "branch.actual_receipt_read": 2,
        "branch.actual_binding_visit": 2,
        "branch.actual_object_read": 4,
        "branch.cached_fact_use": 4,
    }:
        return "shared atomic multi-budget window membership differs"
    for event_id in (
        "branch.actual_receipt_read",
        "branch.actual_binding_visit",
        "branch.actual_object_read",
    ):
        fields = tuple(charge[0] for charge in specs[event_id].charges)
        if not any("::per_pointer." in field for field in fields) or not any(
            "::union." in field for field in fields
        ):
            return f"{event_id} does not charge head and union atomically"
        if not specs[event_id].retains:
            return f"{event_id} does not retain its exact cache work"
    cached_fields = tuple(
        charge[0] for charge in specs["branch.cached_fact_use"].charges
    )
    if (
        any("::union." in field for field in cached_fields)
        or specs["branch.cached_fact_use"].retains
    ):
        return "cached fact use charges union or republishes cache work"
    if (
        not isinstance(expected_digest, str)
        or limit_event_specs_sha256(specs) != expected_digest
    ):
        return "limit event authority digest differs"
    return None


def limit_event_window_problem(
    source: str,
    spec: LimitEventSpec,
) -> str | None:
    production = normal_build_source(source)
    _path, owner, function = spec.site
    body = rust_named_function_raw_body(production, function, owner)
    if body is None:
        return f"cannot isolate limit event site {owner}::{function}"
    if re.search(r"\bcfg\s*!\s*\(", rust_code_projection(body)):
        return "limit event owner contains compile-time cfg! control"
    expected = limit_event_expected_statements(spec)
    event_range = exact_lexical_statement_sequence_range(body, expected)
    if event_range is None:
        return "exact source/add/guard/commit/sink window is absent or repeated"
    window = body[event_range[0] : event_range[1]]
    normalized_window = normalize_limit_event_tokens(window)
    for token in spec.bypass_tokens:
        if token in normalized_window:
            return f"event window contains bypass token {token!r}"
    for qualified_field, counter, next_identifier, delta in spec.charges:
        resolved = limit_event_profile(qualified_field)
        if resolved is None:
            return f"unknown event field {qualified_field}"
        profile, field = resolved
        helper = profile["helper"]
        checked = normalize_limit_event_tokens(f"{counter}.checked_add({delta})")
        guard = normalize_limit_event_tokens(
            f"{helper}({next_identifier},limits.{field})?"
        )
        commit = normalize_limit_event_tokens(f"{counter}={next_identifier};")
        if normalized_window.count(checked) != 1:
            return f"{qualified_field} lacks one checked-add of its trusted delta"
        if normalized_window.count(guard) != 1:
            return f"{qualified_field} lacks one guard of its next value"
        if normalized_window.count(commit) != 1:
            return f"{qualified_field} lacks one post-guard counter commit"
    return None


def limit_sink_call_target(statement: str) -> str | None:
    projected = rust_code_projection(statement)
    match = re.search(
        rf"(?P<callee>(?:::)?{RUST_IDENTIFIER}"
        rf"(?:(?:::|\.){RUST_IDENTIFIER})*)\s*\(",
        projected,
    )
    if match is None:
        return None
    return semantic_rust_identifier(match["callee"])


