def error_source_helper_problem(source: str, relative: str) -> str | None:
    mask = rust_code_mask(source)
    module_range = exact_test_module_range(source, mask)
    if module_range is None:
        return "lacks one exact cfg(test) module"
    opening, closing = module_range
    module_projection = rust_code_projection(source[opening + 1 : closing])
    signatures = rust_direct_function_signature(
        module_projection, "exact_error_source_chain", "private"
    )
    expected_signature = error_source_helper_expected_signature(relative)
    if len(signatures) != 1 or normalize_rust_tokens(signatures[0]) != (
        normalize_rust_tokens(expected_signature)
    ):
        return "exact source-chain helper signature differs"
    body = rust_named_function_raw_body(source, "exact_error_source_chain", "mod:tests")
    if body is None:
        return "cannot isolate exact source-chain helper body"
    expected_body = error_source_helper_expected_body(relative)
    if normalize_rust_tokens(body) != normalize_rust_tokens(expected_body):
        return "exact source-chain helper body differs"
    return None


