def recovery_ancestry_plan_digest_expected_body(relative: str) -> str:
    epoch_type = recovery_ancestry_plan_digest_epoch_type(relative)
    return f"""\
let epoch_budget = match epochs {{
    {epoch_type}::One => 1_u64,
    {epoch_type}::Two => 2_u64,
}};
let root_bytes = owner_root.as_os_str().as_encoded_bytes();
let root_len = u64::try_from(root_bytes.len()).expect("test root length");
let mut hasher = ::blake3::Hasher::new();
hasher.update(b"sley2.s20-530.recovery-ancestry-test-plan.v1");
hasher.update(&root_len.to_le_bytes());
hasher.update(root_bytes);
hasher.update(&epoch_budget.to_le_bytes());
hasher.update(left.as_bytes());
hasher.update(right.as_bytes());
*hasher.finalize().as_bytes()
"""


def recovery_ancestry_plan_digest_helper_problem(
    source: str,
    relative: str,
) -> str | None:
    mask = rust_code_mask(source)
    module_range = exact_test_module_range(source, mask)
    if module_range is None:
        return "lacks one exact cfg(test) module"
    opening, closing = module_range
    module_projection = rust_code_projection(source[opening + 1 : closing])
    epoch_type = recovery_ancestry_plan_digest_epoch_type(relative)
    expected_signature = (
        "fn expected_recovery_ancestry_test_plan_digest("
        "owner_root: &::std::path::Path, "
        f"epochs: {epoch_type}, "
        "left: ::sley_id::TransactionId, right: ::sley_id::TransactionId,"
        ") -> [u8; 32]"
    )
    signatures = rust_direct_function_signature(
        module_projection,
        "expected_recovery_ancestry_test_plan_digest",
        "private",
    )
    if len(signatures) != 1 or normalize_rust_tokens(signatures[0]) != (
        normalize_rust_tokens(expected_signature)
    ):
        return "exact plan-digest helper signature differs"
    body = rust_named_function_raw_body(
        source,
        "expected_recovery_ancestry_test_plan_digest",
        "mod:tests",
    )
    if body is None:
        return "cannot isolate exact plan-digest helper body"
    if normalize_rust_tokens(body) != normalize_rust_tokens(
        recovery_ancestry_plan_digest_expected_body(relative)
    ):
        return "exact plan-digest helper body differs"
    return None


