def exact_tree_delta_paths_expected_body() -> str:
    return """\
let before_by_path = before
    .iter()
    .map(|(path, snapshot)| (path.clone(), snapshot))
    .collect::<::std::collections::BTreeMap<_, _>>();
let after_by_path = after
    .iter()
    .map(|(path, snapshot)| (path.clone(), snapshot))
    .collect::<::std::collections::BTreeMap<_, _>>();
let added = after_by_path
    .keys()
    .filter(|path| !before_by_path.contains_key(*path))
    .cloned()
    .collect::<::std::vec::Vec<_>>();
let changed = after_by_path
    .iter()
    .filter_map(|(path, after_snapshot)| match before_by_path.get(path) {
        ::core::option::Option::Some(before_snapshot)
            if *before_snapshot != *after_snapshot =>
        {
            ::core::option::Option::Some(path.clone())
        }
        _ => ::core::option::Option::None,
    })
    .collect::<::std::vec::Vec<_>>();
let removed = before_by_path
    .keys()
    .filter(|path| !after_by_path.contains_key(*path))
    .cloned()
    .collect::<::std::vec::Vec<_>>();
(added, changed, removed)
"""


def snapshot_helpers_problem(source: str) -> str | None:
    mask = rust_code_mask(source)
    module_range = exact_test_module_range(source, mask)
    if module_range is None:
        return "lacks one exact cfg(test) module"
    opening, closing = module_range
    module_projection = rust_code_projection(source[opening + 1 : closing])
    aliases = (
        "type ExactPathSnapshot = ("
        "&'static str, u32, ::std::vec::Vec<u8>, "
        "::core::option::Option<::std::path::PathBuf>);",
        "type ExactTreeSnapshot = ::std::vec::Vec<("
        "::std::path::PathBuf, ExactPathSnapshot)>;",
        "type ExactOptionalPathSnapshot = ::core::option::Option<ExactPathSnapshot>;",
        "type ExactTreeDeltaPaths = ("
        "::std::vec::Vec<::std::path::PathBuf>, "
        "::std::vec::Vec<::std::path::PathBuf>, "
        "::std::vec::Vec<::std::path::PathBuf>);",
    )
    for alias in aliases:
        if (
            normalize_rust_tokens(module_projection).count(normalize_rust_tokens(alias))
            != 1
        ):
            return "exact snapshot type aliases differ"
    signatures = {
        "exact_path_snapshot": (
            "fn exact_path_snapshot(path: &::std::path::Path) -> ExactPathSnapshot"
        ),
        "exact_tree_snapshot": (
            "fn exact_tree_snapshot(root: &::std::path::Path) -> ExactTreeSnapshot"
        ),
        "exact_optional_path_snapshot": (
            "fn exact_optional_path_snapshot(path: &::std::path::Path) "
            "-> ExactOptionalPathSnapshot"
        ),
        "exact_tree_delta_paths": (
            "fn exact_tree_delta_paths("
            "before: &ExactTreeSnapshot, after: &ExactTreeSnapshot,"
            ") -> ExactTreeDeltaPaths"
        ),
    }
    expected_bodies = {
        "exact_path_snapshot": exact_path_snapshot_expected_body(),
        "exact_tree_snapshot": exact_tree_snapshot_expected_body(),
        "exact_optional_path_snapshot": exact_optional_path_snapshot_expected_body(),
        "exact_tree_delta_paths": exact_tree_delta_paths_expected_body(),
    }
    for helper, expected_signature in signatures.items():
        actual_signatures = rust_direct_function_signature(
            module_projection,
            helper,
            "private",
        )
        if len(actual_signatures) != 1 or normalize_rust_tokens(
            actual_signatures[0]
        ) != normalize_rust_tokens(expected_signature):
            return f"{helper} signature differs"
        body = rust_named_function_raw_body(source, helper, "mod:tests")
        if body is None:
            return f"cannot isolate {helper} body"
        if normalize_rust_tokens(body) != normalize_rust_tokens(
            expected_bodies[helper]
        ):
            return f"{helper} body differs"
    return None


def require_snapshot_helpers(sources: dict[str, str]) -> None:
    for relative in (
        "crates/sley-store/src/lib.rs",
        "crates/sley-txn/src/repository.rs",
        "crates/sley-repo/src/refs.rs",
        "crates/sley-repo/src/gc.rs",
    ):
        if problem := snapshot_helpers_problem(sources[relative]):
            fail(f"{relative} exact snapshot helpers differ: {problem}")
    for relative in (
        "crates/sley-txn/src/repository.rs",
        "crates/sley-repo/src/refs.rs",
    ):
        if problem := recovery_ancestry_plan_digest_helper_problem(
            sources[relative],
            relative,
        ):
            fail(f"{relative} recovery-ancestry plan digest helper differs: {problem}")


