def top_level_let_statement_ranges(
    source: str,
    identifier: str,
) -> tuple[tuple[int, int, str], ...]:
    projected = rust_code_projection(source)
    ranges: list[tuple[int, int, str]] = []
    for match in re.finditer(r"\blet\b", projected):
        if delimiter_depth_at(source, match.start()) != (0, 0, 0):
            continue
        round_depth = square_depth = brace_depth = 0
        assignment = None
        end = None
        for index in range(match.end(), len(projected)):
            character = projected[index]
            if character == "(":
                round_depth += 1
            elif character == ")":
                round_depth -= 1
            elif character == "[":
                square_depth += 1
            elif character == "]":
                square_depth -= 1
            elif character == "{":
                brace_depth += 1
            elif character == "}":
                if brace_depth == 0:
                    break
                brace_depth -= 1
            elif (
                character == "="
                and assignment is None
                and round_depth == square_depth == brace_depth == 0
            ):
                assignment = index
            elif (
                character == ";"
                and assignment is not None
                and round_depth == square_depth == brace_depth == 0
            ):
                end = index + 1
                break
            if min(round_depth, square_depth, brace_depth) < 0:
                break
        if assignment is None or end is None:
            continue
        if not code_contains_token(source[match.end() : assignment], identifier):
            continue
        ranges.append((match.start(), end, source[match.start() : end]))
    return tuple(ranges)


def top_level_statement_ranges(
    source: str,
) -> tuple[tuple[int, int, str], ...]:
    projected = rust_code_projection(source)
    ranges: list[tuple[int, int, str]] = []
    cursor = 0
    while cursor < len(projected):
        while cursor < len(projected) and projected[cursor].isspace():
            cursor += 1
        if cursor >= len(projected):
            break
        start = cursor
        round_depth = square_depth = brace_depth = 0
        end: int | None = None
        while cursor < len(projected):
            character = projected[cursor]
            if character == "(":
                round_depth += 1
            elif character == ")":
                round_depth -= 1
            elif character == "[":
                square_depth += 1
            elif character == "]":
                square_depth -= 1
            elif character == "{":
                brace_depth += 1
            elif character == "}":
                if brace_depth == 0:
                    break
                brace_depth -= 1
            elif character == ";" and round_depth == square_depth == brace_depth == 0:
                end = cursor + 1
                break
            if min(round_depth, square_depth, brace_depth) < 0:
                break
            cursor += 1
        if end is None:
            break
        ranges.append((start, end, source[start:end]))
        cursor = end
    return tuple(ranges)


def exact_statement_sequence_range(
    source: str,
    expected: tuple[str, ...],
) -> tuple[int, int] | None:
    if not expected:
        return None
    statements = top_level_statement_ranges(source)
    normalized_expected = tuple(normalize_rust_tokens(value) for value in expected)
    matches: list[tuple[int, int]] = []
    for index in range(0, len(statements) - len(expected) + 1):
        window = statements[index : index + len(expected)]
        if tuple(normalize_rust_tokens(value[2]) for value in window) == (
            normalized_expected
        ):
            matches.append((window[0][0], window[-1][1]))
    return matches[0] if len(matches) == 1 else None


def normalize_limit_event_tokens(value: str) -> str:
    normalized = normalize_rust_tokens(value)
    stack: list[int] = []
    pairs: dict[int, int] = {}
    for index, character in enumerate(normalized):
        if character == "(":
            stack.append(index)
        elif character == ")" and stack:
            pairs[index] = stack.pop()
    removals: set[int] = set()
    control_words = {"if", "while", "for", "match", "loop"}
    for closing, opening in pairs.items():
        comma = closing - 1
        if comma < 0 or normalized[comma] != ",":
            continue
        cursor = opening - 1
        if cursor < 0:
            continue
        character = normalized[cursor]
        callable_opening = character in ")]}>?!"
        if character.isalnum() or character == "_":
            end = cursor + 1
            while cursor >= 0 and (
                normalized[cursor].isalnum() or normalized[cursor] == "_"
            ):
                cursor -= 1
            callable_opening = normalized[cursor + 1 : end] not in control_words
        if callable_opening:
            removals.add(comma)
    return "".join(
        character for index, character in enumerate(normalized) if index not in removals
    )


def limit_event_scope_prefix(
    projected: str,
    brace_pairs: dict[int, int],
    parent: int | None,
    opening: int,
) -> str:
    """Return the direct parent-scope syntax that owns one candidate brace."""
    cursor = 0 if parent is None else parent + 1
    boundary = cursor
    round_depth = 0
    square_depth = 0
    while cursor < opening:
        character = projected[cursor]
        if character == "(":
            round_depth += 1
        elif character == ")":
            round_depth -= 1
        elif character == "[":
            square_depth += 1
        elif character == "]":
            square_depth -= 1
        elif character == "{" and round_depth == square_depth == 0:
            closing = brace_pairs.get(cursor)
            if closing is None or closing >= opening:
                return ""
            cursor = closing
            boundary = cursor + 1
        elif character in ";," and round_depth == square_depth == 0:
            boundary = cursor + 1
        if round_depth < 0 or square_depth < 0:
            return ""
        cursor += 1
    if round_depth != 0 or square_depth != 0:
        return ""
    return projected[boundary:opening]


def limit_event_prefix_has_detached_owner(prefix: str, control_start: int) -> bool:
    before = rust_code_projection(prefix[:control_start])
    top_level = "".join(
        character if delimiter_depth_at(before, index) == (0, 0, 0) else " "
        for index, character in enumerate(before)
    )
    if re.search(
        r"(?:^|[=(:,])\s*(?:async\s+|move\s+|async\s+move\s+)?"
        r"\|[^|]*\|\s*(?:->\s*[^{}]+)?$",
        top_level,
    ):
        return True
    if re.search(
        rf"(?:::)?{RUST_IDENTIFIER}(?:::{RUST_IDENTIFIER})*\s*!\s*[({{\[]",
        top_level,
    ):
        return True
    return False


def limit_event_control_kind(prefix: str, parent_kind: str) -> str | None:
    projected = rust_code_projection(prefix)
    stripped = projected.strip()
    if re.search(r"\bcfg\s*!\s*\(", projected):
        return None
    if parent_kind.startswith("match:") and stripped.endswith("=>"):
        normalized_arm = normalize_rust_tokens(stripped)
        if "iffalse=>" in normalized_arm:
            return None
        scrutinee = parent_kind.removeprefix("match:")
        pattern = normalized_arm.removesuffix("=>").split("if", 1)[0]
        literal = r"(?:true|false|[0-9][0-9_]*)"
        if re.fullmatch(literal, scrutinee) and re.fullmatch(literal, pattern):
            if scrutinee != pattern:
                return None
        return "match-arm"
    control_matches = tuple(
        match
        for match in re.finditer(r"\b(if|for|while|loop|match)\b", projected)
        if delimiter_depth_at(projected, match.start()) == (0, 0, 0)
    )
    if not control_matches:
        return "else" if stripped == "else" else None
    control = control_matches[-1]
    if limit_event_prefix_has_detached_owner(prefix, control.start()):
        return None
    kind = control[1]
    tail = normalize_rust_tokens(projected[control.end() :])
    if kind in {"if", "while"} and (
        tail in {"false", "(false)"} or tail.startswith("false&&")
    ):
        return None
    if kind == "for" and re.search(r"\b(?:core|std)::iter::empty(?:::<.*>)?\(\)", tail):
        return None
    if kind == "if" and tail in {"true", "(true)"}:
        return "if-true"
    if kind == "match":
        return f"match:{tail}"
    return kind


def limit_event_executable_scope_records(
    source: str,
) -> tuple[tuple[int, int, str, str], ...]:
    """Enumerate root and directly executable scopes with exact control headers."""
    projected = rust_code_projection(source)
    stack: list[int] = []
    pairs: dict[int, int] = {}
    parents: dict[int, int | None] = {}
    for index, character in enumerate(projected):
        if character == "{":
            parents[index] = stack[-1] if stack else None
            stack.append(index)
        elif character == "}":
            if not stack:
                return ()
            pairs[stack.pop()] = index
    if stack:
        return ()

    scopes: list[tuple[int, int, str, str]] = [(0, len(source), "root", "")]
    accepted_kinds: dict[int | None, str] = {None: "root"}
    openings_by_close = {closing: opening for opening, closing in pairs.items()}
    for opening in sorted(pairs):
        parent = parents[opening]
        parent_kind = accepted_kinds.get(parent)
        if parent_kind is None:
            continue
        prefix = limit_event_scope_prefix(projected, pairs, parent, opening)
        kind = limit_event_control_kind(prefix, parent_kind)
        if kind is None:
            continue
        if kind == "else":
            else_start = opening - len(prefix) + prefix.find("else")
            cursor = else_start - 1
            while cursor >= 0 and projected[cursor].isspace():
                cursor -= 1
            prior_opening = openings_by_close.get(cursor)
            if (
                prior_opening is not None
                and accepted_kinds.get(prior_opening) == "if-true"
            ):
                continue
        accepted_kinds[opening] = kind
        scopes.append((opening + 1, pairs[opening], kind, prefix))
    return tuple(scopes)


def limit_event_executable_scopes(source: str) -> tuple[tuple[int, int], ...]:
    """Enumerate only root and directly executable control-flow statement scopes."""
    return tuple(
        (start, end)
        for start, end, _kind, _prefix in limit_event_executable_scope_records(source)
    )


def exact_lexical_statement_sequence_range(
    source: str,
    expected: tuple[str, ...],
) -> tuple[int, int] | None:
    if not expected:
        return None
    normalized_expected = tuple(
        normalize_limit_event_tokens(value) for value in expected
    )
    matches: list[tuple[int, int]] = []
    for scope_start, scope_end in limit_event_executable_scopes(source):
        statements = top_level_statement_ranges(source[scope_start:scope_end])
        for index in range(0, len(statements) - len(expected) + 1):
            window = statements[index : index + len(expected)]
            if tuple(normalize_limit_event_tokens(value[2]) for value in window) == (
                normalized_expected
            ):
                absolute = (
                    scope_start + window[0][0],
                    scope_start + window[-1][1],
                )
                matches.append(absolute)
    return matches[0] if len(matches) == 1 else None


def operation_result_error_ranges(
    body: str,
    row_id: str,
    subcase_id: str | None,
    leaf_id: str | None = None,
) -> tuple[
    str | None,
    tuple[int, int] | None,
    tuple[int, int] | None,
]:
    operation = error_operation_call(row_id, subcase_id, leaf_id)
    expected_result_binding = f"let result = {operation};"
    result_bindings = top_level_let_statement_ranges(body, "result")
    if len(result_bindings) != 1:
        return "result is not bound exactly once at test-body scope", None, None
    result_start, result_end, result_statement = result_bindings[0]
    if normalize_rust_tokens(result_statement) != normalize_rust_tokens(
        expected_result_binding
    ):
        return (
            "result is not bound directly to the frozen recovery operation",
            None,
            None,
        )
    normalized_operation = code_only_normalized(operation)
    if code_only_normalized(body).count(normalized_operation) != 1:
        return "the frozen recovery operation is not invoked exactly once", None, None

    error_bindings = top_level_let_statement_ranges(body, "error")
    if len(error_bindings) != 1:
        return "error is not extracted exactly once at test-body scope", None, None
    error_start, error_end, error_statement = error_bindings[0]
    expected_error_binding = 'let error = result.expect_err("expected recovery error");'
    if normalize_rust_tokens(error_statement) != normalize_rust_tokens(
        expected_error_binding
    ):
        return "error is not extracted directly from the frozen result", None, None
    if error_start <= result_end:
        return "error extraction does not follow the recovery operation", None, None
    if result_start >= result_end or error_start >= error_end:
        return "operation/error binding ranges are malformed", None, None
    return None, (result_start, result_end), (error_start, error_end)


def exact_snapshot_binding_range(
    body: str,
    identifier: str,
    expected_statement: str,
) -> tuple[int, int] | None:
    bindings = top_level_let_statement_ranges(body, identifier)
    if len(bindings) != 1:
        return None
    start, end, statement = bindings[0]
    if normalize_rust_tokens(statement) != normalize_rust_tokens(expected_statement):
        return None
    return start, end


def snapshot_binding_problem(
    body: str,
    relative: str,
    row_id: str,
    subcase_id: str | None,
    result_range: tuple[int, int],
    error_range: tuple[int, int],
    no_mutation_assertion: object,
    leaf_id: str | None = None,
) -> str | None:
    result_start, _result_end = result_range
    _error_start, error_end = error_range
    projected_body = rust_code_projection(body)
    if re.search(r"\b(?:restore|restorer|restoration)\b", projected_body):
        return "mapped test contains owner-state restoration authority"
    if re.search(
        r"(?:\b(?:std\s*::\s*)?thread\s*::\s*spawn\b|"
        r"\b(?:std\s*::\s*)?process\s*::\s*Command\s*::\s*new\b)",
        projected_body,
    ):
        return "mapped test contains concurrent or process restoration authority"
    owner_root = error_operation_owner_root(row_id, subcase_id, leaf_id)
    owner_binding = exact_snapshot_binding_range(
        body,
        "owner_root",
        f"let owner_root = {owner_root};",
    )
    if owner_binding is None:
        return "owner root is not bound exactly to the operation receiver"
    tree_helper = snapshot_helper_path(relative, "exact_tree_snapshot")
    before_tree = exact_snapshot_binding_range(
        body,
        "owner_tree_before_snapshot",
        (f"let owner_tree_before_snapshot = {tree_helper}(owner_root);"),
    )
    after_tree = exact_snapshot_binding_range(
        body,
        "owner_tree_after_snapshot",
        (f"let owner_tree_after_snapshot = {tree_helper}(owner_root);"),
    )
    if before_tree is None or after_tree is None:
        return "owner tree snapshots are not bound to the frozen helper"
    if not (owner_binding[1] <= before_tree[0] and before_tree[1] <= result_start):
        return "owner-tree before snapshot does not precede the recovery operation"
    if after_tree[0] < error_end:
        return "owner-tree after snapshot does not follow error extraction"
    after_sequence: list[tuple[int, int]] = [after_tree]
    if not isinstance(no_mutation_assertion, str):
        return "no-mutation assertion is not text"
    no_mutation_starts = exact_direct_statement_starts(
        body,
        no_mutation_assertion,
    )
    if len(no_mutation_starts) != 1 or no_mutation_starts[0] < after_tree[1]:
        return "no-mutation assertion does not follow the bound after snapshot"

    path_helper = snapshot_helper_path(relative, "exact_path_snapshot")
    for name in PREFLIGHT_CANARIES.get(row_id, ()):
        path_binding: tuple[int, int] | None = None
        if name == "gc_witness":
            path_binding = exact_snapshot_binding_range(
                body,
                "gc_witness_path",
                ('let gc_witness_path = owner_root.join("locks").join("gc.lock");'),
            )
            if path_binding is None:
                return "GC witness path is not derived exactly from the owner root"
        before_snapshot_name = f"{name}_before_snapshot"
        before_kind_name = f"{name}_before_kind"
        after_snapshot_name = f"{name}_after_snapshot"
        after_kind_name = f"{name}_after_kind"
        before_snapshot = exact_snapshot_binding_range(
            body,
            before_snapshot_name,
            (f"let {before_snapshot_name} = {path_helper}(&{name}_path);"),
        )
        before_kind = exact_snapshot_binding_range(
            body,
            before_kind_name,
            f"let {before_kind_name} = {before_snapshot_name}.0;",
        )
        after_snapshot = exact_snapshot_binding_range(
            body,
            after_snapshot_name,
            (f"let {after_snapshot_name} = {path_helper}(&{name}_path);"),
        )
        after_kind = exact_snapshot_binding_range(
            body,
            after_kind_name,
            f"let {after_kind_name} = {after_snapshot_name}.0;",
        )
        if None in (before_snapshot, before_kind, after_snapshot, after_kind):
            return f"{name} snapshot/kind bindings differ"
        assert before_snapshot is not None
        assert before_kind is not None
        assert after_snapshot is not None
        assert after_kind is not None
        after_sequence.extend((after_snapshot, after_kind))
        if path_binding is not None and not (
            owner_binding[1] <= path_binding[0]
            and path_binding[1] <= before_snapshot[0]
        ):
            return "GC witness path binding does not precede its snapshots"
        if not (
            before_snapshot[1] <= before_kind[0] and before_kind[1] <= result_start
        ):
            return f"{name} before snapshot/kind does not precede recovery"
        expected_kind = PREFLIGHT_CANARY_KINDS.get(
            (row_id, subcase_id, name),
            "regular",
        )
        expected_kind_assertion = (
            f"::core::assert_eq!({before_kind_name}, {json.dumps(expected_kind)});"
        )
        expected_kind_starts = exact_direct_statement_starts(
            body,
            expected_kind_assertion,
        )
        if len(expected_kind_starts) != 1 or not (
            before_kind[1] <= expected_kind_starts[0] < result_start
        ):
            return f"{name} expected-kind assertion is not bound before recovery"
        fixture_assertion = PREFLIGHT_CANARY_FIXTURE_ASSERTIONS.get(
            (row_id, subcase_id, name)
        )
        if fixture_assertion is not None:
            fixture_starts = exact_direct_statement_starts(body, fixture_assertion)
            if len(fixture_starts) != 1 or not (
                before_kind[1] <= fixture_starts[0] < result_start
            ):
                return f"{name} exact fixture assertion is not bound before recovery"
        if not (error_end <= after_snapshot[0] and after_snapshot[1] <= after_kind[0]):
            return f"{name} after snapshot/kind does not follow recovery"
    cursor = error_end
    for start, end in sorted(after_sequence):
        if rust_code_projection(body[cursor:start]).strip():
            return "after snapshots are not the immediate post-error statements"
        cursor = end
    return None


def operation_error_binding_problem(
    body: str,
    relative: str,
    row_id: str,
    subcase_id: str | None,
    semantic: dict[str, object],
    leaf_id: str | None = None,
) -> str | None:
    problem, result_range, error_range = operation_result_error_ranges(
        body,
        row_id,
        subcase_id,
        leaf_id,
    )
    if problem is not None or result_range is None or error_range is None:
        return problem or "operation/error binding ranges are absent"
    _result_start, result_end = result_range
    error_start, error_end = error_range

    no_success = semantic.get("no_success_report")
    if not isinstance(no_success, str):
        return "no-success assertion is not text"
    no_success_starts = exact_direct_statement_starts(body, no_success)
    if len(no_success_starts) != 1:
        return "no-success assertion is not one exact direct statement"
    if not (result_end <= no_success_starts[0] < error_start):
        return (
            "no-success assertion does not bind the operation result before extraction"
        )

    for field in (
        "expected_result",
        "expected_variant",
        "expected_source_chain",
    ):
        assertion = semantic.get(field)
        if not isinstance(assertion, str):
            return f"{field} assertion is not text"
        starts = exact_direct_statement_starts(body, assertion)
        if len(starts) != 1:
            return f"{field} assertion is not one exact direct statement"
        if starts[0] < error_end:
            return f"{field} assertion precedes exact error extraction"
    return snapshot_binding_problem(
        body,
        relative,
        row_id,
        subcase_id,
        result_range,
        error_range,
        semantic.get("no_mutation"),
        leaf_id,
    )


def corruption_fixture_evidence_problem(
    key: tuple[str, str, str],
    entry: dict[str, object],
    relative: str,
    body: str,
) -> str | None:
    try:
        spec = CORRUPTION_FIXTURE_SPECS[key]
    except KeyError:
        return "does not identify one frozen corruption fixture"
    if relative != spec.owner_source:
        return "mapped test owner differs from the fixture owner"
    expected_digest, rendered = corruption_fixture_plan(key, spec)
    if entry.get("fixture_plan_sha256") != expected_digest:
        return "fixture plan digest differs"
    fixture_assertions = entry.get("fixture_assertions")
    if (
        not isinstance(fixture_assertions, dict)
        or tuple(fixture_assertions) != spec.required_facts
        or fixture_assertions != rendered.fact_assertions
    ):
        return "fixture assertions differ from the checker-rendered plan"
    assertions = entry.get("assertions")
    if not isinstance(assertions, list):
        return "fixture evidence lacks one assertion list"
    for fact, assertion in rendered.fact_assertions.items():
        if assertion not in assertions:
            return f"fixture fact {fact!r} is absent from evidence assertions"
        starts = exact_direct_statement_starts(body, assertion)
        if len(starts) != 1:
            return f"fixture fact {fact!r} is not one exact mapped-test statement"
    if key in GROUPED_MULTIFAULT_CASES:
        return None
    plan_range = exact_statement_sequence_range(body, rendered.statements)
    if plan_range is None:
        return "mapped test lacks one exact contiguous fixture-plan sequence"
    plan_start, plan_end = plan_range
    if rust_code_projection(body[:plan_start]).strip():
        return "mapped test executes code before its fresh fixture plan"
    problem, result_range, _error_range = operation_result_error_ranges(
        body,
        key[0],
        key[1],
        key[2],
    )
    if problem is not None or result_range is None:
        return problem or "fixture plan lacks its exact operation result"
    if plan_end != result_range[1]:
        return "fixture-plan sequence does not end at its exact operation result"
    projected = rust_code_projection(body)
    for helper in rendered.helper_ids:
        if len(re.findall(rf"\b{re.escape(helper)}\s*\(", projected)) != 1:
            return f"fixture helper {helper!r} is not called exactly once"
    if len(re.findall(r"\bFixture\s*::\s*new\s*\(", projected)) != 1:
        return "fixture plan does not own exactly one fresh Fixture"
    return None


def recovery_provenance_evidence_problem(
    case_id: tuple[str, str | None],
    entry: dict[str, object],
    relative: str,
    body: str,
) -> str | None:
    try:
        spec = RECOVERY_PROVENANCE_SPECS[case_id]
    except KeyError:
        return "does not identify one frozen recovery provenance case"
    if relative != spec.owner_source:
        return "mapped test owner differs from the provenance owner"
    if entry.get("fixture_plan_sha256") != recovery_provenance_plan_sha256(
        case_id,
        spec,
    ):
        return "recovery provenance plan digest differs"
    expected_assertions = recovery_provenance_fact_assertions(case_id, spec)
    actual_assertions = entry.get("fixture_assertions")
    if (
        not isinstance(actual_assertions, dict)
        or tuple(actual_assertions) != spec.required_facts
        or actual_assertions != expected_assertions
    ):
        return "recovery provenance assertions differ from checker rendering"
    assertions = entry.get("assertions")
    if not isinstance(assertions, list):
        return "recovery provenance evidence lacks one assertion list"
    problem, result_range, error_range = operation_result_error_ranges(
        body,
        case_id[0],
        case_id[1],
    )
    if problem is not None or result_range is None or error_range is None:
        return problem or "recovery provenance operation ranges are absent"
    result_start, _result_end = result_range
    _error_start, error_end = error_range
    post_fact_markers = (
        "_unchanged",
        "observed_",
        "plan_consumed_",
        "production_core_binding",
    )
    for fact, assertion in expected_assertions.items():
        if assertion not in assertions:
            return f"recovery provenance fact {fact!r} is absent from assertions"
        starts = exact_direct_statement_starts(body, assertion)
        if len(starts) != 1:
            return f"recovery provenance fact {fact!r} is not one direct statement"
        post_operation = (
            fact.endswith(post_fact_markers[0])
            or fact.startswith(post_fact_markers[1:3])
            or fact == post_fact_markers[3]
        )
        if post_operation and starts[0] < error_end:
            return f"post-operation provenance fact {fact!r} precedes error extraction"
        if not post_operation and starts[0] >= result_start:
            return f"pre-operation provenance fact {fact!r} does not precede recovery"
    projected = rust_code_projection(body)
    expected_fixture_count = 2 if spec.guard_relation == "wrong_root_exclusive" else 1
    if len(re.findall(r"\bFixture\s*::\s*new\s*\(", projected)) != (
        expected_fixture_count
    ):
        return "fresh real-root fixture cardinality differs"
    expected_acquisition = (
        "acquire_shared_maintenance"
        if spec.guard_relation == "same_root_shared"
        else "acquire_exclusive_maintenance"
    )
    acquisitions = re.findall(
        r"\b(?:acquire_shared_maintenance|acquire_exclusive_maintenance)\s*\(",
        projected,
    )
    if len(acquisitions) != 1 or expected_acquisition not in acquisitions[0]:
        return "maintenance acquisition mode or cardinality differs"
    if spec.guard_relation == "wrong_root_exclusive":
        if (
            "canonical_owner_root" not in projected
            or "canonical_guard_root" not in projected
        ):
            return "wrong-root fixture lacks both canonical root bindings"
        for name in ("guard_tree_before_snapshot", "guard_tree_after_snapshot"):
            if len(top_level_let_statement_ranges(body, name)) != 1:
                return f"wrong-root fixture lacks one exact {name} binding"
    if spec.fixture_family == "logical_cycle":
        if (
            len(
                re.findall(
                    r"\binstall_recovery_ancestry_l_r_l_test_plan\s*\(", projected
                )
            )
            != 1
        ):
            return "logical-cycle fixture lacks one exact production-core plan install"
        if len(top_level_let_statement_ranges(body, "cycle_observations")) != 1:
            return "logical-cycle fixture lacks one consumed observation binding"
    return None


def require_error_case_evidence(
    row_id: str,
    subcase_id: str | None,
    entry: dict[str, object],
    relative: str,
    source: str,
    leaf_id: str | None = None,
) -> None:
    label = (
        row_id
        if subcase_id is None
        else f"{row_id}/{subcase_id}"
        if leaf_id is None
        else f"{row_id}/{subcase_id}/{leaf_id}"
    )
    expected_code, expected_variant, expected_chain = (
        error_case_spec(row_id, subcase_id)
        if leaf_id is None
        else grouped_error_case_spec(row_id, str(subcase_id), leaf_id)
    )
    fields = error_evidence_field_order(row_id, subcase_id, leaf_id)
    if tuple(entry) != fields:
        fail(f"{label} error-evidence fields/order differ")
    for field, expected in (
        ("result", "PASS"),
        ("fresh_fixture", True),
        ("expected_result", expected_code),
        ("expected_variant", expected_variant),
        ("no_mutation", True),
        ("no_success_report", True),
    ):
        if not exact_json_scalar_equal(entry.get(field), expected):
            fail(f"{label} {field} differs in type or value")
    actual_chain = entry.get("expected_source_chain")
    if (
        not isinstance(actual_chain, list)
        or any(type(item) is not str for item in actual_chain)
        or tuple(actual_chain) != expected_chain
    ):
        fail(f"{label} exact source chain differs")
    semantic = entry.get("semantic_assertions")
    assertions = entry.get("assertions")
    if not isinstance(semantic, dict) or tuple(semantic) != (
        ERROR_SEMANTIC_ASSERTION_FIELDS
    ):
        fail(f"{label} error semantic-assertion fields/order differ")
    if not isinstance(assertions, list):
        fail(f"{label} lacks an assertion list")
    if len(set(semantic.values())) != len(ERROR_SEMANTIC_ASSERTION_FIELDS):
        fail(f"{label} reuses an error semantic assertion")
    for field, assertion in semantic.items():
        if not isinstance(assertion, str) or assertion not in assertions:
            fail(f"{label} semantic field {field} lacks an exact assertion")
    multifault_case = (row_id, str(subcase_id), leaf_id)
    if multifault_case in MULTIFAULT_OVERLAYS:
        expected_semantic = multifault_base_error_semantic_assertions(
            multifault_case, relative
        )
        if semantic != expected_semantic:
            fail(f"{label} base error semantics differ from multifault operation 1")
    else:
        if problem := exact_error_result_assertion_problem(
            semantic["expected_result"], relative, expected_variant, expected_code
        ):
            fail(f"{label} exact result assertion differs: {problem}")
        if problem := exact_error_variant_assertion_problem(
            semantic["expected_variant"], relative, expected_variant
        ):
            fail(f"{label} exact variant assertion differs: {problem}")
        if problem := exact_error_source_assertion_problem(
            semantic["expected_source_chain"], relative, expected_chain
        ):
            fail(f"{label} exact source-chain assertion differs: {problem}")
        mutation_operands = exact_assert_eq_operands(semantic["no_mutation"])
        if mutation_operands is None or {
            code_only_normalized(operand) for operand in mutation_operands
        } != {"owner_tree_before_snapshot", "owner_tree_after_snapshot"}:
            fail(
                f"{label} no-mutation assertion does not compare exact owner-tree snapshots"
            )
        if exact_assert_predicate(semantic["no_success_report"]) != "result.is_err()":
            fail(f"{label} no-success assertion is not exact result.is_err()")
    tests = entry.get("tests")
    if not isinstance(tests, list) or len(tests) != 1 or not isinstance(tests[0], str):
        fail(f"{label} lacks one exact test for operation binding")
    definition = exact_test_definition(source, tests[0])
    if definition is None:
        fail(f"{label} operation binding cannot isolate its mapped test")
    if leaf_id is not None and multifault_case not in MULTIFAULT_OVERLAYS:
        fixture_key = (row_id, str(subcase_id), leaf_id)
        if problem := corruption_fixture_evidence_problem(
            fixture_key,
            entry,
            relative,
            definition[0],
        ):
            fail(f"{label} corruption fixture binding differs: {problem}")
    provenance_key = (row_id, subcase_id)
    if provenance_key in RECOVERY_PROVENANCE_SPECS:
        if problem := recovery_provenance_evidence_problem(
            provenance_key,
            entry,
            relative,
            definition[0],
        ):
            fail(f"{label} recovery provenance binding differs: {problem}")
    if multifault_case not in MULTIFAULT_OVERLAYS:
        if problem := operation_error_binding_problem(
            definition[0],
            relative,
            row_id,
            subcase_id,
            semantic,
            leaf_id,
        ):
            fail(f"{label} operation/error binding differs: {problem}")


def multifault_key(
    row_id: str,
    subcase_id: str,
    leaf_id: str | None = None,
) -> MultifaultKey:
    return row_id, subcase_id, leaf_id


def multifault_operation_call(
    spec: MultifaultOverlaySpec,
    ordinal: int,
) -> str:
    profile = spec.operation_1_profile if ordinal == 1 else spec.operation_2_profile
    if profile == "production_call":
        calls = {
            "transaction_recovery": (
                "repository.recover_with_maintenance(&maintenance)"
            ),
            "ancestry_verifier": (
                "repository.verify_branch_recovery_ancestries_with_maintenance("
                "&maintenance, &requests)"
            ),
            "ref_recovery": (
                "branch_repository.recover_refs_with_maintenance(&maintenance)"
            ),
        }
        return calls[spec.recovery_operation]
    if profile == "private_final_receipts_1":
        return (
            "repository.recover_with_maintenance_and_limits("
            "&maintenance, transaction_limits_1, accepted_recovery_limits())"
        )
    if profile == "private_final_receipts_2_only":
        return (
            "repository.recover_with_maintenance_and_limits("
            "&maintenance, transaction_limits_2, accepted_recovery_limits())"
        )
    if profile == "private_final_origins_1":
        return (
            "branch_repository.recover_refs_with_maintenance_and_limits("
            "&maintenance, ref_limits_1)"
        )
    if profile == "private_final_origins_2_only":
        return (
            "branch_repository.recover_refs_with_maintenance_and_limits("
            "&maintenance, ref_limits_2)"
        )
    fail(f"unknown multifault operation profile {profile!r}")


def multifault_repair_statements(spec: MultifaultOverlaySpec) -> tuple[str, ...]:
    if spec.repair_class == "unlink_all_three_exact_symlinks_sync_distinct_parents":
        return (
            "::std::fs::remove_file(&m2_primary_paths[0]).unwrap();",
            "::std::fs::remove_file(&m2_primary_paths[1]).unwrap();",
            "::std::fs::remove_file(&m2_primary_paths[2]).unwrap();",
            "super::sync_dir(&m2_primary_parent_paths[0]).unwrap();",
            "super::sync_dir(&m2_primary_parent_paths[1]).unwrap();",
            "super::sync_dir(&m2_primary_parent_paths[2]).unwrap();",
        )
    if spec.repair_class == "replace_exact_profile_only_final_receipts_1_to_2":
        return (
            "let transaction_limits_2 = TransactionRecoveryLimits { "
            "receipt_fanout_directories: transaction_limits_1.receipt_fanout_directories, "
            "receipt_leaf_entries: transaction_limits_1.receipt_leaf_entries, "
            "final_receipts: 2_u64, receipt_stages: transaction_limits_1.receipt_stages, "
            "head_entries: transaction_limits_1.head_entries, "
            "head_stages: transaction_limits_1.head_stages };",
        )
    if spec.repair_class == "replace_exact_profile_only_final_origins_1_to_2":
        return (
            "let ref_limits_2 = RefRecoveryLimits { "
            "origin_fanout_directories: ref_limits_1.origin_fanout_directories, "
            "origin_leaf_entries: ref_limits_1.origin_leaf_entries, "
            "final_origins: 2_u64, origin_stages: ref_limits_1.origin_stages, "
            "origin_record_bytes: ref_limits_1.origin_record_bytes, "
            "ref_fanout_directories: ref_limits_1.ref_fanout_directories, "
            "ref_leaf_entries: ref_limits_1.ref_leaf_entries, "
            "ref_stages: ref_limits_1.ref_stages, "
            "visible_ref_record_bytes: ref_limits_1.visible_ref_record_bytes, "
            "orphan_origins: ref_limits_1.orphan_origins, "
            "visible_branches: ref_limits_1.visible_branches };",
        )
    return (
        "::std::fs::write(&m2_primary_path, &m2_pristine_primary_bytes).unwrap();",
        "::std::fs::File::open(&m2_primary_path).unwrap().sync_all().unwrap();",
        "super::sync_dir(m2_primary_path.parent().unwrap()).unwrap();",
    )


def multifault_cycle_type_path(
    spec: MultifaultOverlaySpec,
    type_name: str,
) -> str:
    prefix = (
        "crate::recovery_ancestry_test_hook"
        if spec.owner_source == TXN_PROVENANCE_SOURCE
        else "::sley_txn::recovery_ancestry_test_hook"
    )
    return f"{prefix}::{type_name}"


def multifault_cycle_plan_install_statement(
    spec: MultifaultOverlaySpec,
) -> str | None:
    contract = spec.cycle_epochs
    if contract is None:
        return None
    receiver = (
        "repository"
        if spec.owner_source == TXN_PROVENANCE_SOURCE
        else "transaction_repository"
    )
    budget = "One" if contract.epoch_budget == 1 else "Two"
    epoch_type = multifault_cycle_type_path(spec, "RecoveryAncestryTestEpochs")
    module = multifault_cycle_type_path(spec, "install")
    return (
        f"let m2_cycle_plan_identity = {module}("
        f"{receiver}, &maintenance, "
        f"{epoch_type}::{budget}, m2_cycle_left_transaction_id, "
        "m2_cycle_right_transaction_id).unwrap();"
    )


def multifault_cycle_observation_drain_statement(
    spec: MultifaultOverlaySpec,
) -> str | None:
    if spec.cycle_epochs is None:
        return None
    receiver = (
        "repository"
        if spec.owner_source == TXN_PROVENANCE_SOURCE
        else "transaction_repository"
    )
    module = multifault_cycle_type_path(spec, "take")
    return (
        f"let m2_cycle_drain = {module}("
        f"{receiver}, &maintenance, m2_cycle_plan_identity).unwrap();"
    )


def multifault_cycle_epoch_expression(spec: MultifaultOverlaySpec) -> str:
    contract = spec.cycle_epochs
    if contract is None:
        fail("non-cycle multifault case requested a recovery-ancestry epoch")
    variant = "One" if contract.epoch_budget == 1 else "Two"
    epoch_type = multifault_cycle_type_path(spec, "RecoveryAncestryTestEpochs")
    return f"{epoch_type}::{variant}"


def multifault_cycle_provenance_window(
    key: MultifaultKey,
    spec: MultifaultOverlaySpec,
) -> list[str] | None:
    contract = spec.cycle_epochs
    if contract is None:
        return None

    statements: list[str] = []
    if key == ("ANC-04", "accepted_nested_codec_before_cycle", None):
        statements.extend(
            (
                "let m2_cycle_left_accepted = repository"
                ".accepted_head_with_maintenance(&maintenance).unwrap();",
                "let m2_cycle_left_transaction_id = "
                "m2_cycle_left_accepted.transaction_id();",
                "let m2_cycle_left_verified_revision = "
                "m2_cycle_left_accepted.verified_revision();",
                "let m2_accepted_transaction_id = m2_cycle_left_transaction_id;",
                "let m2_secondary_cycle_entry_transaction_id = "
                "m2_accepted_transaction_id;",
            )
        )
    elif key == ("ANC-04", "verifier_nested_store_before_cycle", None):
        statements.extend(
            (
                "let m2_cycle_left_transaction_id = "
                "requests[0].head_claim.transaction_id;",
                "let m2_cycle_left_verified_revision = repository"
                ".verified_revision_with_maintenance("
                "&maintenance, m2_cycle_left_transaction_id).unwrap();",
                "let m2_secondary_cycle_entry_transaction_id = "
                "requests[0].head_claim.transaction_id;",
            )
        )
    elif key in {
        ("ANC-06", "ref_nested_store_before_cycle", None),
        ("COR-07", "ref_digest", "ref_digest_mismatch"),
    }:
        statements.extend(
            (
                "let m2_cycle_pristine_ref_path = branch_repository"
                ".checked_ref_path(&m2_fixture.selected_branch_name).unwrap();",
                "let m2_cycle_pristine_ref_bytes = "
                "::std::fs::read(&m2_cycle_pristine_ref_path).unwrap();",
                "let m2_cycle_pristine_ref = "
                "super::import_branch_ref(&m2_cycle_pristine_ref_bytes).unwrap();",
                "let m2_cycle_left_transaction_id = "
                "m2_cycle_pristine_ref.record.head_transaction_id;",
                "let m2_cycle_left_verified_revision = transaction_repository"
                ".verified_revision_with_maintenance("
                "&maintenance, m2_cycle_left_transaction_id).unwrap();",
            )
        )
        if key[0] == "ANC-06":
            statements.extend(
                (
                    "let m2_branch_head_transaction_id = m2_cycle_left_transaction_id;",
                    "let m2_secondary_cycle_entry_transaction_id = "
                    "m2_cycle_left_transaction_id;",
                )
            )
        else:
            statements.extend(
                (
                    "let m2_secondary_ref_target_transaction_id = "
                    "m2_cycle_left_transaction_id;",
                    "let m2_branch_ref_path = m2_cycle_pristine_ref_path.clone();",
                    "let m2_primary_path = m2_cycle_pristine_ref_path.clone();",
                    "let m2_pristine_primary_bytes = "
                    "m2_cycle_pristine_ref_bytes.clone();",
                )
            )
    else:
        fail(f"cycle provenance has no exact renderer for {key!r}")

    transaction_kind = (
        "super::TransactionKind"
        if spec.owner_source == TXN_PROVENANCE_SOURCE
        else "::sley_txn::TransactionKind"
    )
    statements.extend(
        (
            "let m2_cycle_left_parent_transaction_ids = "
            "m2_cycle_left_verified_revision.receipt().transaction.record"
            ".parent_transaction_ids.clone();",
            tagged_fixture_eq(
                "m2_cycle_left_has_one_parent",
                "m2_cycle_left_parent_transaction_ids.len()",
                "1_usize",
            ),
            "let m2_cycle_right_transaction_id = "
            "m2_cycle_left_parent_transaction_ids[0];",
            (
                "let m2_cycle_right_verified_revision = repository"
                ".verified_revision_with_maintenance("
                "&maintenance, m2_cycle_right_transaction_id).unwrap();"
                if spec.owner_source == TXN_PROVENANCE_SOURCE
                else "let m2_cycle_right_verified_revision = transaction_repository"
                ".verified_revision_with_maintenance("
                "&maintenance, m2_cycle_right_transaction_id).unwrap();"
            ),
            "let m2_cycle_right_parent_transaction_ids = "
            "m2_cycle_right_verified_revision.receipt().transaction.record"
            ".parent_transaction_ids.clone();",
            tagged_fixture_eq(
                "m2_cycle_right_has_one_parent",
                "m2_cycle_right_parent_transaction_ids.len()",
                "1_usize",
            ),
            "let m2_cycle_genesis_transaction_id = "
            "m2_cycle_right_parent_transaction_ids[0];",
            (
                "let m2_cycle_genesis_verified_revision = repository"
                ".verified_revision_with_maintenance("
                "&maintenance, m2_cycle_genesis_transaction_id).unwrap();"
                if spec.owner_source == TXN_PROVENANCE_SOURCE
                else "let m2_cycle_genesis_verified_revision = transaction_repository"
                ".verified_revision_with_maintenance("
                "&maintenance, m2_cycle_genesis_transaction_id).unwrap();"
            ),
            tagged_provenance_assert(
                "m2_cycle_genesis_has_no_parents",
                "m2_cycle_genesis_verified_revision.receipt().transaction.record"
                ".parent_transaction_ids.is_empty()",
            ),
            tagged_fixture_eq(
                "m2_cycle_genesis_kind",
                "m2_cycle_genesis_verified_revision.receipt().transaction.record"
                ".transaction_kind",
                f"{transaction_kind}::TrustedGenesis",
            ),
            tagged_fixture_ne(
                "m2_cycle_left_right_distinct_durable",
                "m2_cycle_left_transaction_id",
                "m2_cycle_right_transaction_id",
            ),
            tagged_fixture_ne(
                "m2_cycle_left_genesis_distinct_durable",
                "m2_cycle_left_transaction_id",
                "m2_cycle_genesis_transaction_id",
            ),
            tagged_fixture_ne(
                "m2_cycle_right_genesis_distinct_durable",
                "m2_cycle_right_transaction_id",
                "m2_cycle_genesis_transaction_id",
            ),
        )
    )

    if contract.primary_fault_node == "RIGHT_RECEIPT":
        statements.extend(
            (
                "let m2_cycle_right_receipt_path = repository"
                ".receipt_path(m2_cycle_right_transaction_id).unwrap();",
                "let m2_primary_path = m2_cycle_right_receipt_path.clone();",
                "let m2_pristine_primary_bytes = "
                "::std::fs::read(&m2_primary_path).unwrap();",
                "let m2_cycle_right_pristine_receipt = super::import_transaction_receipt("
                "&m2_pristine_primary_bytes).unwrap();",
                tagged_fixture_eq(
                    "m2_cycle_right_pristine_receipt_identity",
                    "m2_cycle_right_pristine_receipt.record.transaction_id",
                    "m2_cycle_right_transaction_id",
                ),
                "let m2_pristine_nested_state_root_bytes = "
                "m2_cycle_right_pristine_receipt.record.stored_state_root.clone();",
                "let m2_primary_fault_transaction_id = "
                "::core::option::Option::Some(m2_cycle_right_transaction_id);",
                "let m2_primary_fault_node: "
                "::core::option::Option<&'static str> = "
                '::core::option::Option::Some("right_receipt");',
            )
        )
    elif contract.primary_fault_node in {
        "RIGHT_OBJECT",
        "DEPTH_ONE_RIGHT_ANCESTOR_OBJECT",
    }:
        statements.extend(
            (
                "let m2_cycle_right_changed_object_ids = "
                "m2_cycle_right_verified_revision.receipt().transaction.record"
                ".changed_entity_bindings.iter().filter_map("
                "|binding| binding.postimage).collect::<::std::vec::Vec<_>>();",
                tagged_fixture_eq(
                    "m2_cycle_right_has_one_changed_postimage",
                    "m2_cycle_right_changed_object_ids.len()",
                    "1_usize",
                ),
                "let m2_cycle_right_changed_object_id = "
                "m2_cycle_right_changed_object_ids[0];",
                tagged_provenance_assert(
                    "m2_cycle_right_manifest_contains_changed_postimage",
                    "m2_cycle_right_verified_revision.receipt().record.object_manifest"
                    ".iter().any(|entry| entry.object_id == "
                    "m2_cycle_right_changed_object_id)",
                ),
                "let m2_cycle_left_changed_object_ids = "
                "m2_cycle_left_verified_revision.receipt().transaction.record"
                ".changed_entity_bindings.iter().filter_map("
                "|binding| binding.postimage).collect::<::std::vec::Vec<_>>();",
                tagged_provenance_assert(
                    "m2_cycle_left_excludes_right_changed_postimage",
                    "!m2_cycle_left_changed_object_ids"
                    ".contains(&m2_cycle_right_changed_object_id)",
                ),
                "let m2_primary_object_id = m2_cycle_right_changed_object_id;",
                (
                    "let m2_primary_path = repository.object_store"
                    ".object_path(m2_primary_object_id);"
                    if spec.owner_source == TXN_PROVENANCE_SOURCE
                    else "let m2_primary_path = ::sley_store::ObjectStore::new("
                    "owner_root.to_path_buf()).object_path(m2_primary_object_id);"
                ),
                "let m2_pristine_primary_bytes = "
                "::std::fs::read(&m2_primary_path).unwrap();",
                "let m2_pristine_primary_object_bytes = "
                "m2_pristine_primary_bytes.clone();",
                "let m2_primary_fault_transaction_id = "
                "::core::option::Option::Some(m2_cycle_right_transaction_id);",
                "let m2_primary_fault_node: "
                "::core::option::Option<&'static str> = "
                "::core::option::Option::Some("
                + (
                    '"right_object"'
                    if contract.primary_fault_node == "RIGHT_OBJECT"
                    else '"depth_one_right_ancestor_object"'
                )
                + ");",
            )
        )
    elif contract.primary_fault_node is None:
        statements.extend(
            (
                "let m2_primary_fault_transaction_id: "
                "::core::option::Option<::sley_id::TransactionId> = "
                "::core::option::Option::None;",
                "let m2_primary_fault_node: "
                "::core::option::Option<&'static str> = "
                "::core::option::Option::None;",
            )
        )
    else:
        fail(
            f"unsupported multifault primary cycle node {contract.primary_fault_node!r}"
        )

    digest_helper = snapshot_helper_path(
        spec.owner_source,
        "expected_recovery_ancestry_test_plan_digest",
    )
    statements.append(
        "let m2_cycle_expected_plan_digest = "
        f"{digest_helper}(owner_root, {multifault_cycle_epoch_expression(spec)}, "
        "m2_cycle_left_transaction_id, m2_cycle_right_transaction_id);"
    )
    return statements


def multifault_cycle_activation_identifiers(
    key: MultifaultKey,
    spec: MultifaultOverlaySpec,
) -> tuple[str, ...]:
    provenance_owned = {
        "m2_primary_fault_node",
        "m2_primary_fault_transaction_id",
        "m2_primary_object_id",
        "m2_primary_path",
        "m2_pristine_primary_bytes",
        "m2_pristine_primary_object_bytes",
        "m2_pristine_primary_observation",
    }
    return tuple(
        identifier
        for identifier in multifault_fixture_input_identifiers(
            key,
            spec,
            include_cycle_critical=True,
        )
        if identifier.startswith("m2_primary_") and identifier not in provenance_owned
    )


def multifault_secondary_baseline_and_primary_activation_window(
    key: MultifaultKey,
    spec: MultifaultOverlaySpec,
) -> list[str] | None:
    if spec.cycle_epochs is None:
        return None
    tree = snapshot_helper_path(spec.owner_source, "exact_tree_snapshot")
    statements = [
        "let m2_secondary_cycle_descriptor = [(m2_cycle_left_transaction_id, "
        "m2_cycle_right_transaction_id), (m2_cycle_right_transaction_id, "
        "m2_cycle_left_transaction_id)];",
        "let m2_secondary_logical_edges = m2_secondary_cycle_descriptor.to_vec();",
        f"let m2_secondary_only_owner_tree = {tree}(owner_root);",
        f"let m2_pristine_primary_observation = observe_{spec.fresh_fixture_recipe}_primary("
        "&fixture, &m2_fixture);",
        f"let m2_secondary_only_observation = observe_{spec.fresh_fixture_recipe}_secondary("
        "&fixture, &m2_fixture);",
        f"let m2_primary_activation = activate_{spec.fresh_fixture_recipe}_primary("
        "&fixture, &m2_fixture, &m2_primary_path);",
    ]
    statements.extend(
        f"let {identifier} = m2_primary_activation.{identifier}.clone();"
        for identifier in multifault_cycle_activation_identifiers(key, spec)
    )
    return statements


