def multifault_fixture_label(key: MultifaultKey) -> str:
    return "s20-530-m2-" + "-".join(
        component.lower().replace("_", "-")
        for component in key
        if component is not None
    )


def multifault_fixture_input_identifiers(
    key: MultifaultKey,
    spec: MultifaultOverlaySpec,
    *,
    include_cycle_critical: bool = False,
) -> tuple[str, ...]:
    texts = [
        *multifault_fixture_assertions("primary", spec.primary).values(),
        *multifault_fixture_assertions("secondary", spec.secondary).values(),
        multifault_distinctness_assertion(spec),
        *(
            multifault_probe_assertion("primary", fact, spec.winner)
            for fact in multifault_overlay_probe_fields(spec.primary)
        ),
        *(
            multifault_probe_assertion("secondary", fact, spec.loser)
            for fact in multifault_overlay_probe_fields(spec.secondary)
        ),
        *multifault_repair_statements(spec),
        multifault_operation_call(spec, 1),
        multifault_operation_call(spec, 2),
        *multifault_repair_assertions(spec).values(),
        *multifault_cycle_epoch_assertions(spec).values(),
    ]
    projected = rust_code_projection("\n".join(texts))
    identifiers = {
        semantic_rust_identifier(identifier)
        for identifier in re.findall(RUST_IDENTIFIER, projected)
        if semantic_rust_identifier(identifier).startswith("m2_")
    } - M2_DYNAMIC_IDENTIFIERS
    for identifier in ("requests", "transaction_limits_1", "ref_limits_1"):
        if code_contains_token(projected, identifier):
            identifiers.add(identifier)
    identifiers.discard("transaction_limits_2")
    identifiers.discard("ref_limits_2")
    if spec.cycle_epochs is not None:
        identifiers.update(
            {
                "m2_cycle_left_transaction_id",
                "m2_cycle_right_transaction_id",
                "m2_primary_fault_node",
                "m2_primary_fault_transaction_id",
            }
        )
        if not include_cycle_critical:
            identifiers = {
                identifier
                for identifier in identifiers
                if not identifier.startswith("m2_primary_")
                and identifier
                not in {
                    "m2_accepted_transaction_id",
                    "m2_branch_head_transaction_id",
                    "m2_branch_ref_path",
                    "m2_cycle_left_transaction_id",
                    "m2_cycle_expected_plan_digest",
                    "m2_cycle_right_changed_object_id",
                    "m2_cycle_right_receipt_path",
                    "m2_cycle_right_transaction_id",
                    "m2_pristine_primary_bytes",
                    "m2_pristine_nested_state_root_bytes",
                    "m2_pristine_primary_object_bytes",
                    "m2_pristine_primary_observation",
                    "m2_secondary_cycle_entry_transaction_id",
                    "m2_secondary_logical_edges",
                    "m2_secondary_only_observation",
                    "m2_secondary_only_owner_tree",
                    "m2_secondary_ref_target_transaction_id",
                }
            }
    return tuple(sorted(identifiers))


def multifault_probe_window(
    key: MultifaultKey,
    spec: MultifaultOverlaySpec,
    side: str,
    adapters: dict[tuple[MultifaultKey, str], str] | None = None,
) -> list[str]:
    tree = snapshot_helper_path(spec.owner_source, "exact_tree_snapshot")
    overlay = spec.primary if side == "primary" else spec.secondary
    selected_adapters = GROUPED_M2_PROBE_ADAPTERS if adapters is None else adapters
    probe = selected_adapters.get((key, side), overlay.probe_class)
    statements = [f"let m2_{side}_probe_before = {tree}(owner_root);"]
    if side == "secondary" and spec.cycle_epochs is not None:
        pass
    else:
        statements.extend(
            (
                f"let m2_{side}_probe_result = {probe}(&fixture, &m2_fixture);",
                f"let m2_{side}_probe_error = m2_{side}_probe_result"
                f'.expect_err("expected {side} multifault probe error");',
            )
        )
    statements.append(f"let m2_{side}_probe_after = {tree}(owner_root);")
    return statements


def grouped_m2_probe_adapter_call_problem(
    key: MultifaultKey,
    side: str,
    window: object,
    registry: tuple[tuple[MultifaultKey, str, str], ...] = (
        GROUPED_M2_PROBE_ADAPTER_REGISTRY
    ),
) -> str | None:
    adapters = {
        (item_key, item_side): adapter for item_key, item_side, adapter in registry
    }
    if len(adapters) != len(registry):
        return "adapter records collapse to duplicate key-side identities"
    if key not in MULTIFAULT_OVERLAYS or side not in {"primary", "secondary"}:
        return "probe window identity is outside the closed multifault domain"
    if not isinstance(window, list) or any(
        not isinstance(item, str) for item in window
    ):
        return "probe window is not one exact statement list"
    spec = MULTIFAULT_OVERLAYS[key]
    overlay = spec.primary if side == "primary" else spec.secondary
    if side == "secondary" and spec.cycle_epochs is not None:
        if len(window) != 2 or any("_probe_result =" in item for item in window):
            return "cycle secondary side emits a direct probe"
        if (key, side) in adapters:
            return "cycle secondary side has an adapter"
        return None
    selected = adapters.get((key, side), overlay.probe_class)
    expected_call = f"let m2_{side}_probe_result = {selected}(&fixture, &m2_fixture);"
    calls = tuple(item for item in window if "_probe_result =" in item)
    if calls != (expected_call,):
        return "adapter call identity or exact two-argument shape differs"
    if key in GROUPED_MULTIFAULT_CASES:
        if (key, side) not in adapters:
            return "grouped side lacks one adapter"
        if selected == overlay.probe_class:
            return "grouped side reuses its leaf probe as an adapter"
    elif (key, side) in adapters:
        return "non-grouped side gains grouped adapter authority"
    return None


def grouped_m2_probe_adapter_render_problem(
    registry: tuple[tuple[MultifaultKey, str, str], ...] = (
        GROUPED_M2_PROBE_ADAPTER_REGISTRY
    ),
) -> str | None:
    adapters = {(key, side): adapter for key, side, adapter in registry}
    if len(adapters) != len(registry):
        return "adapter records collapse to duplicate key-side identities"
    for key, spec in MULTIFAULT_OVERLAY_REGISTRY:
        for side in ("primary", "secondary"):
            window = multifault_probe_window(key, spec, side, adapters)
            if problem := grouped_m2_probe_adapter_call_problem(
                key, side, window, registry
            ):
                return f"{key!r} {side} {problem}"
    return None


def multifault_observation_window(
    spec: MultifaultOverlaySpec,
    ordinal: int,
    phase: str,
) -> list[str]:
    tree = snapshot_helper_path(spec.owner_source, "exact_tree_snapshot")
    observe_primary = f"observe_{spec.fresh_fixture_recipe}_primary"
    observe_secondary = f"observe_{spec.fresh_fixture_recipe}_secondary"
    suffix = f"{phase}_{ordinal}"
    statements: list[str] = []
    if phase == "before":
        receiver = (
            "repository"
            if spec.recovery_operation != "ref_recovery"
            else "branch_repository"
        )
        statements.extend(
            (
                f"let m2_receiver_identity_{ordinal} = "
                f"{receiver}.root().to_path_buf();",
                f"let m2_owner_root_{ordinal} = owner_root.to_path_buf();",
                f"let m2_guard_identity_{ordinal} = "
                "maintenance.repository_root().to_path_buf();",
                f"let m2_arguments_{ordinal} = "
                f"m2_fixture.m2_arguments_{ordinal}.clone();",
            )
        )
    statements.extend(
        (
            f"let m2_{phase}_{ordinal} = {tree}(owner_root);",
            f"let m2_primary_{suffix} = {observe_primary}(&fixture, &m2_fixture);",
            f"let m2_secondary_{suffix} = {observe_secondary}(&fixture, &m2_fixture);",
        )
    )
    return statements


def multifault_repair_observation_window(
    spec: MultifaultOverlaySpec,
) -> list[str]:
    tree = snapshot_helper_path(spec.owner_source, "exact_tree_snapshot")
    return [
        f"let m2_primary_after_repair = observe_{spec.fresh_fixture_recipe}_primary("
        "&fixture, &m2_fixture);",
        f"let m2_secondary_after_repair = observe_{spec.fresh_fixture_recipe}_secondary("
        "&fixture, &m2_fixture);",
        f"let m2_after_repair = {tree}(owner_root);",
    ]


def multifault_operation_bindings(
    key: MultifaultKey,
    spec: MultifaultOverlaySpec,
) -> dict[str, object]:
    receiver = (
        "repository"
        if spec.recovery_operation != "ref_recovery"
        else "branch_repository"
    )
    label = json.dumps(multifault_fixture_label(key))
    if spec.owner_source == TXN_PROVENANCE_SOURCE:
        receiver_bindings = [
            "let repository: &super::TransactionRepository = &fixture.repository;"
        ]
    else:
        receiver_bindings = [
            "let transaction_repository: &::sley_txn::TransactionRepository = "
            "&fixture.transactions;",
            "let branch_repository: &super::BranchRepository = &fixture.branches;",
        ]
    fixture_setup = [
        "::core::assert_eq!(owner_root, fixture.path());",
        f"let m2_fixture = prepare_{spec.fresh_fixture_recipe}(&fixture);",
    ]
    fixture_setup.extend(
        f"let {identifier} = m2_fixture.{identifier}.clone();"
        for identifier in multifault_fixture_input_identifiers(key, spec)
    )
    return {
        "fresh_fixture": f"let fixture = Fixture::new({label});",
        "receiver_bindings": receiver_bindings,
        "owner_root": f"let owner_root = {receiver}.root();",
        "fixture_setup": fixture_setup,
        "maintenance_guard": (
            f"let maintenance = {receiver}.acquire_exclusive_maintenance().unwrap();"
        ),
        "cycle_provenance_window": multifault_cycle_provenance_window(key, spec),
        "cycle_plan_install": multifault_cycle_plan_install_statement(spec),
        "secondary_baseline_and_primary_activation_window": (
            multifault_secondary_baseline_and_primary_activation_window(key, spec)
        ),
        "primary_probe_window": multifault_probe_window(key, spec, "primary"),
        "secondary_probe_window": multifault_probe_window(key, spec, "secondary"),
        "operation_1_pre_observation_window": multifault_observation_window(
            spec, 1, "before"
        ),
        "operation_1_result": (
            f"let m2_result_1 = {multifault_operation_call(spec, 1)};"
        ),
        "operation_1_error": (
            "let m2_error_1 = m2_result_1"
            '.expect_err("expected multifault precedence winner");'
        ),
        "operation_1_post_observation_window": multifault_observation_window(
            spec, 1, "after"
        ),
        "repair_window": list(multifault_repair_statements(spec)),
        "repair_observation_window": multifault_repair_observation_window(spec),
        "operation_2_pre_observation_window": multifault_observation_window(
            spec, 2, "before"
        ),
        "operation_2_result": (
            f"let m2_result_2 = {multifault_operation_call(spec, 2)};"
        ),
        "operation_2_error": (
            "let m2_error_2 = m2_result_2"
            '.expect_err("expected multifault precedence loser");'
        ),
        "operation_2_post_observation_window": multifault_observation_window(
            spec, 2, "after"
        ),
        "cycle_observation_drain": (multifault_cycle_observation_drain_statement(spec)),
    }


def multifault_authority_code_expression(
    authority: ErrorAuthority,
    error_name: str,
) -> str:
    if authority.variant.startswith("ancestry.verification."):
        return (
            f"match &{error_name} {{ "
            "super::RecoveryAncestryError::Verification(inner) => inner.code(), "
            '_ => "", }'
        )
    return f"{error_name}.code()"


def multifault_authority_assertions(
    authority: ErrorAuthority,
    relative: str,
    ordinal: int,
) -> tuple[str, str, str]:
    error_name = f"m2_error_{ordinal}"
    if authority.kind == "code":
        code_or_fields = tagged_fixture_eq(
            f"m2_operation_{ordinal}_code",
            multifault_authority_code_expression(authority, error_name),
            json.dumps(authority.code),
        )
        variant = tagged_provenance_assert(
            f"m2_operation_{ordinal}_variant",
            f"::core::matches!(&{error_name}, "
            f"{error_variant_pattern(relative, authority.variant)})",
        )
    elif authority.variant.endswith("ClaimMismatch"):
        code_or_fields = tagged_fixture_eq(
            f"m2_operation_{ordinal}_fields",
            f"match &{error_name} {{ "
            "super::RecoveryAncestryError::ClaimMismatch { request_index, "
            "claim_index } => (*request_index, *claim_index), "
            "_ => (::core::primitive::u64::MAX, ::core::primitive::u64::MAX), }",
            "(0_u64, 0_u64)",
        )
        variant = tagged_provenance_assert(
            f"m2_operation_{ordinal}_variant",
            f"::core::matches!(&{error_name}, "
            "super::RecoveryAncestryError::ClaimMismatch { "
            "request_index: 0, claim_index: 0 })",
        )
    else:
        code_or_fields = tagged_fixture_eq(
            f"m2_operation_{ordinal}_fields",
            f"::core::mem::discriminant(&{error_name})",
            "::core::mem::discriminant(&super::RecoveryAncestryError::Cycle)",
        )
        variant = tagged_provenance_assert(
            f"m2_operation_{ordinal}_variant",
            f"::core::matches!(&{error_name}, super::RecoveryAncestryError::Cycle)",
        )
    source_chain = tagged_fixture_eq(
        f"m2_operation_{ordinal}_source_chain",
        error_source_helper_call(relative, error_name, authority.source_chain),
        error_source_expected_literal(relative, authority.source_chain),
    )
    return code_or_fields, variant, source_chain


def multifault_result_assertions(
    spec: MultifaultOverlaySpec,
    relative: str,
) -> dict[str, str]:
    winner = multifault_authority_assertions(spec.winner, relative, 1)
    loser = multifault_authority_assertions(spec.loser, relative, 2)
    return {
        "operation_1_no_success": "::core::assert!(m2_result_1.is_err());",
        "operation_1_code_or_fields": winner[0],
        "operation_1_variant": winner[1],
        "operation_1_source_chain": winner[2],
        "operation_2_no_success": "::core::assert!(m2_result_2.is_err());",
        "operation_2_code_or_fields": loser[0],
        "operation_2_variant": loser[1],
        "operation_2_source_chain": loser[2],
    }


def multifault_base_error_semantic_assertions(
    key: MultifaultKey,
    relative: str,
) -> dict[str, str]:
    """Project the frozen operation-1 multifault proof into base error fields."""
    spec = MULTIFAULT_OVERLAYS[key]
    results = multifault_result_assertions(spec, relative)
    snapshots = multifault_snapshot_assertions()
    return {
        "expected_result": results["operation_1_code_or_fields"],
        "expected_variant": results["operation_1_variant"],
        "expected_source_chain": results["operation_1_source_chain"],
        "no_mutation": snapshots["operation_1_tree_unchanged"],
        "no_success_report": results["operation_1_no_success"],
    }


def multifault_repair_assertions(spec: MultifaultOverlaySpec) -> dict[str, str]:
    same_arguments = (
        "::core::assert_eq!(m2_arguments_1, m2_arguments_2);"
        if spec.operation_1_profile == spec.operation_2_profile
        else "::core::assert_eq!(m2_non_target_limit_fields_1, "
        "m2_non_target_limit_fields_2);"
    )
    return {
        "primary_repaired": (
            "::core::assert_eq!(m2_primary_after_repair, "
            "m2_pristine_primary_observation);"
        ),
        "secondary_preserved": (
            "::core::assert_eq!(m2_secondary_after_repair, "
            "m2_secondary_only_observation);"
        ),
        "repair_delta_exact": (
            "::core::assert_eq!(m2_after_repair, m2_secondary_only_owner_tree);"
        ),
        "same_receiver": (
            "::core::assert_eq!(m2_receiver_identity_1, m2_receiver_identity_2);"
        ),
        "same_owner_root": ("::core::assert_eq!(m2_owner_root_1, m2_owner_root_2);"),
        "same_guard": ("::core::assert_eq!(m2_guard_identity_1, m2_guard_identity_2);"),
        "same_arguments": same_arguments,
    }


def multifault_cycle_epoch_assertions(
    spec: MultifaultOverlaySpec,
) -> dict[str, str]:
    contract = spec.cycle_epochs
    if contract is None:
        return {}
    node_variant = {
        "RIGHT_RECEIPT": '"right_receipt"',
        "RIGHT_OBJECT": '"right_object"',
        "DEPTH_ONE_RIGHT_ANCESTOR_OBJECT": '"depth_one_right_ancestor_object"',
    }
    primary_fault_node = (
        "::core::option::Option::None"
        if contract.primary_fault_node is None
        else (
            f"::core::option::Option::Some({node_variant[contract.primary_fault_node]})"
        )
    )
    entry_expression = (
        "m2_secondary_ref_target_transaction_id"
        if spec.secondary.role == "BRANCH_ANCESTRY_GRAPH"
        and contract.primary_fault_node is None
        else "m2_secondary_cycle_entry_transaction_id"
    )
    primary_origin = (
        "::core::option::Option::None"
        if contract.primary_fault_node is None
        else ("::core::option::Option::Some(m2_cycle_right_transaction_id)")
    )
    return {
        "entry_is_left": tagged_fixture_eq(
            "m2_cycle_entry_is_left",
            entry_expression,
            "m2_cycle_left_transaction_id",
        ),
        "left_right_distinct": tagged_fixture_ne(
            "m2_cycle_left_right_distinct",
            "m2_cycle_left_transaction_id",
            "m2_cycle_right_transaction_id",
        ),
        "primary_origin_contract": tagged_fixture_eq(
            "m2_cycle_primary_origin_contract",
            "m2_primary_fault_transaction_id",
            primary_origin,
        ),
        "primary_fault_node": tagged_fixture_eq(
            "m2_cycle_primary_fault_node",
            "m2_primary_fault_node",
            primary_fault_node,
        ),
        "plan_owner_root": tagged_fixture_eq(
            "m2_cycle_plan_owner_root",
            "m2_cycle_plan_identity.owner_root()",
            "owner_root",
        ),
        "plan_digest": tagged_fixture_eq(
            "m2_cycle_plan_digest",
            "m2_cycle_plan_identity.digest()",
            "m2_cycle_expected_plan_digest",
        ),
        "epoch_budget": tagged_fixture_eq(
            "m2_cycle_epoch_budget",
            "m2_cycle_drain.epoch_budget()",
            f"{contract.epoch_budget}_u64",
        ),
        "operation_1_claims": tagged_fixture_eq(
            "m2_cycle_operation_1_claims",
            "m2_cycle_drain.operation_1().claims()",
            f"{contract.operation_1_claims}_u64",
        ),
        "operation_1_edge_counts": tagged_fixture_eq(
            "m2_cycle_operation_1_edge_counts",
            "m2_cycle_drain.operation_1().edge_counts()",
            f"({contract.operation_1_edge_counts[0]}_u64, "
            f"{contract.operation_1_edge_counts[1]}_u64)",
        ),
        "operation_2_claims": tagged_fixture_eq(
            "m2_cycle_operation_2_claims",
            "m2_cycle_drain.operation_2().claims()",
            f"{contract.operation_2_claims}_u64",
        ),
        "operation_2_edge_counts": tagged_fixture_eq(
            "m2_cycle_operation_2_edge_counts",
            "m2_cycle_drain.operation_2().edge_counts()",
            f"({contract.operation_2_edge_counts[0]}_u64, "
            f"{contract.operation_2_edge_counts[1]}_u64)",
        ),
        "epochs_exhausted": tagged_fixture_eq(
            "m2_cycle_epochs_exhausted",
            "m2_cycle_drain.remaining_epochs()",
            "0_u64",
        ),
    }


def multifault_snapshot_assertions() -> dict[str, str]:
    return {
        "secondary_probe_read_only": (
            "::core::assert_eq!(m2_secondary_probe_before, m2_secondary_probe_after);"
        ),
        "primary_probe_read_only": (
            "::core::assert_eq!(m2_primary_probe_before, m2_primary_probe_after);"
        ),
        "operation_1_tree_unchanged": ("::core::assert_eq!(m2_before_1, m2_after_1);"),
        "operation_1_primary_unchanged": (
            "::core::assert_eq!(m2_primary_before_1, m2_primary_after_1);"
        ),
        "operation_1_secondary_unchanged": (
            "::core::assert_eq!(m2_secondary_before_1, m2_secondary_after_1);"
        ),
        "operation_2_tree_unchanged": ("::core::assert_eq!(m2_before_2, m2_after_2);"),
        "operation_2_primary_unchanged": (
            "::core::assert_eq!(m2_primary_before_2, m2_primary_after_2);"
        ),
        "operation_2_secondary_unchanged": (
            "::core::assert_eq!(m2_secondary_before_2, m2_secondary_after_2);"
        ),
    }


def multifault_owned_entry_canary_assertions(
    key: MultifaultKey,
) -> dict[str, str]:
    if (key[0], key[1]) not in OWNED_ENTRY_MULTIFAULT_CASES or key[2] is not None:
        return {}
    return {
        "snapshot_unchanged": (
            "::core::assert_eq!(m2_owned_entry_canary_before_snapshot, "
            "m2_owned_entry_canary_after_snapshot);"
        ),
        "kind_unchanged": (
            "::core::assert_eq!(m2_owned_entry_canary_before_kind, "
            "m2_owned_entry_canary_after_kind);"
        ),
        "expected_kind": (
            '::core::assert_eq!(m2_owned_entry_canary_before_kind, "regular");'
        ),
    }


def multifault_owned_entry_canary_before_statements(
    key: MultifaultKey,
    spec: MultifaultOverlaySpec,
) -> tuple[str, ...]:
    if not multifault_owned_entry_canary_assertions(key):
        return ()
    helper = snapshot_helper_path(spec.owner_source, "exact_path_snapshot")
    return (
        (
            "let m2_owned_entry_canary_before_snapshot = "
            f"{helper}(&m2_primary_regular_canary_path);"
        ),
        (
            "let m2_owned_entry_canary_before_kind = "
            "m2_owned_entry_canary_before_snapshot.0;"
        ),
    )


def multifault_owned_entry_canary_after_statements(
    key: MultifaultKey,
    spec: MultifaultOverlaySpec,
) -> tuple[str, ...]:
    assertions = multifault_owned_entry_canary_assertions(key)
    if not assertions:
        return ()
    helper = snapshot_helper_path(spec.owner_source, "exact_path_snapshot")
    return (
        (
            "let m2_owned_entry_canary_after_snapshot = "
            f"{helper}(&m2_primary_regular_canary_path);"
        ),
        (
            "let m2_owned_entry_canary_after_kind = "
            "m2_owned_entry_canary_after_snapshot.0;"
        ),
        *assertions.values(),
    )


def multifault_statement_plan(
    key: MultifaultKey,
    spec: MultifaultOverlaySpec | None = None,
) -> tuple[str, ...]:
    selected = MULTIFAULT_OVERLAYS[key] if spec is None else spec
    bindings = multifault_operation_bindings(key, selected)
    primary_fixture = multifault_fixture_assertions("primary", selected.primary)
    secondary_fixture = multifault_fixture_assertions("secondary", selected.secondary)
    distinctness = multifault_distinctness_assertion(selected)
    primary_probes = {
        fact: multifault_probe_assertion("primary", fact, selected.winner)
        for fact in multifault_overlay_probe_fields(selected.primary)
    }
    secondary_probes = {
        fact: multifault_probe_assertion("secondary", fact, selected.loser)
        for fact in multifault_overlay_probe_fields(selected.secondary)
    }
    results = multifault_result_assertions(selected, selected.owner_source)
    repairs = multifault_repair_assertions(selected)
    cycles = multifault_cycle_epoch_assertions(selected)
    snapshots = multifault_snapshot_assertions()

    statements: list[str] = [str(bindings["fresh_fixture"])]
    receiver_bindings = bindings["receiver_bindings"]
    fixture_setup = bindings["fixture_setup"]
    assert isinstance(receiver_bindings, list)
    assert isinstance(fixture_setup, list)
    statements.extend(str(value) for value in receiver_bindings)
    statements.append(str(bindings["owner_root"]))
    statements.extend(str(value) for value in fixture_setup)
    statements.append(str(bindings["maintenance_guard"]))
    if selected.cycle_epochs is not None:
        cycle_provenance = bindings["cycle_provenance_window"]
        activation_window = bindings["secondary_baseline_and_primary_activation_window"]
        assert isinstance(cycle_provenance, list)
        assert isinstance(activation_window, list)
        statements.extend(str(value) for value in cycle_provenance)
        statements.extend(
            cycles[name]
            for name in (
                "entry_is_left",
                "left_right_distinct",
                "primary_origin_contract",
                "primary_fault_node",
            )
        )
        statements.append(str(bindings["cycle_plan_install"]))
        statements.extend(cycles[name] for name in ("plan_owner_root", "plan_digest"))
        statements.extend(str(value) for value in activation_window)
    statements.extend(primary_fixture.values())
    statements.extend(secondary_fixture.values())
    statements.append(distinctness)

    primary_probe_window = bindings["primary_probe_window"]
    secondary_probe_window = bindings["secondary_probe_window"]
    assert isinstance(primary_probe_window, list)
    assert isinstance(secondary_probe_window, list)
    statements.extend(str(value) for value in primary_probe_window)
    statements.extend(primary_probes.values())
    statements.append(snapshots["primary_probe_read_only"])
    statements.extend(str(value) for value in secondary_probe_window)
    statements.extend(secondary_probes.values())
    statements.append(snapshots["secondary_probe_read_only"])

    operation_1_pre = bindings["operation_1_pre_observation_window"]
    operation_1_post = bindings["operation_1_post_observation_window"]
    repair_window = bindings["repair_window"]
    repair_observations = bindings["repair_observation_window"]
    operation_2_pre = bindings["operation_2_pre_observation_window"]
    operation_2_post = bindings["operation_2_post_observation_window"]
    for window in (
        operation_1_pre,
        operation_1_post,
        repair_window,
        repair_observations,
        operation_2_pre,
        operation_2_post,
    ):
        assert isinstance(window, list)
    statements.extend(multifault_owned_entry_canary_before_statements(key, selected))
    statements.extend(str(value) for value in operation_1_pre)
    statements.extend(
        (
            str(bindings["operation_1_result"]),
            results["operation_1_no_success"],
            str(bindings["operation_1_error"]),
        )
    )
    statements.extend(str(value) for value in operation_1_post)
    statements.extend(multifault_owned_entry_canary_after_statements(key, selected))
    statements.extend(
        (
            results["operation_1_code_or_fields"],
            results["operation_1_variant"],
            results["operation_1_source_chain"],
            snapshots["operation_1_tree_unchanged"],
            snapshots["operation_1_primary_unchanged"],
            snapshots["operation_1_secondary_unchanged"],
        )
    )
    statements.extend(str(value) for value in repair_window)
    statements.extend(str(value) for value in repair_observations)
    statements.extend(
        repairs[name]
        for name in (
            "primary_repaired",
            "secondary_preserved",
            "repair_delta_exact",
        )
    )
    statements.extend(str(value) for value in operation_2_pre)
    statements.extend(
        repairs[name]
        for name in (
            "same_receiver",
            "same_owner_root",
            "same_guard",
            "same_arguments",
        )
    )
    statements.extend(
        (
            str(bindings["operation_2_result"]),
            results["operation_2_no_success"],
            str(bindings["operation_2_error"]),
        )
    )
    statements.extend(str(value) for value in operation_2_post)
    statements.extend(
        (
            results["operation_2_code_or_fields"],
            results["operation_2_variant"],
            results["operation_2_source_chain"],
            snapshots["operation_2_tree_unchanged"],
            snapshots["operation_2_primary_unchanged"],
            snapshots["operation_2_secondary_unchanged"],
        )
    )
    if selected.cycle_epochs is not None:
        statements.append(str(bindings["cycle_observation_drain"]))
        statements.extend(
            cycles[name]
            for name in (
                "epoch_budget",
                "operation_1_claims",
                "operation_1_edge_counts",
                "operation_2_claims",
                "operation_2_edge_counts",
                "epochs_exhausted",
            )
        )
    return tuple(statements)


def multifault_statement_plan_problem(
    key: MultifaultKey,
    spec: MultifaultOverlaySpec | None = None,
) -> str | None:
    selected = MULTIFAULT_OVERLAYS[key] if spec is None else spec
    statements = multifault_statement_plan(key, selected)
    if not statements or not statements[0].startswith("let fixture = Fixture::new("):
        return "does not begin with one checker-rendered fresh fixture"
    if len(set(normalize_rust_tokens(statement) for statement in statements)) != len(
        statements
    ):
        return "reuses an exact top-level statement"

    bound: set[str] = set()
    tracked = re.compile(
        r"(?<!\.)\b(?:m2_[A-Za-z0-9_]+|requests|"
        r"transaction_limits_[12]|ref_limits_[12])\b"
    )
    for ordinal, statement in enumerate(statements, 1):
        projected = rust_code_projection(statement)
        target_match = re.match(
            rf"\s*let\s+(?:mut\s+)?(?P<name>{RUST_IDENTIFIER})\b",
            projected,
        )
        target = (
            semantic_rust_identifier(target_match.group("name"))
            if target_match is not None
            else None
        )
        references = {
            semantic_rust_identifier(match.group(0))
            for match in tracked.finditer(projected)
        }
        if target is not None:
            references.discard(target)
        missing = sorted(references - bound)
        if missing:
            return f"statement {ordinal} consumes unbound locals: " + ", ".join(missing)
        if target is not None:
            if target in bound:
                return f"statement {ordinal} rebinds local {target!r}"
            bound.add(target)

    normalized = tuple(normalize_rust_tokens(statement) for statement in statements)
    install_token = normalize_rust_tokens("recovery_ancestry_test_hook::install(")
    drain_token = normalize_rust_tokens("recovery_ancestry_test_hook::take(")
    install_ordinals = tuple(
        index
        for index, statement in enumerate(normalized)
        if install_token in statement
    )
    drain_ordinals = tuple(
        index for index, statement in enumerate(normalized) if drain_token in statement
    )
    if selected.cycle_epochs is None:
        if install_ordinals or drain_ordinals:
            return "non-cycle plan gains cycle install or drain authority"
    else:
        if len(install_ordinals) != 1 or len(drain_ordinals) != 1:
            return "cycle plan does not contain one exact install and final drain"
        install_ordinal = install_ordinals[0]
        drain_ordinal = drain_ordinals[0]
        probe_ordinals = tuple(
            index
            for index, statement in enumerate(normalized)
            if "m2_primary_probe_result=" in statement
            or "m2_secondary_probe_result=" in statement
            or "m2_secondary_cycle_descriptor=" in statement
        )
        if not probe_ordinals or install_ordinal >= min(probe_ordinals):
            return "cycle plan installation does not precede every direct probe"
        if drain_ordinal >= len(statements) - 1:
            return "cycle plan lacks direct post-drain assertions"
        if any(
            token in "".join(normalized[:install_ordinal])
            for token in ("m2_primary_probe_result=", "m2_secondary_probe_result=")
        ):
            return "cycle plan consumes a probe before installation"
    return None


def multifault_probe_assertion(
    side: str,
    fact: str,
    authority: ErrorAuthority,
) -> str:
    if fact == "secondary_probe_branch_ancestry_cycle":
        return tagged_fixture_eq(
            fact,
            "m2_secondary_cycle_descriptor.as_slice()",
            "[(m2_cycle_left_transaction_id, m2_cycle_right_transaction_id), "
            "(m2_cycle_right_transaction_id, m2_cycle_left_transaction_id)]"
            ".as_slice()",
        )
    error_name = f"m2_{side}_probe_error"
    if authority.kind == "code":
        return tagged_fixture_eq(
            fact,
            f"{error_name}.code()",
            json.dumps(authority.code),
        )
    pattern = (
        "super::RecoveryAncestryError::ClaimMismatch { "
        "request_index: 0, claim_index: 0 }"
        if authority.fields
        else "super::RecoveryAncestryError::Cycle"
    )
    return tagged_provenance_assert(
        fact,
        f"::core::matches!(&{error_name}, {pattern})",
    )


def multifault_overlay_fact_fields(overlay: FaultOverlay) -> tuple[str, ...]:
    return tuple(fact for fact in overlay.required_facts if "_probe_" not in fact)


def multifault_overlay_probe_fields(overlay: FaultOverlay) -> tuple[str, ...]:
    return tuple(fact for fact in overlay.required_facts if "_probe_" in fact)


