def render_multifault_direct_assertion(
    fact: str,
    render: DirectAssertionRender,
) -> str:
    if render.kind == "eq" and render.right is not None:
        return tagged_fixture_eq(fact, render.left, render.right)
    if render.kind == "ne" and render.right is not None:
        return tagged_fixture_ne(fact, render.left, render.right)
    if render.kind == "assert" and render.right is None:
        return tagged_provenance_assert(fact, render.left)
    fail(f"malformed multifault fixture renderer for {fact!r}")


def multifault_fixture_assertion(side: str, fact: str) -> str:
    try:
        render = MULTIFAULT_FIXTURE_RENDER_SPECS[(side, fact)]
    except KeyError:
        fail(f"unknown multifault fixture fact {(side, fact)!r}")
    return render_multifault_direct_assertion(fact, render)


def multifault_fixture_assertions(
    side: str,
    overlay: FaultOverlay,
) -> dict[str, str]:
    return {
        fact: multifault_fixture_assertion(side, fact)
        for fact in multifault_overlay_fact_fields(overlay)
    }


def multifault_fixture_assertion_problem(
    assertion: object,
    side: str,
    fact: str,
) -> str | None:
    expected = multifault_fixture_assertion(side, fact)
    if assertion != expected:
        return "differs from checker rendering"
    if ASSERTION_MACRO.match(expected) is None:
        return "checker rendering is not one exact assertion macro"
    projected = rust_code_projection(expected)
    if json.dumps(fact) not in expected:
        return "does not carry its exact checker fact tag"
    if f"m2_{side}_" not in projected:
        return "does not inspect the exact fault-side observation"
    if re.search(r"\b(?:true|false)\b|\bproves\s*\(|_expected\b", projected):
        return "trusts a boolean or helper-supplied expected value"
    operands = exact_assert_eq_operands(expected)
    if operands is not None and code_only_normalized(
        operands[0]
    ) == code_only_normalized(operands[1]):
        return "is reflexive"
    predicate = exact_assert_predicate(expected)
    if predicate is not None and re.fullmatch(RUST_IDENTIFIER, predicate):
        return "trusts one local boolean"
    return None


def multifault_fixture_renderer_metadata_problem(
    render_specs: object = MULTIFAULT_FIXTURE_RENDER_SPECS,
) -> str | None:
    expected_keys = {
        (side, fact)
        for _key, spec in MULTIFAULT_OVERLAY_REGISTRY
        for side, overlay in (
            ("primary", spec.primary),
            ("secondary", spec.secondary),
        )
        for fact in multifault_overlay_fact_fields(overlay)
    }
    if (
        not isinstance(render_specs, dict)
        or len(expected_keys) != 43
        or set(render_specs) != expected_keys
    ):
        return "fixture renderer coverage differs from the exact 43 side/facts"
    for (side, fact), render in render_specs.items():
        if (
            not isinstance(render, DirectAssertionRender)
            or render.kind not in {"eq", "ne", "assert"}
            or not render.left
            or (render.kind == "assert") != (render.right is None)
        ):
            return f"{(side, fact)!r} has a malformed direct renderer"
        assertion = render_multifault_direct_assertion(fact, render)
        if problem := multifault_fixture_assertion_problem(assertion, side, fact):
            return f"{(side, fact)!r} {problem}"
    return None


def multifault_distinctness_assertion(spec: MultifaultOverlaySpec) -> str:
    if spec.distinctness_class in {
        "same_carrier_origin_semantics",
        "same_carrier_ref_semantics",
        "ref_carrier_bound_to_logical_graph_head",
    }:
        return tagged_fixture_eq(
            spec.distinctness_class,
            "m2_primary_carrier_path.as_path()",
            "m2_secondary_carrier_path.as_path()",
        )
    return tagged_fixture_ne(
        spec.distinctness_class,
        "m2_primary_locator.as_str()",
        "m2_secondary_locator.as_str()",
    )


def multifault_plan_sha256(
    key: MultifaultKey,
    _entry: dict[str, object],
) -> str:
    spec = MULTIFAULT_OVERLAYS[key]
    base_digest = None
    if key[2] is not None:
        base_digest = corruption_fixture_plan((key[0], key[1], str(key[2])))[0]
    payload = (
        "sley-s20-530-multifault-m2-plan-v1",
        MULTIFAULT_OVERLAY_REGISTRY_SHA256,
        base_digest,
        multifault_overlay_record(key, spec),
        multifault_operation_bindings(key, spec),
        multifault_fixture_assertions("primary", spec.primary),
        multifault_fixture_assertions("secondary", spec.secondary),
        {spec.distinctness_class: multifault_distinctness_assertion(spec)},
        {
            fact: multifault_probe_assertion("primary", fact, spec.winner)
            for fact in multifault_overlay_probe_fields(spec.primary)
        },
        {
            fact: multifault_probe_assertion("secondary", fact, spec.loser)
            for fact in multifault_overlay_probe_fields(spec.secondary)
        },
        multifault_result_assertions(spec, spec.owner_source),
        multifault_repair_assertions(spec),
        multifault_cycle_epoch_assertions(spec),
        multifault_snapshot_assertions(),
        multifault_owned_entry_canary_assertions(key),
        tuple(
            normalize_rust_tokens(statement)
            for statement in multifault_statement_plan(key, spec)
        ),
    )
    return canonical_json_sha256(payload)


def multifault_evidence_problem(
    row_id: str,
    subcase_id: str,
    entry: dict[str, object],
    relative: str,
    leaf_id: str | None = None,
) -> str | None:
    key = multifault_key(row_id, subcase_id, leaf_id)
    try:
        spec = MULTIFAULT_OVERLAYS[key]
    except KeyError:
        return "is not a frozen multifault case"
    if relative != spec.owner_source:
        return "mapped test owner differs from multifault owner"
    if problem := multifault_statement_plan_problem(key, spec):
        return f"checker-rendered statement plan {problem}"
    keys = tuple(entry)
    try:
        start = keys.index(MULTIFAULT_M2_EVIDENCE_FIELDS[0])
    except ValueError:
        return "lacks multifault M2 evidence fields"
    if keys[start : start + len(MULTIFAULT_M2_EVIDENCE_FIELDS)] != (
        MULTIFAULT_M2_EVIDENCE_FIELDS
    ):
        return "multifault M2 evidence fields/order differ"
    expected_bindings = multifault_operation_bindings(key, spec)
    expected_results = multifault_result_assertions(spec, relative)
    expected_repairs = multifault_repair_assertions(spec)
    expected_cycle_epochs = multifault_cycle_epoch_assertions(spec)
    expected_snapshots = multifault_snapshot_assertions()
    expected_owned_entry_canary = multifault_owned_entry_canary_assertions(key)
    exact_groups = (
        ("m2_operation_bindings", M2_OPERATION_BINDING_FIELDS, expected_bindings),
        ("m2_result_assertions", M2_RESULT_ASSERTION_FIELDS, expected_results),
        ("m2_repair_assertions", M2_REPAIR_ASSERTION_FIELDS, expected_repairs),
        (
            "m2_cycle_epoch_assertions",
            M2_CYCLE_EPOCH_ASSERTION_FIELDS if spec.cycle_epochs is not None else (),
            expected_cycle_epochs,
        ),
        ("m2_snapshot_assertions", M2_SNAPSHOT_ASSERTION_FIELDS, expected_snapshots),
        (
            "m2_owned_entry_canary_assertions",
            (
                M2_OWNED_ENTRY_CANARY_ASSERTION_FIELDS
                if expected_owned_entry_canary
                else ()
            ),
            expected_owned_entry_canary,
        ),
    )
    for field, order, expected in exact_groups:
        actual = entry.get(field)
        if not isinstance(actual, dict) or tuple(actual) != order or actual != expected:
            return f"{field} differs from checker rendering"
    assertions = entry.get("assertions")
    if not isinstance(assertions, list):
        return "lacks one assertion list"
    fixture_groups = (
        ("primary", spec.primary, spec.winner),
        ("secondary", spec.secondary, spec.loser),
    )
    all_assertions: list[str] = []
    for side, overlay, authority in fixture_groups:
        fixture_field = f"{side}_fixture_assertions"
        expected_fixture = multifault_fixture_assertions(side, overlay)
        fixture_mapping = entry.get(fixture_field)
        if (
            not isinstance(fixture_mapping, dict)
            or tuple(fixture_mapping) != tuple(expected_fixture)
            or fixture_mapping != expected_fixture
        ):
            return f"{fixture_field} differs from checker rendering"
        for fact, assertion in expected_fixture.items():
            if problem := multifault_fixture_assertion_problem(assertion, side, fact):
                return f"{fixture_field}/{fact} {problem}"
            all_assertions.append(assertion)
        probe_field = f"{side}_probe_assertions"
        expected_probe = {
            fact: multifault_probe_assertion(side, fact, authority)
            for fact in multifault_overlay_probe_fields(overlay)
        }
        probe_mapping = entry.get(probe_field)
        if (
            not isinstance(probe_mapping, dict)
            or tuple(probe_mapping) != tuple(expected_probe)
            or probe_mapping != expected_probe
        ):
            return f"{probe_field} differs from checker rendering"
        all_assertions.extend(expected_probe.values())
    expected_distinctness = {
        spec.distinctness_class: multifault_distinctness_assertion(spec)
    }
    if entry.get("distinctness_assertions") != expected_distinctness:
        return "distinctness assertions differ from checker rendering"
    all_assertions.extend(expected_distinctness.values())
    for mapping in (
        expected_results,
        expected_repairs,
        expected_cycle_epochs,
        expected_snapshots,
        expected_owned_entry_canary,
    ):
        all_assertions.extend(mapping.values())
    if len(set(all_assertions)) != len(all_assertions):
        return "multifault M2 assertions are not unique"
    if any(assertion not in assertions for assertion in all_assertions):
        return "one multifault M2 assertion is absent from evidence assertions"
    if entry.get("multifault_plan_sha256") != multifault_plan_sha256(key, entry):
        return "multifault M2 plan digest differs"
    return None


def multifault_operation_binding_problem(
    body: str,
    row_id: str,
    subcase_id: str,
    entry: dict[str, object],
    leaf_id: str | None = None,
) -> str | None:
    key = multifault_key(row_id, subcase_id, leaf_id)
    spec = MULTIFAULT_OVERLAYS[key]
    bindings = multifault_operation_bindings(key, spec)
    if entry.get("m2_operation_bindings") != bindings:
        return "operation binding evidence differs from checker rendering"
    expected_plan = multifault_statement_plan(key, spec)
    actual_ranges = top_level_statement_ranges(body)
    actual_plan = tuple(statement for _start, _end, statement in actual_ranges)
    normalized_expected = tuple(
        normalize_rust_tokens(statement) for statement in expected_plan
    )
    normalized_actual = tuple(
        normalize_rust_tokens(statement) for statement in actual_plan
    )
    if row_id.startswith("LIMIT-"):
        starts = tuple(
            index
            for index, statement in enumerate(normalized_actual)
            if statement == normalized_expected[0]
        )
        if len(starts) != 1:
            return "appended limit multifault proof start is missing or ambiguous"
        normalized_actual = normalized_actual[starts[0] :]
    if normalized_actual != normalized_expected:
        shared = min(len(normalized_actual), len(normalized_expected))
        mismatch = next(
            (
                index
                for index in range(shared)
                if normalized_actual[index] != normalized_expected[index]
            ),
            shared,
        )
        return (
            "mapped M2 body differs from the complete checker-rendered statement "
            f"plan at ordinal {mismatch + 1}; expected "
            f"{len(normalized_expected)} statements and observed "
            f"{len(normalized_actual)}"
        )
    if not actual_ranges:
        return "mapped M2 body contains no top-level statements"
    if rust_code_projection(body[: actual_ranges[0][0]]).strip():
        return "mapped M2 body executes code before its fresh fixture"
    if rust_code_projection(body[actual_ranges[-1][1] :]).strip():
        return "mapped M2 body executes code after its final assertion"
    return None


def require_multifault_evidence(
    row_id: str,
    subcase_id: str,
    entry: dict[str, object],
    relative: str,
    source: str,
    leaf_id: str | None = None,
) -> None:
    label = (
        f"{row_id}/{subcase_id}"
        if leaf_id is None
        else f"{row_id}/{subcase_id}/{leaf_id}"
    )
    if problem := multifault_evidence_problem(
        row_id,
        subcase_id,
        entry,
        relative,
        leaf_id,
    ):
        fail(f"{label} {problem}")
    tests = entry.get("tests")
    if not isinstance(tests, list) or len(tests) != 1 or not isinstance(tests[0], str):
        fail(f"{label} lacks one exact multifault test")
    definition = exact_test_definition(source, tests[0])
    if definition is None:
        fail(f"{label} cannot isolate its multifault test")
    if problem := multifault_operation_binding_problem(
        definition[0],
        row_id,
        subcase_id,
        entry,
        leaf_id,
    ):
        fail(f"{label} multifault operation binding differs: {problem}")


def require_evidence_tests(
    row_id: str,
    subcase_id: str | None,
    entry: object,
    sources: dict[str, str],
    used_tests: list[str],
    leaf_id: str | None = None,
) -> tuple[str, str]:
    label = (
        row_id
        if subcase_id is None
        else f"{row_id}/{subcase_id}"
        if leaf_id is None
        else f"{row_id}/{subcase_id}/{leaf_id}"
    )
    if (
        not isinstance(entry, dict)
        or entry.get("result") != "PASS"
        or entry.get("fresh_fixture") is not True
    ):
        fail(f"{label} lacks a fresh-fixture assertion")
    tests = entry.get("tests")
    if not isinstance(tests, list) or len(tests) != 1 or not isinstance(tests[0], str):
        fail(f"{label} must map to exactly one Rust test function")
    test = tests[0]
    if test in used_tests:
        fail(f"Rust test function {test!r} is mapped more than once")
    used_tests.append(test)
    allowed = allowed_test_sources(row_id)
    bodies = [
        (relative, definition[0], definition[1])
        for relative in allowed
        if (definition := exact_test_definition(sources[relative], test)) is not None
    ]
    if len(bodies) != 1:
        fail(f"{label} does not map to one exact owning #[test] fn {test}")
    assertions = entry.get("assertions")
    if (
        not isinstance(assertions, list)
        or not assertions
        or any(
            not isinstance(assertion, str)
            or ASSERTION_MACRO.match(assertion) is None
            or not assertion.rstrip().endswith(");")
            for assertion in assertions
        )
    ):
        fail(f"{label} lacks exact assertion-macro snippets")
    owner, body, local_qualified = bodies[0]
    body_code = rust_code_projection(body)
    if problem := mapped_test_control_flow_problem(body):
        fail(f"{label} mapped test contains {problem}")
    if re.search(r"#\s*\[\s*cfg(?:_attr)?\s*\(", body_code):
        fail(f"{label} mapped test contains a conditional statement")
    if problem := unsafe_mapped_test_macro_problem(body):
        fail(f"{label} mapped test has unsafe macro authority: {problem}")
    for assertion in assertions:
        if not exact_direct_statement_present(body, assertion):
            fail(
                f"{label} assertion is not one exact direct statement in {test}: "
                f"{assertion!r}"
            )
    return owner, qualified_test_name(owner, local_qualified)


def mapped_test_body_manifest(
    tests: list[str],
    sources: dict[str, str],
    qualified_tests: dict[str, str],
) -> dict[str, dict[str, str]]:
    manifest: dict[str, dict[str, str]] = {}
    for test in tests:
        definitions = tuple(
            (relative, body)
            for relative, source in sources.items()
            if (body := exact_test_body(source, test)) is not None
        )
        if len(definitions) != 1:
            fail(f"mapped test {test!r} body lacks one exact review owner")
        relative, body = definitions[0]
        try:
            qualified = qualified_tests[test]
        except KeyError:
            fail(f"mapped test {test!r} lacks an exact qualified name")
        manifest[test] = {
            "source": relative,
            "qualified_test": qualified,
            "body_sha256": hashlib.sha256(body.encode("utf-8")).hexdigest(),
        }
    return manifest


def limit_runtime_helper_owner(spec: LimitRuntimeCaseSpec, function: str) -> str:
    if function == spec.setup_helper or function in LIMIT_RUNTIME_PROBE_HELPERS:
        return "mod:tests"
    profile = limit_profile_map().get(spec.profile_constructor)
    if profile is not None and function == profile.get("helper"):
        return "<crate>"
    fail(
        f"{spec.row_id}/{spec.subcase_id} has an unowned limit runtime helper "
        f"{function!r}"
    )


def limit_runtime_helper_body_key(relative: str, owner: str, function: str) -> str:
    return f"{relative}:{owner}:{function}"


def limit_runtime_helper_body_manifest(
    sources: dict[str, str],
) -> dict[str, dict[str, str]]:
    authorities: dict[str, tuple[str, str, str]] = {}
    for spec in LIMIT_RUNTIME_CASE_SPECS.values():
        for function in spec.helper_functions:
            owner = limit_runtime_helper_owner(spec, function)
            key = limit_runtime_helper_body_key(spec.owner_source, owner, function)
            authorities[key] = (spec.owner_source, owner, function)
    manifest: dict[str, dict[str, str]] = {}
    for key in sorted(authorities):
        relative, owner, function = authorities[key]
        source = sources.get(relative)
        if not isinstance(source, str):
            fail(f"limit runtime helper source is absent: {relative}")
        body = rust_named_function_raw_body(source, function, owner)
        if body is None:
            fail(f"cannot isolate limit runtime helper body: {key}")
        attribute_chain = limit_named_function_attribute_chain(source, function, owner)
        if attribute_chain is None:
            fail(f"cannot isolate limit runtime helper attribute chain: {key}")
        manifest[key] = {
            "source": relative,
            "owner": owner,
            "function": function,
            "attribute_chain_sha256": hashlib.sha256(
                attribute_chain.encode("utf-8")
            ).hexdigest(),
            "body_sha256": hashlib.sha256(body.encode("utf-8")).hexdigest(),
        }
    return manifest


def limit_runtime_probe_binding_problem(sources: dict[str, str]) -> str | None:
    checked: set[tuple[str, str]] = set()
    for spec in LIMIT_RUNTIME_CASE_SPECS.values():
        profile = limit_profile_map().get(spec.profile_constructor)
        if profile is None:
            return f"{spec.qualified_field} lacks a limit probe profile"
        helper = profile.get("helper")
        helper_body = profile.get("helper_body")
        if not isinstance(helper, str) or not isinstance(helper_body, str):
            return f"{spec.qualified_field} limit probe helper metadata differs"
        authority = (spec.owner_source, helper)
        if authority in checked:
            continue
        checked.add(authority)
        source = sources.get(spec.owner_source)
        if not isinstance(source, str):
            return f"limit probe source is absent: {spec.owner_source}"
        raw_body = rust_named_function_raw_body(source, helper, "<crate>")
        if raw_body is None:
            return f"cannot isolate limit probe comparison helper {helper}"
        expected = limit_runtime_instrumented_helper_body(helper_body)
        if normalize_rust_tokens(raw_body) != normalize_rust_tokens(expected):
            return f"{spec.owner_source}::{helper} runtime probe binding differs"
    return None


def limit_runtime_case_manifest(
    row_map: dict[str, object],
    mapped_test_bodies: dict[str, dict[str, str]],
    helper_bodies: dict[str, dict[str, str]],
) -> dict[str, dict[str, object]]:
    manifest: dict[str, dict[str, object]] = {}
    for (row_id, subcase_id), spec in LIMIT_RUNTIME_CASE_SPECS.items():
        row = row_map.get(row_id)
        subcases = row.get("subcases") if isinstance(row, dict) else None
        subcase = subcases.get(subcase_id) if isinstance(subcases, dict) else None
        tests = subcase.get("tests") if isinstance(subcase, dict) else None
        if (
            not isinstance(tests, list)
            or len(tests) != 1
            or not isinstance(tests[0], str)
        ):
            fail(f"{row_id}/{subcase_id} lacks one runtime case test")
        test = tests[0]
        test_record = mapped_test_bodies.get(test)
        if not isinstance(test_record, dict) or tuple(test_record) != (
            "source",
            "qualified_test",
            "body_sha256",
        ):
            fail(f"{row_id}/{subcase_id} runtime case test body is unreviewed")
        if test_record.get("source") != spec.owner_source:
            fail(f"{row_id}/{subcase_id} runtime case test owner differs")
        helper_records: dict[str, dict[str, str]] = {}
        for function in spec.helper_functions:
            owner = limit_runtime_helper_owner(spec, function)
            key = limit_runtime_helper_body_key(spec.owner_source, owner, function)
            helper_record = helper_bodies.get(key)
            if not isinstance(helper_record, dict):
                fail(f"{row_id}/{subcase_id} helper body is unreviewed: {function}")
            helper_records[key] = helper_record
        identity = f"{row_id}/{subcase_id}"
        manifest[identity] = {
            "qualified_field": spec.qualified_field,
            "owner_source": spec.owner_source,
            "operation_kind": spec.operation_kind,
            "profile_constructor": spec.profile_constructor,
            "profile_field": spec.profile_field,
            "frozen_constant": spec.frozen_constant,
            "frozen_default": spec.frozen_default,
            "exact_cardinality": spec.exact_cardinality,
            "plus_one_cardinality": spec.plus_one_cardinality,
            "event_sites": list(spec.event_ids),
            "test": test,
            "qualified_test": test_record["qualified_test"],
            "test_body_sha256": test_record["body_sha256"],
            "helper_bodies": helper_records,
        }
    return manifest


def limit_runtime_site_proof_manifest(
    runtime_cases: dict[str, dict[str, object]],
    owner_bodies: dict[str, dict[str, str]],
) -> dict[str, dict[str, object]]:
    proofs: dict[str, dict[str, object]] = {}
    for spec in LIMIT_RUNTIME_CASE_SPECS.values():
        if len(spec.event_ids) == 1:
            continue
        case_id = f"{spec.row_id}/{spec.subcase_id}"
        runtime_case = runtime_cases.get(case_id)
        if not isinstance(runtime_case, dict):
            fail(f"{case_id} dual-site runtime case is absent")
        event_owner_bodies: dict[str, dict[str, str]] = {}
        for event_id in spec.event_ids:
            event = LIMIT_EVENT_SPECS[event_id]
            owner_key = limit_event_owner_body_key(event)
            owner_record = owner_bodies.get(owner_key)
            if not isinstance(owner_record, dict):
                fail(f"{case_id} event owner body is absent: {event_id}")
            event_owner_bodies[event_id] = owner_record
        proofs[spec.qualified_field] = {
            "row_id": spec.row_id,
            "subcase_id": spec.subcase_id,
            "event_sites": list(spec.event_ids),
            "test": runtime_case["test"],
            "test_body_sha256": runtime_case["test_body_sha256"],
            "setup_helper": spec.setup_helper,
            "setup_helper_body_sha256": runtime_case["helper_bodies"][
                limit_runtime_helper_body_key(
                    spec.owner_source,
                    "mod:tests",
                    spec.setup_helper,
                )
            ]["body_sha256"],
            "event_owner_bodies": event_owner_bodies,
        }
    return proofs


def limit_event_owner_body_key(spec: LimitEventSpec) -> str:
    return ":".join(spec.site)


def limit_event_owner_body_manifest(
    sources: dict[str, str],
    specs: dict[str, LimitEventSpec] = LIMIT_EVENT_SPECS,
) -> dict[str, dict[str, str]]:
    manifest: dict[str, dict[str, str]] = {}
    for spec in specs.values():
        relative, owner, function = spec.site
        key = limit_event_owner_body_key(spec)
        if key in manifest:
            continue
        source = sources.get(relative)
        if not isinstance(source, str):
            fail(f"limit-event owner source is absent: {relative}")
        production = normal_build_source(source)
        body = rust_named_function_raw_body(production, function, owner)
        if body is None:
            fail(f"cannot isolate limit-event owner body: {key}")
        attribute_chain = limit_named_function_attribute_chain(
            production,
            function,
            owner,
        )
        if attribute_chain is None:
            fail(f"cannot isolate limit-event owner attribute chain: {key}")
        manifest[key] = {
            "source": relative,
            "owner": owner,
            "function": function,
            "attribute_chain_sha256": hashlib.sha256(
                attribute_chain.encode("utf-8")
            ).hexdigest(),
            "body_sha256": hashlib.sha256(body.encode("utf-8")).hexdigest(),
        }
    return manifest


